        print('param',prm.get('name'),prm.get('in'),prm.get('required'))
    for code,r in op.get('responses',{}).items():
        sch=r.get('content',{}).get('application/json',{}).get('schema',{})
        print('RESP',code,json.dumps(sch))
"

