def find(opid):
    for p,v in ops.items():
        for m,op in v.items():
            if op.get('operationId')==opid:
                return p,m,op
    return None
for w in want:
    r=find(w)
    if not r:
        print('MISSING', w); continue
    p,m,op=r
    print('='*70)
    print(m.upper(), p, '->', op.get('operationId'))
    rb=op.get('requestBody',{})
    if rb:
        sch=rb.get('content',{}).get('application/json',{}).get('schema',{})
        print('REQ required=',rb.get('required'),'schema=',json.dumps(sch))
    for prm in op.get('parameters',[]):
        print('param',prm.get('name'),prm.get('in'),prm.get('required'))
    for code,r2 in op.get('responses',{}).items():
        sch=r2.get('content',{}).get('application/json',{}).get('schema',{})
        print('RESP',code,json.dumps(sch))

