package main

import (
	"context"
	"crypto/rand"
	"crypto/subtle"
	"encoding/hex"
	"errors"
	"fmt"
	"log"
	"sync"
	"time"

	"github.com/jackc/pgx/v5"
	"github.com/jackc/pgx/v5/pgxpool"
	"go.mongodb.org/mongo-driver/mongo"
	"go.mongodb.org/mongo-driver/mongo/options"
)

type App struct {
	cfg    Config
	pg     *pgxpool.Pool
	mongo  *mongo.Client
	mdb    *mongo.Database
	rtMu   sync.Mutex
}

func NewApp(ctx context.Context, cfg Config) (*App, error) {
	pool, err := pgxpool.New(ctx, cfg.PostgresURL)
	if err != nil {
		return nil, fmt.Errorf("pg connect: %w", err)
	}
	if err := pool.Ping(ctx); err != nil {
		return nil, fmt.Errorf("pg ping: %w", err)
	}
	mclient, err := mongo.Connect(ctx, options.Client().ApplyURI(cfg.MongoURI))
	if err != nil {
		return nil, fmt.Errorf("mongo connect: %w", err)
	}
	if err := mclient.Ping(ctx, nil); err != nil {
		return nil, fmt.Errorf("mongo ping: %w", err)
	}
	a := &App{
		cfg:   cfg,
		pg:    pool,
		mongo: mclient,
		mdb:   mclient.Database("arena"),
	}
	if err := a.Migrate(ctx); err != nil {
		return nil, fmt.Errorf("migrate: %w", err)
	}
	if err := a.MaterializeMongo(ctx); err != nil {
		return nil, fmt.Errorf("materialize mongo: %w", err)
	}
	if err := a.SeedDefaults(ctx); err != nil {
		return nil, fmt.Errorf("seed: %w", err)
	}
	return a, nil
}

func (a *App) Close() {
	if a.pg != nil {
		a.pg.Close()
	}
	if a.mongo != nil {
		_ = a.mongo.Disconnect(context.Background())
	}
}

// tx runs fn inside a serializable transaction with retry on snapshot conflict.
func (a *App) tx(ctx context.Context, fn func(pgx.Tx) error) error {
	for i := 0; i < 4; i++ {
		err := func() error {
			t, err := a.pg.BeginTx(ctx, pgx.TxOptions{IsoLevel: pgx.Serializable})
			if err != nil {
				return err
			}
			defer t.Rollback(ctx)
			if err := fn(t); err != nil {
				return err
			}
			return t.Commit(ctx)
		}()
		if err == nil {
			return nil
		}
		if isSnapshotConflict(err) {
			time.Sleep(time.Duration(20<<(i)) * time.Millisecond)
			continue
		}
		return err
	}
	return errors.New("concurrent_conflict")
}

func isSnapshotConflict(err error) bool {
	s := err.Error()
	return contains(s, "could not serialize access") || contains(s, "40P01") || contains(s, "40001") || contains(s, "concurrent_conflict")
}

func contains(s, sub string) bool {
	return len(sub) == 0 || (len(s) >= len(sub) && (func() bool {
		for i := 0; i+len(sub) <= len(s); i++ {
			if s[i:i+len(sub)] == sub {
				return true
			}
		}
		return false
	})())
}

func newToken() string {
	b := make([]byte, 24)
	rand.Read(b)
	return hex.EncodeToString(b)
}

func newUUID() string {
	return uuidStr()
}

func uuidStr() string {
	b := make([]byte, 16)
	rand.Read(b)
	b[6] = (b[6] & 0x0f) | 0x40
	b[8] = (b[8] & 0x3f) | 0x80
	return fmt.Sprintf("%x-%x-%x-%x-%x", b[0:4], b[4:6], b[6:8], b[8:10], b[10:16])
}

func secureEq(a, b string) bool {
	return subtle.ConstantTimeCompare([]byte(a), []byte(b)) == 1
}

func ptr[T any](v T) *T { return &v }

func nowRFC() string { return time.Now().UTC().Format(time.RFC3339Nano) }

var _ = log.Printf

