package main

import (
	"context"

	"go.mongodb.org/mongo-driver/bson"
	"go.mongodb.org/mongo-driver/mongo/options"
)

// MaterializeMongo creates collections and indexes so reset materializes structure.
func (a *App) MaterializeMongo(ctx context.Context) error {
	db := a.mdb
	colls := []string{"audit_events", "realtime_events", "audit_requests"}
	for _, c := range colls {
		if err := db.CreateCollection(ctx, c); err != nil {
			// ignore already exists
			if !isMongoAlreadyExists(err) {
				return err
			}
		}
	}
	indexes := map[string][]mongoIndex{
		"audit_events": {
			{Keys: bson.D{{Key: "timestamp", Value: 1}}},
			{Keys: bson.D{{Key: "entity_type", Value: 1}, {Key: "entity_id", Value: 1}}},
			{Keys: bson.D{{Key: "user_id", Value: 1}, {Key: "timestamp", Value: -1}}},
			{Keys: bson.D{{Key: "action", Value: 1}}},
		},
		"realtime_events": {
			{Keys: bson.D{{Key: "seq", Value: 1}}, Unique: true},
			{Keys: bson.D{{Key: "timestamp", Value: 1}}},
			{Keys: bson.D{{Key: "entity_type", Value: 1}, {Key: "timestamp", Value: -1}}},
		},
		"audit_requests": {
			{Keys: bson.D{{Key: "request_id", Value: 1}}},
		},
	}
	for coll, idxs := range indexes {
		c := db.Collection(coll)
		for _, ix := range idxs {
			opts := options.Index()
			if ix.Unique {
				opts.SetUnique(true)
			}
			_, err := c.Indexes().CreateOne(ctx, ix, opts)
			if err != nil && !isMongoAlreadyExists(err) {
				return err
			}
		}
	}
	return nil
}

type mongoIndex struct {
	Keys   any
	Unique bool
}

func isMongoAlreadyExists(err error) bool {
	s := err.Error()
	return contains(s, "already exists") || contains(s, "NamespaceExists")
}

func (a *App) ResetMongo(ctx context.Context) error {
	colls := []string{"audit_events", "realtime_events", "audit_requests"}
	for _, c := range colls {
		_ = a.mdb.Collection(c).Drop(ctx)
	}
	return a.MaterializeMongo(ctx)
}

