// EnsureInitialAdmin creates the first administrator account when no users exist.
func (a *App) EnsureInitialAdmin(ctx context.Context) error {
	var count int
	if err := a.pg.QueryRow(ctx, `SELECT COUNT(*) FROM users`).Scan(&count); err != nil {
		return err
	}
	if count > 0 {
		return nil
	}
	if a.cfg.AdminUser == "" || a.cfg.AdminPass == "" {
		return fmt.Errorf("ADMIN_USERNAME/ADMIN_PASSWORD not set and no users exist")
	}
	salt := newSalt()
	_, err := a.pg.Exec(ctx, `INSERT INTO users
		(user_id, username, password_hash, password_salt, roles, qualifications, active, full_name)
		VALUES ($1,$2,$3,$4,$5,$6,true,'System Administrator')`,
		uuidStr(), a.cfg.AdminUser, hashPassword(a.cfg.AdminPass, salt), salt,
		[]string{"administrator"}, []string{})
	return err
}

