        # request body
        rb=op.get('requestBody',{}).get('content',{}).get('application/json',{}).get('schema',{})
        if rb:
            ref=rb.get('$ref','')
            if ref:
                out.append(f"  req: {ref.split('/')[-1]}")
            else:
                out.append(f"  req inline: {json.dumps(rb)}")
        # params
        for p in op.get('parameters',[]):
            out.append(f"  param: {p.get('in')} {p.get('name')} required={p.get('required',False)}")
        # responses
        for code,resp in op.get('responses',{}).items():
            sch=resp.get('content',{}).get('application/json',{}).get('schema',{})
            ref=sch.get('$ref','')
            if ref:
                out.append(f"  resp {code}: {ref.split('/')[-1]}")
            else:
                out.append(f"  resp {code}: {json.dumps(sch)}")
        out.append("")
open('/tmp/ops_detail.txt','w').write("\n".join(out))
print("done", len(out))

