package main

import (
	"context"
	"time"

	"go.mongodb.org/mongo-driver/bson"
	"go.mongodb.org/mongo-driver/mongo/options"
)

type auditRecord struct {
	ActorID    string
	Role       string
	Action     string
	EntityType string
	EntityID   string
	Success    bool
	OccurredAt time.Time
	Details    map[string]any
}

func (a *App) audit(ctx context.Context, u *AuthUser, action, entityType, entityID string, success bool, details map[string]any) {
	if u == nil {
		u = &AuthUser{}
	}
	rec := bson.M{
		"auditId":     uuidStr(),
		"actorId":     u.UserID,
		"role":        u.ActiveRole,
		"actorRole":   u.ActiveRole,
		"action":      action,
		"entityType":  entityType,
		"entityType":  entityType,
		"entityId":    entityID,
		"success":     success,
		"occurredAt":  time.Now().UTC(),
		"timestamp":   time.Now().UTC(),
		"details":     details,
	}
	_, _ = a.mdb.Collection("audit_events").InsertOne(ctx, rec)
}

// realtime event seq counter
func (a *App) emitRealtime(ctx context.Context, etype, entityType, entityID string, payload map[string]any) {
	seq := a.nextSeq(ctx)
	_, _ = a.mdb.Collection("realtime_events").InsertOne(ctx, bson.M{
		"id":          seq,
		"seq":         seq,
		"type":        etype,
		"entityType":  entityType,
		"entityId":    entityID,
		"payload":     payload,
		"createdAt":   time.Now().UTC(),
		"timestamp":   time.Now().UTC(),
	})
}

func (a *App) nextSeq(ctx context.Context) int64 {
	for {
		var seq int64
		err := a.pg.QueryRow(ctx, `SELECT seq FROM network_revision WHERE id=1 FOR UPDATE`).Scan(&seq)
		if err != nil {
			return time.Now().UnixNano()
		}
		seq++
		_, err = a.pg.Exec(ctx, `UPDATE network_revision SET seq=$1 WHERE id=1`, seq)
		if err == nil {
			return seq
		}
	}
}

func init() {
	// network_revision table is created in migrate; add seq column if missing at runtime via migration
}

func (a *App) ensureSeqCol(ctx context.Context) {
	_, _ = a.pg.Exec(ctx, `ALTER TABLE network_revision ADD COLUMN IF NOT EXISTS seq bigint NOT NULL DEFAULT 0`)
	_, _ = a.pg.Exec(ctx, `UPDATE network_revision SET seq=0 WHERE id=1 AND seq IS NULL`)
}

func realtimeQuery(ctx context.Context, a *App, since int64, limit int) ([]bson.M, int64, error) {
	if limit <= 0 {
		limit = 500
	}
	opts := options.Find().SetSort(bson.D{{Key: "seq", Value: 1}}).SetLimit(int64(limit))
	filter := bson.M{}
	if since > 0 {
		filter["seq"] = bson.M{"$gt": since}
	}
	cur, err := a.mdb.Collection("realtime_events").Find(ctx, filter, opts)
	if err != nil {
		return nil, 0, err
	}
	defer cur.Close(ctx)
	var out []bson.M
	if err := cur.All(ctx, &out); err != nil {
		return nil, 0, err
	}
	var last int64 = since
	for _, d := range out {
		if s, ok := d["seq"].(int64); ok && s > last {
			last = s
		}
	}
	return out, last, nil
}

func auditSearch(ctx context.Context, a *App, q auditQuery) (auditSearchResult, error) {
	filter := bson.M{}
	if q.ActorID != "" {
		filter["actorId"] = q.ActorID
	}
	if q.EntityType != "" {
		filter["entityType"] = q.EntityType
	}
	if q.EntityID != "" {
		filter["entityId"] = q.EntityID
	}
	if q.Action != "" {
		filter["action"] = q.Action
	}
	if q.Role != "" {
		filter["role"] = q.Role
	}
	if q.Success != nil {
		filter["success"] = *q.Success
	}
	if !q.FromTime.IsZero() || !q.ToTime.IsZero() {
		tf := bson.M{}
		if !q.FromTime.IsZero() {
			tf["$gte"] = q.FromTime
		}
		if !q.ToTime.IsZero() {
			tf["$lte"] = q.ToTime
		}
		filter["occurredAt"] = tf
	}
	if q.Query != "" {
		filter["$or"] = bson.A{
			bson.M{"action": bson.M{"$regex": q.Query, "$options": "i"}},
			bson.M{"entityType": bson.M{"$regex": q.Query, "$options": "i"}},
			bson.M{"entityId": bson.M{"$regex": q.Query, "$options": "i"}},
		}
	}
	total, err := a.mdb.Collection("audit_events").CountDocuments(ctx, filter)
	if err != nil {
		return auditSearchResult{}, err
	}
	order := 1
	if q.Order == "newest_first" {
		order = -1
	}
	opts := options.Find().SetSort(bson.D{{Key: "occurredAt", Value: order}, {Key: "_id", Value: order}}).
		SetSkip(int64(q.Offset)).SetLimit(int64(q.Limit))
	cur, err := a.mdb.Collection("audit_events").Find(ctx, filter, opts)
	if err != nil {
		return auditSearchResult{}, err
	}
	defer cur.Close(ctx)
	var out []bson.M
	if err := cur.All(ctx, &out); err != nil {
		return auditSearchResult{}, err
	}
	entries := make([]map[string]any, 0, len(out))
	for _, d := range out {
		entries = append(entries, normalizeAudit(d))
	}
	hasMore := q.Offset+len(entries) < int(total)
	res := auditSearchResult{
		Entries: entries,
		Total:   int(total),
		Returned: len(entries),
		Offset:  q.Offset,
		Limit:   q.Limit,
		Order:   q.Order,
		HasMore: hasMore,
	}
	if q.Offset+len(entries) < int(total) {
		no := q.Offset + len(entries)
		res.NextOffset = &no
	}
	return res, nil
}

