	oid := getStr(d, "_id")
	aid := getStr(d, "auditId")
	if aid == "" {
		aid = oid
	}
	return map[string]any{
		"auditId":    aid,
		"audit_id":   aid,
		"actorId":    getStr(d, "actorId"),
		"actor_id":   getStr(d, "actorId"),
		"role":        getStr(d, "role"),
		"actorRole":   getStr(d, "role"),
		"action":      getStr(d, "action"),
		"entityType": getStr(d, "entityType"),
		"entity_type": getStr(d, "entityType"),
		"entityId":   getStr(d, "entityId"),
		"entity_id":  getStr(d, "entityId"),
		"success":    getBool(d, "success"),
		"occurredAt": getTime(d, "occurredAt"),
		"occurred_at": getTime(d, "occurredAt"),
		"details":    d["details"],
	}
}

func getStr(d bson.M, k string) string {
	if v, ok := d[k]; ok {
		switch t := v.(type) {
		case string:
			return t
		}
	}
	return ""
}

func getBool(d bson.M, k string) bool {
	if v, ok := d[k]; ok {
		if b, ok := v.(bool); ok {
			return b
		}
	}
	return false
}

func getTime(d bson.M, k string) string {
	if v, ok := d[k]; ok {
		switch t := v.(type) {
		case time.Time:
			return t.UTC().Format(time.RFC3339Nano)
		case string:
			return t
		}
	}
	return ""
}

type auditQuery struct {
	Query     string
	ActorID   string
	EntityType string
	EntityID  string
	Action    string
	Role      string
	Success   *bool
	FromTime  time.Time
	ToTime    time.Time
	Limit     int
	Offset    int
	Order     string
}

type auditSearchResult struct {
	Entries    []map[string]any `json:"entries"`
	Total      int              `json:"total"`
	Returned   int              `json:"returned"`
	Offset     int              `json:"offset"`
	Limit      int              `json:"limit"`
