			if cooled {
				if cool-coolRes < 1 {
					return false
				}
			} else {
				if reg-regRes < 1 {
					return false
				}
			}
		}
	}
	return true
}

func (a *App) currentServiceabilityVersion(ctx context.Context) int {
	var ver int
	err := a.pg.QueryRow(ctx, `SELECT COALESCE(MAX(version),0) FROM serviceability_versions WHERE status='complete'`).Scan(&ver)
	if err != nil {
		return 0
	}
	return ver
}

// computeServiceabilityVersion computes and stores a complete serviceability version.
func (a *App) computeServiceabilityVersion(ctx context.Context) (int, error) {
	nodes, conns := must2(loadNetwork(ctx, a.pg))
	var rev int
	_ = a.pg.QueryRow(ctx, `SELECT rev FROM network_revision WHERE id=1`).Scan(&rev)

	regions := []map[string]any{}
	cpCount := 0
	for _, n := range nodes {
		if n.CollectionPt {
			cpCount++
			regions = append(regions, map[string]any{
				"locationId":  n.ID,
				"name":         n.Name,
				"latitude":     n.Lat,
				"longitude":    n.Lng,
				"coverageKm":   n.CoverageKm,
			})
		}
	}
	_ = conns
	ver := rev + 1
	_, err := a.pg.Exec(ctx, `INSERT INTO serviceability_versions (version, status, computed_at, network_revision, regions, active_cp_count)
		VALUES ($1,'complete',now(),$2,$3,$4)`, ver, rev, toJSONB(regions), cpCount)
	if err != nil {
		return 0, err
	}
	_, err = a.pg.Exec(ctx, `UPDATE network_revision SET rev=$1 WHERE id=1`, ver)
	return ver, err
}

func must[T any](v T, err error) T {
	if err != nil {
		panic(err)
	}
	return v
}

func must2[T any](v T, err error) (T, error) {
	return v, err
}

func toJSONB(v any) []byte {
	b, _ := jsonMarshal(v)
	return b
}

// sortStops ensures stops are ordered by sequence.
func sortStops(stops []map[string]any) {
	sort.SliceStops(stops, func(i, j int) bool {
		return getStSeq(stops[i]) < getStSeq(stops[j])
	})
}

func getStSeq(s map[string]any) int {
	if v, ok := s["sequence"]; ok {
		if f, ok := v.(float64); ok {
			return int(f)
		}
		if i, ok := v.(int); ok {
			return i
		}
	}
	return 0
}

var sortSliceStops = func(stops []map[string]any, less func(i, j int) bool) {
	sort.Slice(stops, less)
}

