package main

import (
	"context"
	"crypto/rand"
	"crypto/subtle"
	"encoding/hex"
	"errors"
	"fmt"
	"log"
	"sync"
	"time"

	"github.com/jackc/pgx/v5"
	"github.com/jackc/pgx/v5/pgxpool"
	"go.mongodb.org/mongo-driver/mongo"
	"go.mongodb.org/mongo-driver/mongo/options"
)

type App struct {
	cfg    Config
	pg     *pgxpool.Pool
	mongo  *mongo.Client
	mdb    *mongo.Database
	rtMu   sync.Mutex
}

func NewApp(ctx context.Context, cfg Config) (*App, error) {
	pool, err := pgxpool.New(ctx, cfg.PostgresURL)
	if err != nil {
		return nil, fmt.Errorf("pg connect: %w", err)
	}
	if err := pool.Ping(ctx); err != nil {
		return nil, fmt.Errorf("pg ping: %w", err)
	}
	mclient, err := mongo.Connect(ctx, options.Client().ApplyURI(cfg.MongoURI))
	if err != nil {
		return nil, fmt.Errorf("mongo connect: %w", err)
	}
	if err := mclient.Ping(ctx, nil); err != nil {
		return nil, fmt.Errorf("mongo ping: %w", err)
	}
	a := &App{
		cfg:   cfg,
		pg:    pool,
		mongo: mclient,
		mdb:   mclient.Database("arena"),
	}
	if err := a.Migrate(ctx); err != nil {
		return nil, fmt.Errorf("migrate: %w", err)
	}
	if err := a.MaterializeMongo(ctx); err != nil {
		return nil, fmt.Errorf("materialize mongo: %w", err)
	}
	if err := a.SeedDefaults(ctx); err != nil {
		return nil, fmt.Errorf("seed: %w", err)
	}
	return a, nil
}

func (a *App) Close() {
	if a.pg != nil {
		a.pg.Close()
	}
	if a.mongo != nil {
		_ = a.mongo.Disconnect(context.Background())
	}
}

// tx runs fn inside a serializable transaction with retry on snapshot conflict.
func (a *App) tx(ctx context.Context, fn func(pgx.Tx) error) error {
	for i := 0; i < 4; i++ {
		err := func() error {
			t, err := a.pg.BeginTx(ctx, pgx.TxOptions{IsoLevel: pgx.Serializable})
			if err != nil {
				return err
