		path[i], path[j] = path[j], path[i]
	}
	steps := make([]routeStep, 0, len(path))
	for i, p := range path {
		steps = append(steps, routeStep{LocID: nodes[p].ID, IsLab: labSet[nodes[p].ID], HandMin: nodes[p].HandlingMin})
