// networkNode is an active location with its functions.
type networkNode struct {
	ID             string
	Name           string
	Lat, Lng       float64
	CoverageKm     float64
	HandlingMin    int
	CollectionPt   bool
	TransferPt     bool
	Hub            bool
	Laboratory     bool
}

type networkConnection struct {
	ID          string
	From        string
	To          string
	TravelMin   int
	Cost        float64
	Cooled      bool
	Active      bool
}

func loadNetwork(ctx context.Context, pg pgxQuerier) ([]networkNode, []networkConnection, error) {
	rows, err := pg.Query(ctx, `SELECT location_id::text, name, latitude, longitude, coverage_km, handling_minutes,
		fn_collection_point, fn_transfer_point, fn_hub, fn_laboratory, active FROM locations`)
	if err != nil {
		return nil, nil, err
	}
	var nodes []networkNode
	for rows.Next() {
		var n networkNode
		var active bool
		if err := rows.Scan(&n.ID, &n.Name, &n.Lat, &n.Lng, &n.CoverageKm, &n.HandlingMin,
			&n.CollectionPt, &n.TransferPt, &n.Hub, &n.Laboratory, &active); err != nil {
			rows.Close()
			return nil, nil, err
		}
		if active {
			nodes = append(nodes, n)
		}
	}
	rows.Close()
	crows, err := pg.Query(ctx, `SELECT connection_id::text, from_location_id::text, to_location_id::text, travel_minutes, cost_units, cooled, active FROM connections`)
	if err != nil {
		return nil, nil, err
	}
	var conns []networkConnection
	for crows.Next() {
		var c networkConnection
		if err := crows.Scan(&c.ID, &c.From, &c.To, &c.TravelMin, &c.Cost, &c.Cooled, &c.Active); err != nil {
			crows.Close()
			return nil, nil, err
		}
		if c.Active {
			conns = append(conns, c)
		}
	}
	crows.Close()
	return nodes, conns, nil
}

type pgxQuerier interface {
	Query(ctx context.Context, sql string, args ...any) (pgx.Rows, error)
	QueryRow(ctx context.Context, sql string, args ...any) pgx.Row
	Exec(ctx context.Context, sql string, args ...any) (pgx.CommandTag, error)
