    80	// haversineKm returns distance in km between two lat/lng points.
    81	func haversineKm(lat1, lng1, lat2, lng2 float64) float64 {
    82		const R = 6371.0
    83		dLat := (lat2 - lat1) * math.Pi / 180
    84		dLng := (lng2 - lng1) * math.Pi / 180
    85		a := math.Sin(dLat/2)*math.Sin(dLat/2) +
    86			math.Cos(lat1*math.Pi/180)*math.Cos(lat2*math.Pi/180)*
    87				math.Sin(dLng/2)*math.Sin(dLng/2)
    88		c := 2 * math.Atan2(math.Sqrt(a), math.Sqrt(1-a))
    89		return R * c
    90	}
