   134					entryNode = &nodes[i]
   135					break
   136				}
   137			}
   138		} else {
   139			best := -1.0
   140			for i := range nodes {
   141				if !nodes[i].CollectionPt {
   142					continue
   143				}
   144				d := haversineKm(in.OriginLat, in.OriginLng, nodes[i].Lat, nodes[i].Lng)
   145				if d <= nodes[i].CoverageKm && (best < 0 || d < best) {
   146					best = d
   147					entryNode = &nodes[i]
   148				}
   149			}
   150		}
   151		if entryNode == nil {
   152			return serviceabilityResult{Serviceable: false, Reason: "outside_service_coverage", Version: version}
   153		}
   154	
   155		// 2. Find accepting laboratories for the sample type.
   156		labs := acceptingLabs(ctx, a.pg, in.SampleTypeID, nodes)
   157		if len(labs) == 0 {
   158			return serviceabilityResult{Serviceable: false, Reason: "no_accepting_laboratory", Version: version}
   159		}
   160	
   161		// 3. Find a route from entryNode to any lab (shortest by travel minutes).
   162		route, labID, estArrival, ok := findRoute(entryNode, labs, nodes, conns, in)
   163		if !ok {
   164			return serviceabilityResult{Serviceable: false, Reason: "no_route", Version: version}
   165		}
   166	
   167		// 4. Capacity check.
   168		hasCap := capacityAvailable(ctx, a.pg, route, in.RequiresCooled)
   169		if !hasCap {
   170			return serviceabilityResult{Serviceable: false, Reason: "insufficient_capacity", Version: version}
   171		}
   172	
   173		// 5. Deadline check.
   174		collectTime := in.EarliestCollect
   175		if collectTime.IsZero() {
   176			collectTime = in.RequestedAt
   177		}
