   218	// findRoute finds shortest path (by travel minutes) from entry node to any lab.
   219	func findRoute(entry *networkNode, labs []*networkNode, nodes []networkNode, conns []networkConnection, in serviceabilityInput) ([]routeStep, string, time.Time, bool) {
   220		labSet := map[string]bool{}
   221		for _, l := range labs {
   222			labSet[l.ID] = true
   223		}
   224		// Dijkstra over nodes.
   225		idx := map[string]int{}
   226		for i, n := range nodes {
   227			idx[n.ID] = i
   228		}
   229		adj := make([][]networkConnection, len(nodes))
   230		for _, c := range conns {
   231			if _, ok := idx[c.From]; !ok {
   232				continue
   233			}
   234			adj[idx[c.From]] = append(adj[idx[c.From]], c)
   235		}
   236		const inf = math.MaxInt32
   237		dist := make([]int, len(nodes))
   238		prev := make([]int, len(nodes))
   239		prevConn := make([]networkConnection, len(nodes))
   240		for i := range dist {
   241			dist[i] = inf
   242			prev[i] = -1
   243		}
   244		start := idx[entry.ID]
   245		dist[start] = entry.HandlingMin
   246		visited := make([]bool, len(nodes))
   247		for {
   248			u := -1
   249			best := inf
   250			for i := range dist {
   251				if !visited[i] && dist[i] < best {
   252					best = dist[i]
   253					u = i
   254				}
   255			}
   256			if u == -1 {
   257				break
   258			}
   259			visited[u] = true
   260			for _, c := range adj[u] {
   261				v := idx[c.To]
   262				nd := dist[u] + c.TravelMin + nodes[v].HandlingMin
   263				if nd < dist[v] {
   264					dist[v] = nd
   265					prev[v] = u
   266					prevConn[v] = c
   267				}
   268			}
   269		}
   270		bestLab := -1
   271		bestDist := inf
   272		for i, n := range nodes {
   273			if labSet[n.ID] && dist[i] < bestDist {
   274				bestDist = dist[i]
   275				bestLab = i
   276			}
   277		}
   278		if bestLab == -1 {
   279			return nil, "", time.Time{}, false
   280		}
   281		// Reconstruct path.
   282		var path []int
   283		for cur := bestLab; cur != -1; cur = prev[cur] {
   284			path = append(path, cur)
   285		}
   286		// reverse
   287		for i, j := 0, len(path)-1; i < j; i, j = i+1, j-1 {
   288			path[i], path[j] = path[j], path[i]
   289		}
   290		steps := make([]routeStep, 0, len(path))
   291		for i, p := range path {
   292			steps = append(steps, routeStep{LocID: nodes[p].ID, IsLab: labSet[nodes[p].ID], HandMin: nodes[p].HandlingMin})
   293			if i > 0 {
   294				c := prevConn[p]
   295				steps[len(steps)-1].TravelMin = c.TravelMin
   296				steps[len(steps)-1].Cooled = c.Cooled
   297			}
   298		}
   299		totalMin := dist[bestLab]
   300		collectTime := in.EarliestCollect
   301		if collectTime.IsZero() {
   302			collectTime = in.RequestedAt
   303		}
   304		estArrival := collectTime.Add(time.Duration(totalMin) * time.Minute)
   305		return steps, nodes[bestLab].ID, estArrival, true
   306	}
   307	
   308	func routeAllCooled(steps []routeStep, conns []networkConnection) bool {
   309		// A route satisfies cooled if all legs that require cooled transport are cooled.
   310		// Simplify: every transport step with TravelMin>0 must be cooled.
   311		for _, s := range steps {
   312			if s.TravelMin > 0 && !s.Cooled {
   313				return false
   314			}
   315		}
   316		return true
   317	}
   318	
   319	func capacityAvailable(ctx context.Context, pg pgxQuerier, steps []routeStep, cooled bool) bool {
   320		// Check node capacity at each intermediate stop and lab, plus connections.
   321		for _, s := range steps {
   322			var reg, regRes, cool, coolRes int
   323			err := pg.QueryRow(ctx, `SELECT regular_capacity, regular_reserved, cooled_capacity, cooled_reserved FROM capacity WHERE resource_id::text=$1`, s.LocID).Scan(&reg, &regRes, &cool, &coolRes)
   324			if err == nil {
   325				if cooled {
   326					if cool-coolRes < 1 {
   327						return false
   328					}
   329				} else {
   330					if reg-regRes < 1 {
   331						return false
   332					}
   333				}
   334			}
   335		}
   336		return true
   337	}
