   339	func (a *App) currentServiceabilityVersion(ctx context.Context) int {
   340		var ver int
   341		err := a.pg.QueryRow(ctx, `SELECT COALESCE(MAX(version),0) FROM serviceability_versions WHERE status='complete'`).Scan(&ver)
   342		if err != nil {
   343			return 0
   344		}
   345		return ver
   346	}
   347	
   348	// computeServiceabilityVersion computes and stores a complete serviceability version.
   349	func (a *App) computeServiceabilityVersion(ctx context.Context) (int, error) {
   350		nodes, conns := loadNetwork2(ctx, a.pg)
   351		var rev int
   352		_ = a.pg.QueryRow(ctx, `SELECT rev FROM network_revision WHERE id=1`).Scan(&rev)
   353	
   354		regions := []map[string]any{}
   355		cpCount := 0
   356		for _, n := range nodes {
   357			if n.CollectionPt {
   358				cpCount++
   359				regions = append(regions, map[string]any{
   360					"locationId": n.ID,
   361					"name":       n.Name,
   362					"latitude":   n.Lat,
   363					"longitude":  n.Lng,
   364					"coverageKm": n.CoverageKm,
   365				})
   366			}
   367		}
   368		_ = conns
   369		ver := rev + 1
   370		_, err := a.pg.Exec(ctx, `INSERT INTO serviceability_versions (version, status, computed_at, network_revision, regions, active_cp_count)
   371			VALUES ($1,'complete',now(),$2,$3,$4)`, ver, rev, toJSONB(regions), cpCount)
   372		if err != nil {
   373			return 0, err
   374		}
   375		_, err = a.pg.Exec(ctx, `UPDATE network_revision SET rev=$1 WHERE id=1`, ver)
   376		return ver, err
   377	}
