package main

import (
	"context"
	"time"

	"github.com/jackc/pgx/v5"
)

// sampleTypeRow holds a sample type's handling attributes.
type sampleTypeRow struct {
	ID                    string
	Name                  string
	QualifiedRequired     bool
	RequiredQualification string
	ContainerType         string
	TempMin               float64
	TempMax               float64
	RequiresCooled        bool
	BatchingAllowed       bool
	Incompatible          []string
}

func loadSampleType(ctx context.Context, pg pgxQuerier, id string) (*sampleTypeRow, error) {
	var s sampleTypeRow
	err := pg.QueryRow(ctx, `SELECT sample_type_id::text, name, qualified_collector_required, COALESCE(required_qualification,''), container_type, temperature_min_c, temperature_max_c, requires_cooled_route, batching_allowed, incompatible
		FROM sample_types WHERE sample_type_id::text=$1`, id).
		Scan(&s.ID, &s.Name, &s.QualifiedRequired, &s.RequiredQualification, &s.ContainerType, &s.TempMin, &s.TempMax, &s.RequiresCooled, &s.BatchingAllowed, &s.Incompatible)
	if err != nil {
		return nil, err
	}
	return &s, nil
}

func loadSampleTypeByName(ctx context.Context, pg pgxQuerier, name string) (*sampleTypeRow, error) {
	var s sampleTypeRow
	err := pg.QueryRow(ctx, `SELECT sample_type_id::text, name, qualified_collector_required, COALESCE(required_qualification,''), container_type, temperature_min_c, temperature_max_c, requires_cooled_route, batching_allowed, incompatible
		FROM sample_types WHERE name=$1`, name).
		Scan(&s.ID, &s.Name, &s.QualifiedRequired, &s.RequiredQualification, &s.ContainerType, &s.TempMin, &s.TempMax, &s.RequiresCooled, &s.BatchingAllowed, &s.Incompatible)
	if err != nil {
		return nil, err
	}
	return &s, nil
}

// planRouteStep is a planned stop/leg descriptor used when building a journey.
type planRouteStep struct {
	LocID     string
	IsLab     bool
	IsEntry   bool
	TravelMin int
	HandMin   int
	Cooled    bool
}

// planJourneyResult describes a created journey.
type planJourneyResult struct {
	JourneyID         string
	PlanVersion       int
	RouteMode         string
	TargetLaboratoryID string
	EstimatedArrival  time.Time
	TotalCost          float64
	Stops             []planRouteStep
	AssignmentIDs     []string
	CollectionAssign  string
	TransportAssigns   []string
	NodeAssigns        []string
	LabAssigns         []string
}

// resolveEntryAndRoute finds the entry collection node and route to a lab.
func (a *App) resolveEntryAndRoute(ctx context.Context, in serviceabilityInput) (*networkNode, []routeStep, string, time.Time, *apiError) {
	res := a.checkServiceability(ctx, in)
	if !res.Serviceable {
		code := "no_valid_route"
		switch res.Reason {
		case "outside_service_coverage":
			code = "outside_service_coverage"
		case "no_accepting_laboratory":
			code = "no_accepting_laboratory"
		case "no_route":
			code = "no_valid_route"
		case "insufficient_capacity":
			code = "capacity_exhausted"
		case "deadline_unreachable":
			code = "delivery_deadline_exceeded"
		case "handling_rules_unsatisfiable":
			code = "incompatible_batch"
		}
		return nil, nil, "", time.Time{}, errCode(409, code, res.Reason)
	}
	nodes, _ := loadNetwork2(ctx, a.pg)
	var entry *networkNode
	if in.OriginType == "node" && in.OriginNodeID != "" {
		for i := range nodes {
			if nodes[i].ID == in.OriginNodeID {
				entry = &nodes[i]
				break
			}
		}
	} else {
		best := -1.0
		for i := range nodes {
			if !nodes[i].CollectionPt {
				continue
			}
			d := haversineKm(in.OriginLat, in.OriginLng, nodes[i].Lat, nodes[i].Lng)
			if d <= nodes[i].CoverageKm && (best < 0 || d < best) {
				best = d
				entry = &nodes[i]
			}
		}
	}
	return entry, res.Route, res.TargetLaboratoryID, res.EstimatedArrival, nil
}

// eligibleWorkers returns workers holding one of the given roles and (for collectors) the qualification.
func eligibleWorkers(ctx context.Context, pg pgxQuerier, role string, requireQual string) ([]workerSummary, error) {
	rows, err := pg.Query(ctx, `
		SELECT u.user_id::text, u.full_name, u.roles, u.qualifications, u.assigned_location_id::text,
			COALESCE(wp.available,true), COALESCE(wp.capacity_units,1)
		FROM users u LEFT JOIN worker_profiles wp ON wp.worker_id=u.user_id
		WHERE u.active=true AND $1=ANY(u.roles)`, role)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var out []workerSummary
	for rows.Next() {
		var w workerSummary
		var roles, quals []string
		var assigned *string
		if err := rows.Scan(&w.UserID, &w.FullName, &roles, &quals, &assigned, &w.Available, &w.Capacity); err != nil {
			return nil, err
		}
		w.Roles = roles
		w.Qualifications = quals
		if assigned != nil {
			s := *assigned
			w.AssignedLocationID = &s
		}
		if requireQual != "" {
			has := false
			for _, q := range quals {
				if q == requireQual {
					has = true
					break
				}
			}
			if !has {
				continue
			}
		}
		out = append(out, w)
	}
	return out, nil
}

type workerSummary struct {
	UserID            string
	FullName          string
	Roles             []string
	Qualifications    []string
	AssignedLocationID *string
	Available         bool
	Capacity          int
}

// assignmentCount returns the number of non-terminal assignments a worker holds.
func assignmentCount(ctx context.Context, pg pgxQuerier, workerID string) int {
	var n int
	_ = pg.QueryRow(ctx, `SELECT COUNT(*) FROM assignments WHERE worker_id::text=$1 AND status IN ('offered','accepted','in_progress')`, workerID).Scan(&n)
	return n
}

// chooseWorker picks the eligible available worker with the fewest current assignments (fair assignment).
func chooseWorker(ctx context.Context, pg pgxQuerier, workers []workerSummary) *workerSummary {
	var best *workerSummary
	bestCount := -1
	for i := range workers {
		if !workers[i].Available {
			continue
		}
		n := assignmentCount(ctx, pg, workers[i].UserID)
		if bestCount < 0 || n < bestCount {
			bestCount = n
			best = &workers[i]
		}
	}
	return best
}

// reserveCapacity increments reserved units for a resource (cooled or regular).
func reserveCapacity(ctx context.Context, pg pgxQuerier, resourceID string, cooled bool) error {
	if resourceID == "" {
		return nil
	}
	if cooled {
		_, err := pg.Exec(ctx, `UPDATE capacity SET cooled_reserved=cooled_reserved+1 WHERE resource_id::text=$1 AND cooled_capacity-cooled_reserved>=1`, resourceID)
		return err
	}
	_, err := pg.Exec(ctx, `UPDATE capacity SET regular_reserved=regular_reserved+1 WHERE resource_id::text=$1 AND regular_capacity-regular_reserved>=1`, resourceID)
	return err
}

func releaseCapacity(ctx context.Context, pg pgxQuerier, resourceID string, cooled bool) {
	if resourceID == "" {
		return
	}
	if cooled {
		_, _ = pg.Exec(ctx, `UPDATE capacity SET cooled_reserved=GREATEST(cooled_reserved-1,0) WHERE resource_id::text=$1`, resourceID)
		return
	}
	_, _ = pg.Exec(ctx, `UPDATE capacity SET regular_reserved=GREATEST(regular_reserved-1,0) WHERE resource_id::text=$1`, resourceID)
}

func ensureCapacityRow(ctx context.Context, pg pgxQuerier, resourceID, kind string) {
	if resourceID == "" {
		return
	}
	_, _ = pg.Exec(ctx, `INSERT INTO capacity (resource_id, resource_kind) VALUES ($1,$2) ON CONFLICT DO NOTHING`, resourceID, kind)
}

// buildJourney creates a journey with stops and assignments from a route. If alreadySealed,
// no collection assignment is created. Returns the created assignment ids by category.
// tx must be the active transaction.
func (a *App) buildJourney(ctx context.Context, tx pgx.Tx, in serviceabilityInput, st *sampleTypeRow, entry *networkNode, route []routeStep, labID string, estArrival time.Time, alreadySealed bool) (*planJourneyResult, *apiError) {
	journeyID := uuidStr()
	routeMode := "direct"
	if len(route) > 2 {
		routeMode = "multi_stop"
	}
	collectTime := in.EarliestCollect
	if collectTime.IsZero() {
		collectTime = in.RequestedAt
	}
	var totalCost float64
	for _, s := range route {
		// approximate cost from travel minutes
		totalCost += float64(s.TravelMin)
	}

	_, err := tx.Exec(ctx, `INSERT INTO journeys (journey_id, parent_journey_id, plan_version, route_mode, status, estimated_delivery_at, total_cost_units, valid, target_laboratory_id, already_sealed)
		VALUES ($1,NULL,1,$2,'planned',$3,$4,true,$5,$6)`,
		journeyID, routeMode, estArrival, totalCost, labID, alreadySealed)
	if err != nil {
		return nil, errCode(500, "internal_error", err.Error())
	}

	// Link sample to journey done by caller.

	res := &planJourneyResult{
		JourneyID:          journeyID,
		PlanVersion:        1,
		RouteMode:          routeMode,
		TargetLaboratoryID: labID,
		EstimatedArrival:   estArrival,
		TotalCost:           totalCost,
	}

	// Create stops.
	seq := 0
	nowOffset := collectTime
	for i, s := range route {
		seq++
		stopID := uuidStr()
		stopType := "handoff"
		if i == 0 {
			stopType = "pickup"
		}
		if s.IsLab {
			stopType = "delivery"
		}
		est := nowOffset
		if i > 0 {
			est = nowOffset.Add(time.Duration(s.TravelMin) * time.Minute)
		}
		_, err := tx.Exec(ctx, `INSERT INTO journey_stops (stop_id, journey_id, location_id, stop_type, sequence, estimated_at, dwell_minutes)
			VALUES ($1,$2,$3,$4,$5,$6,$7)`, stopID, journeyID, s.LocID, stopType, seq, est, s.HandMin)
		if err != nil {
			return nil, errCode(500, "internal_error", err.Error())
		}
		res.Stops = append(res.Stops, planRouteStep{LocID: s.LocID, IsLab: s.IsLab, IsEntry: i == 0, TravelMin: s.TravelMin, HandMin: s.HandMin, Cooled: s.Cooled})
		nowOffset = est.Add(time.Duration(s.HandMin) * time.Minute)
	}

	// Create assignments.
	// 1. Collection assignment (if not already sealed) -> entry node, collection_professional with qualification.
	if !alreadySealed {
		workers, _ := eligibleWorkers(ctx, tx, "collection_professional", st.Name)
		w := chooseWorker(ctx, tx, workers)
		aid := uuidStr()
		var workerID *string
		var offerExp *time.Time
		if w != nil {
			workerID = &w.UserID
			exp := time.Now().UTC().Add(30 * time.Minute)
			offerExp = &exp
		}
		_, err := tx.Exec(ctx, `INSERT INTO assignments (assignment_id, journey_id, kind, sequence, status, from_location_id, to_location_id, worker_id, sample_id, node_id, offer_expires_at, offer_rank)
			VALUES ($1,$2,'collection',1,'offered',$3,$3,$4,$5,$3,$6,0)`,
			aid, journeyID, entry.ID, workerID, in.sampleID, offerExp)
		if err != nil {
			return nil, errCode(500, "internal_error", err.Error())
		}
		res.CollectionAssign = aid
		res.AssignmentIDs = append(res.AssignmentIDs, aid)
	}

	// 2. Transport legs between consecutive route stops.
	for i := 1; i < len(route); i++ {
		from := route[i-1].LocID
		to := route[i].LocID
		cooled := st.RequiresCooled
		// ensure connection capacity row exists
		var connID string
		_ = tx.QueryRow(ctx, `SELECT connection_id::text FROM connections WHERE from_location_id::text=$1 AND to_location_id::text=$2 AND cooled=$3 ORDER BY active DESC LIMIT 1`, from, to, cooled).Scan(&connID)
		ensureCapacityRow(ctx, tx, connID, "connection")
		workers, _ := eligibleWorkers(ctx, tx, "delivery_partner", "")
		w := chooseWorker(ctx, tx, workers)
		aid := uuidStr()
		var workerID *string
		var offerExp *time.Time
		if w != nil {
			workerID = &w.UserID
			exp := time.Now().UTC().Add(30 * time.Minute)
			offerExp = &exp
		}
		_, err := tx.Exec(ctx, `INSERT INTO assignments (assignment_id, journey_id, kind, sequence, status, from_location_id, to_location_id, worker_id, sample_id, offer_expires_at, offer_rank)
			VALUES ($1,$2,'transport',$3,'offered',$4,$5,$6,$7,$8,$3)`,
			aid, journeyID, i, from, to, workerID, in.sampleID, offerExp)
		if err != nil {
			return nil, errCode(500, "internal_error", err.Error())
		}
		res.TransportAssigns = append(res.TransportAssigns, aid)
		res.AssignmentIDs = append(res.AssignmentIDs, aid)
	}

	// 3. Node assignments for intermediate non-lab, non-entry stops.
	for i, s := range route {
		if i == 0 || s.IsLab {
			continue
		}
		workers, _ := eligibleWorkers(ctx, tx, "node_handler", "")
		// prefer worker assigned to this node
		var w *workerSummary
		for j := range workers {
			if workers[j].AssignedLocationID != nil && *workers[j].AssignedLocationID == s.LocID {
				w = &workers[j]
				break
			}
		}
		if w == nil {
			w = chooseWorker(ctx, tx, workers)
		}
		aid := uuidStr()
		var workerID *string
		var offerExp *time.Time
		if w != nil {
			workerID = &w.UserID
			exp := time.Now().UTC().Add(30 * time.Minute)
			offerExp = &exp
		}
		_, err := tx.Exec(ctx, `INSERT INTO assignments (assignment_id, journey_id, kind, sequence, status, from_location_id, to_location_id, worker_id, sample_id, node_id, offer_expires_at, offer_rank)
			VALUES ($1,$2,'node',$3,'offered',$4,$4,$5,$6,$4,$7,$3)`,
			aid, journeyID, i, s.LocID, workerID, in.sampleID, offerExp)
		if err != nil {
			return nil, errCode(500, "internal_error", err.Error())
		}
		res.NodeAssigns = append(res.NodeAssigns, aid)
		res.AssignmentIDs = append(res.AssignmentIDs, aid)
	}

	// 4. Laboratory assignment.
	workers, _ := eligibleWorkers(ctx, tx, "laboratory_team", "")
	var w *workerSummary
	for j := range workers {
		if workers[j].AssignedLocationID != nil && *workers[j].AssignedLocationID == labID {
			w = &workers[j]
			break
		}
	}
	if w == nil {
		w = chooseWorker(ctx, tx, workers)
	}
	aid := uuidStr()
	var workerID *string
	var offerExp *time.Time
	if w != nil {
		workerID = &w.UserID
		exp := time.Now().UTC().Add(30 * time.Minute)
		offerExp = &exp
	}
	_, err = tx.Exec(ctx, `INSERT INTO assignments (assignment_id, journey_id, kind, sequence, status, from_location_id, to_location_id, worker_id, sample_id, laboratory_id, offer_expires_at, offer_rank)
		VALUES ($1,$2,'laboratory',$3,'offered',$4,$4,$5,$6,$4,$7,$3)`,
		aid, journeyID, len(route), labID, workerID, in.sampleID, offerExp)
	if err != nil {
		return nil, errCode(500, "internal_error", err.Error())
	}
	res.LabAssigns = append(res.LabAssigns, aid)
	res.AssignmentIDs = append(res.AssignmentIDs, aid)

	return res, nil
}

var _ = pgx.ErrNoRows

