	case "/api/initiate-handoff":
		a.handleInitiateHandoff(w, r)
	case "/api/confirm-handoff":
		a.handleConfirmHandoff(w, r)
	case "/api/update-assignment-progress":
		a.handleUpdateAssignmentProgress(w, r)
	case "/api/record-worker-location":
		a.handleRecordWorkerLocation(w, r)
	case "/api/record-handling-checkpoint":
		a.handleRecordHandlingCheckpoint(w, r)
	case "/api/confirm-laboratory-receipt":
		a.handleConfirmLaboratoryReceipt(w, r)
	case "/api/record-laboratory-exception":
		a.handleRecordLaboratoryException(w, r)
	case "/api/set-worker-availability":
		a.handleSetWorkerAvailability(w, r)
	case "/api/read-sample-lifecycle":
		a.handleReadSampleLifecycle(w, r)

	// Dispatcher
	case "/api/read-operations-state":
		a.handleReadOperationsState(w, r)
	case "/api/read-journey-plan":
		a.handleReadJourneyPlan(w, r)
	case "/api/edit-active-plan":
		a.handleEditActivePlan(w, r)
	case "/api/split-journey":
		a.handleSplitJourney(w, r)
	case "/api/merge-journeys":
		a.handleMergeJourneys(w, r)
	case "/api/reroute-journey":
		a.handleRerouteJourney(w, r)
	case "/api/cancel-journey":
		a.handleCancelJourney(w, r)
	case "/api/report-disruption":
		a.handleReportDisruption(w, r)
	case "/api/search-audit-trail":
		a.handleSearchAuditTrail(w, r)

	default:
		// path params
		if strings.HasPrefix(p, "/api/read-sample-state/") {
			a.handleReadSampleState(w, r)
			return
		}
		if strings.HasPrefix(p, "/api/read-user/") {
			a.handleReadUser(w, r)
			return
		}
		a.handleError(w, errNotFound)
	}
}

func (a *App) handleError(w http.ResponseWriter, e *apiError) {
	writeError(w, e)
}

func (a *App) withCORS(next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		w.Header().Set("Access-Control-Allow-Origin", "*")
		w.Header().Set("Access-Control-Allow-Headers", "Authorization, Content-Type")
		w.Header().Set("Access-Control-Allow-Methods", "GET, POST, PUT, PATCH, DELETE, OPTIONS")
		if r.Method == http.MethodOptions {
			w.WriteHeader(204)
			return
		}
		next.ServeHTTP(w, r)
	})
}

func writeJSONStatus(w http.ResponseWriter, status int, v any) {
	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(status)
	_ = json.NewEncoder(w).Encode(v)
}

// serveFrontend serves the SPA from the embedded/asset directory if present.
func (a *App) serveFrontend() http.Handler {
	dir := "frontend/dist"
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		if r.URL.Path == "/" || strings.HasPrefix(r.URL.Path, "/assets") {
			fp := filepath.Join(dir, r.URL.Path)
			if r.URL.Path == "/" {
				fp = filepath.Join(dir, "index.html")
			}
			if data, err := os.ReadFile(fp); err == nil {
				w.Header().Set("Content-Type", contentTypeFor(fp))
				_, _ = w.Write(data)
				return
			}
		}
		// fallback to index.html for SPA routes
		if data, err := os.ReadFile(filepath.Join(dir, "index.html")); err == nil {
			w.Header().Set("Content-Type", "text/html; charset=utf-8")
			_, _ = w.Write(data)
			return
		}
		http.NotFound(w, r)
	})
}

func (a *App) serveMapAssets() http.Handler {
	base := a.cfg.MapAssetsDir
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		rel := strings.TrimPrefix(r.URL.Path, "/map-assets/")
		fp := filepath.Join(base, rel)
		data, err := os.ReadFile(fp)
		if err != nil {
			http.NotFound(w, r)
			return
		}
		w.Header().Set("Content-Type", contentTypeFor(fp))
		_, _ = w.Write(data)
	})
}

func contentTypeFor(fp string) string {
	switch strings.ToLower(filepath.Ext(fp)) {
	case ".html":
		return "text/html; charset=utf-8"
	case ".js":
		return "application/javascript"
	case ".css":
		return "text/css"
	case ".json":
		return "application/json"
	case ".pmtiles":
		return "application/octet-stream"
	case ".pbf":
		return "application/x-protobuf"
	case ".png":
		return "image/png"
	case ".svg":
		return "image/svg+xml"
	case ".woff":
		return "font/woff"
	case ".woff2":
		return "font/woff2"
	default:
		return "application/octet-stream"
	}
}

// readBody reads and returns the raw JSON body bytes.
func readBody(r *http.Request) ([]byte, error) {
	if r.Body == nil {
		return nil, nil
	}
	return io.ReadAll(r.Body)
}

func init() {
	ready.Store(true) // set true once app is constructed in main; see NewApp callers
}

