package main

import (
	"encoding/json"
	"errors"
	"net/http"
)

// handleAuthenticateUser implements POST /api/authenticate-user.
func (a *App) handleAuthenticateUser(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		writeError(w, errCode(405, "method_not_allowed", "POST required"))
		return
	}
	var req struct {
		Username string `json:"username"`
		Password string `json:"password"`
	}
	if err := decodeJSON(r, &req); err != nil {
		writeError(w, errInvalidJSON)
		return
	}
	if req.Username == "" || req.Password == "" {
		writeError(w, errCode(401, "invalid_credentials", "invalid credentials"))
		return
	}
	var (
		userID, username, fullName string
		roles, quals               []string
		hash, salt                 string
		active                     bool
	)
	err := a.pg.QueryRow(r.Context(), `SELECT user_id::text, username, COALESCE(full_name,''), roles, qualifications, password_hash, password_salt, active FROM users WHERE username=$1`, req.Username).
		Scan(&userID, &username, &fullName, &roles, &quals, &hash, &salt, &active)
	if err != nil || !active {
		writeError(w, errCode(401, "invalid_credentials", "invalid credentials"))
		return
	}
	if !secureEq(hashPassword(req.Password, salt), hash) {
		a.audit(r.Context(), &AuthUser{UserID: userID, ActiveRole: ""}, "authenticate_user", "user", userID, false, map[string]any{"username": req.Username})
		writeError(w, errCode(401, "invalid_credentials", "invalid credentials"))
		return
	}
	// Default active role: first role.
	activeRole := ""
	if len(roles) > 0 {
		activeRole = roles[0]
	}
	token := newToken()
	_, err = a.pg.Exec(r.Context(), `INSERT INTO sessions (token, user_id, active_role) VALUES ($1,$2,$3)`, token, userID, activeRole)
	if err != nil {
		writeError(w, errConflict)
		return
	}
	a.audit(r.Context(), &AuthUser{UserID: userID, ActiveRole: activeRole}, "authenticate_user", "user", userID, true, map[string]any{"username": username})
	writeData(w, 200, map[string]any{
		"sessionToken": token,
		"userId":       userID,
		"roles":        roles,
		"activeRole":   activeRole,
	})
}

// handleSelectActiveRole implements POST /api/select-active-role.
func (a *App) handleSelectActiveRole(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		writeError(w, errCode(405, "method_not_allowed", "POST required"))
		return
	}
	u := currentUser(r)
	var req struct {
		Role string `json:"role"`
	}
	if err := decodeJSON(r, &req); err != nil {
		writeError(w, errInvalidJSON)
		return
	}
	if req.Role == "" {
		writeError(w, errCode(400, "invalid_role", "invalid role"))
		return
	}
	if !u.hasRole(req.Role) {
		writeError(w, errCode(403, "role_not_held", "role not held"))
		return
	}
	_, err := a.pg.Exec(r.Context(), `UPDATE sessions SET active_role=$1 WHERE user_id=$2`, req.Role, u.UserID)
	if err != nil {
		writeError(w, errConflict)
		return
	}
	a.audit(r.Context(), u, "select_active_role", "user", u.UserID, true, map[string]any{"role": req.Role})
	writeData(w, 200, map[string]any{
		"activeRole": req.Role,
		"roles":      u.Roles,
	})
}

// handleUIBootstrap implements GET /api/ui/bootstrap.
func (a *App) handleUIBootstrap(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodGet {
		writeError(w, errCode(405, "method_not_allowed", "GET required"))
		return
	}
	u := currentUser(r)
	roleSel := u.ActiveRole == ""
	// requester samples if requester active role
	var requesterSamples []map[string]any
	if u.ActiveRole == "requester" {
		requesterSamples = a.requesterSamples(r.Context(), u.UserID)
	}
	ops := a.operationsState(r.Context())
	writeData(w, 200, map[string]any{
		"user": map[string]any{
			"userId":                u.UserID,
			"username":              u.Username,
			"fullName":              u.FullName,
			"roles":                 u.Roles,
			"activeRole":            u.ActiveRole,
			"roleSelectionRequired": roleSel,
		},
		"serverTime":       nowRFC(),
		"requesterSamples": requesterSamples,
		"operations":       ops,
	})
}

// handleEvents implements GET /api/events (polling fallback + SSE not required; returns batch).
func (a *App) handleEvents(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodGet {
		writeError(w, errCode(405, "method_not_allowed", "GET required"))
		return
	}
	var since int64
	_ = json.NewDecoder(strings.NewReader(r.URL.Query().Get("since"))).Decode(&since)
	if since == 0 {
		// allow plain integer query param
		since = parseQueryInt(r, "since")
	}
	evs, cursor, err := realtimeQuery(r.Context(), a, since, 500)
	if err != nil {
		writeError(w, errInternal)
		return
	}
	events := make([]map[string]any, 0, len(evs))
	for _, e := range evs {
		events = append(events, normalizeRealtime(e))
	}
	writeData(w, 200, map[string]any{
		"events": events,
		"cursor": cursor,
	})
}

func normalizeRealtime(d map[string]any) map[string]any {
	out := map[string]any{}
	for k, v := range d {
		if k == "_id" {
			continue
		}
		out[k] = v
	}
	if _, ok := out["id"]; !ok {
		if s, ok := out["seq"]; ok {
			out["id"] = s
		}
	}
	return out
}

func parseQueryInt(r *http.Request, key string) int64 {
	v := r.URL.Query().Get(key)
	if v == "" {
		return 0
	}
	var n int64
	for _, c := range v {
		if c < '0' || c > '9' {
			return 0
		}
		n = n*10 + int64(c-'0')
	}
	return n
}

var _ = errors.New

