// handleReadUser implements GET /api/read-user/{userId}.
func (a *App) handleReadUser(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodGet {
		writeError(w, errCode(405, "method_not_allowed", "GET required"))
		return
	}
	uid := pathTail(r, "/api/read-user/")
	if uid == "" {
		writeError(w, errNotFound)
		return
	}
	u := currentUser(r)
	if u.ActiveRole != "administrator" && u.UserID != uid {
		writeError(w, errForbidden)
		return
	}
	var username, email, fullName, phone string
	var roles, quals []string
	var active bool
	err := a.pg.QueryRow(r.Context(), `SELECT username, COALESCE(email,''), COALESCE(full_name,''), COALESCE(phone,''), roles, qualifications, active FROM users WHERE user_id::text=$1`, uid).
		Scan(&username, &email, &fullName, &phone, &roles, &quals, &active)
	if err != nil {
		writeError(w, errNotFound)
		return
	}
	writeData(w, 200, map[string]any{
		"userId":         uid,
		"username":       username,
		"email":          email,
		"fullName":       fullName,
		"phone":          phone,
		"roles":          roles,
		"qualifications": quals,
		"certifications": a.userCerts(r.Context(), uid),
		"active":         active,
	})
}

func pathTail(r *http.Request, prefix string) string {
	p := r.URL.Path
	if len(p) >= len(prefix) && p[:len(prefix)] == prefix {
		return p[len(prefix):]
	}
	return ""
}

