		"computedAt":    computedAt,
		"regions":       regions,
		"activeCpCount": cpCount,
	})
}

func nilIfEmpty(s string) any {
	if s == "" {
		return nil
	}
	return s
}

func nilIfZero(t time.Time) any {
	if t.IsZero() {
		return nil
	}
	return t
