// handleCreateCollectionRequest implements POST /api/create-collection-request (requester).
func (a *App) handleCreateCollectionRequest(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		writeError(w, errCode(405, "method_not_allowed", "POST required"))
		return
