		OriginAddress     string  `json:"originAddress"`
		SampleTypeId      string  `json:"sampleTypeId"`
		DeliveryDeadline  string  `json:"deliveryDeadline"`
		EarliestCollection string `json:"earliestCollection"`
		LatestCollection   string  `json:"latestCollection"`
