	}
	if err := decodeJSON(r, &req); err != nil {
		writeError(w, errInvalidJSON)
		return
	}
	if req.OriginType == "home" {
		// home origin must not have a node id
	} else if req.OriginType != "clinic" && req.OriginType != "node" {
		writeError(w, errCode(400, "invalid_origin", "invalid origin type"))
		return
	}
	deadline, e := parseTime(req.DeliveryDeadline, "invalid_time")
	if e != nil {
		writeError(w, e)
		return
	}
	var earliest, latest time.Time
	if req.EarliestCollection != "" {
		earliest, e = parseTime(req.EarliestCollection, "invalid_time")
		if e != nil {
			writeError(w, e)
			return
		}
	}
	if req.LatestCollection != "" {
		latest, e = parseTime(req.LatestCollection, "invalid_time")
		if e != nil {
			writeError(w, e)
			return
		}
	}
