// handleReadServiceabilitySnapshot implements GET /api/read-serviceability-snapshot.
func (a *App) handleReadServiceabilitySnapshot(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodGet {
		writeError(w, errCode(405, "method_not_allowed", "GET required"))
		return
	}
	u := currentUser(r)
	if e := requireRole(u, "administrator", "dispatcher", "requester"); e != nil {
		writeError(w, e)
		return
	}
	ver := a.currentServiceabilityVersion(r.Context())
	var computedAt string
	var regions []map[string]any
	var cpCount int
	_ = a.pg.QueryRow(r.Context(), `SELECT computed_at::text, regions, active_cp_count FROM serviceability_versions WHERE version=$1 AND status='complete'`, ver).Scan(&computedAt, &regions, &cpCount)
