// buildJourney creates a journey with stops and assignments from a route. If alreadySealed,
// no collection assignment is created. Returns the created assignment ids by category.
// tx must be the active transaction.
func (a *App) buildJourney(ctx context.Context, tx pgx.Tx, in serviceabilityInput, st *sampleTypeRow, entry *networkNode, route []routeStep, labID string, estArrival time.Time, alreadySealed bool) (*planJourneyResult, *apiError) {
	journeyID := uuidStr()
	routeMode := "direct"
	if len(route) > 2 {
		routeMode = "multi_stop"
	}
	collectTime := in.EarliestCollect
	if collectTime.IsZero() {
		collectTime = in.RequestedAt
	}
	var totalCost float64
	for _, s := range route {
		// approximate cost from travel minutes
		totalCost += float64(s.TravelMin)
	}

	_, err := tx.Exec(ctx, `INSERT INTO journeys (journey_id, parent_journey_id, plan_version, route_mode, status, estimated_delivery_at, total_cost_units, valid, target_laboratory_id, already_sealed)
		VALUES ($1,NULL,1,$2,'planned',$3,$4,true,$5,$6)`,
		journeyID, routeMode, estArrival, totalCost, labID, alreadySealed)
	if err != nil {
		return nil, errCode(500, "internal_error", err.Error())
	}

	// Link sample to journey done by caller.

	res := &planJourneyResult{
		JourneyID:          journeyID,
		PlanVersion:        1,
		RouteMode:          routeMode,
		TargetLaboratoryID: labID,
		EstimatedArrival:   estArrival,
		TotalCost:           totalCost,
	}

	// Create stops.
	seq := 0
	nowOffset := collectTime
	for i, s := range route {
		seq++
		stopID := uuidStr()
		stopType := "handoff"
		if i == 0 {
			stopType = "pickup"
		}
		if s.IsLab {
			stopType = "delivery"
		}
		est := nowOffset
		if i > 0 {
			est = nowOffset.Add(time.Duration(s.TravelMin) * time.Minute)
		}
		_, err := tx.Exec(ctx, `INSERT INTO journey_stops (stop_id, journey_id, location_id, stop_type, sequence, estimated_at, dwell_minutes)
			VALUES ($1,$2,$3,$4,$5,$6,$7)`, stopID, journeyID, s.LocID, stopType, seq, est, s.HandMin)
		if err != nil {
			return nil, errCode(500, "internal_error", err.Error())
		}
		res.Stops = append(res.Stops, planRouteStep{LocID: s.LocID, IsLab: s.IsLab, IsEntry: i == 0, TravelMin: s.TravelMin, HandMin: s.HandMin, Cooled: s.Cooled})
		nowOffset = est.Add(time.Duration(s.HandMin) * time.Minute)
	}

	// Create assignments.
	// 1. Collection assignment (if not already sealed) -> entry node, collection_professional with qualification.
	if !alreadySealed {
		workers, _ := eligibleWorkers(ctx, tx, "collection_professional", st.Name)
		w := chooseWorker(ctx, tx, workers)
		aid := uuidStr()
		var workerID *string
		var offerExp *time.Time
		if w != nil {
			workerID = &w.UserID
			exp := time.Now().UTC().Add(30 * time.Minute)
			offerExp = &exp
		}
		_, err := tx.Exec(ctx, `INSERT INTO assignments (assignment_id, journey_id, kind, sequence, status, from_location_id, to_location_id, worker_id, sample_id, node_id, offer_expires_at, offer_rank)
			VALUES ($1,$2,'collection',1,'offered',$3,$3,$4,$5,$3,$6,0)`,
			aid, journeyID, entry.ID, workerID, in.sampleID, offerExp)
		if err != nil {
			return nil, errCode(500, "internal_error", err.Error())
		}
		res.CollectionAssign = aid
		res.AssignmentIDs = append(res.AssignmentIDs, aid)
	}

	// 2. Transport legs between consecutive route stops.
	for i := 1; i < len(route); i++ {
		from := route[i-1].LocID
		to := route[i].LocID
		cooled := st.RequiresCooled
		// ensure connection capacity row exists
		var connID string
		_ = tx.QueryRow(ctx, `SELECT connection_id::text FROM connections WHERE from_location_id::text=$1 AND to_location_id::text=$2 AND cooled=$3 ORDER BY active DESC LIMIT 1`, from, to, cooled).Scan(&connID)
		ensureCapacityRow(ctx, tx, connID, "connection")
		workers, _ := eligibleWorkers(ctx, tx, "delivery_partner", "")
		w := chooseWorker(ctx, tx, workers)
		aid := uuidStr()
		var workerID *string
		var offerExp *time.Time
		if w != nil {
			workerID = &w.UserID
			exp := time.Now().UTC().Add(30 * time.Minute)
			offerExp = &exp
		}
		_, err := tx.Exec(ctx, `INSERT INTO assignments (assignment_id, journey_id, kind, sequence, status, from_location_id, to_location_id, worker_id, sample_id, offer_expires_at, offer_rank)
			VALUES ($1,$2,'transport',$3,'offered',$4,$5,$6,$7,$8,$3)`,
			aid, journeyID, i, from, to, workerID, in.sampleID, offerExp)
		if err != nil {
			return nil, errCode(500, "internal_error", err.Error())
		}
		res.TransportAssigns = append(res.TransportAssigns, aid)
		res.AssignmentIDs = append(res.AssignmentIDs, aid)
	}

	// 3. Node assignments for intermediate non-lab, non-entry stops.
	for i, s := range route {
		if i == 0 || s.IsLab {
			continue
		}
		workers, _ := eligibleWorkers(ctx, tx, "node_handler", "")
		// prefer worker assigned to this node
		var w *workerSummary
		for j := range workers {
			if workers[j].AssignedLocationID != nil && *workers[j].AssignedLocationID == s.LocID {
				w = &workers[j]
				break
			}
		}
		if w == nil {
			w = chooseWorker(ctx, tx, workers)
		}
		aid := uuidStr()
		var workerID *string
		var offerExp *time.Time
		if w != nil {
			workerID = &w.UserID
			exp := time.Now().UTC().Add(30 * time.Minute)
			offerExp = &exp
		}
		_, err := tx.Exec(ctx, `INSERT INTO assignments (assignment_id, journey_id, kind, sequence, status, from_location_id, to_location_id, worker_id, sample_id, node_id, offer_expires_at, offer_rank)
			VALUES ($1,$2,'node',$3,'offered',$4,$4,$5,$6,$4,$7,$3)`,
			aid, journeyID, i, s.LocID, workerID, in.sampleID, offerExp)
		if err != nil {
			return nil, errCode(500, "internal_error", err.Error())
		}
		res.NodeAssigns = append(res.NodeAssigns, aid)
		res.AssignmentIDs = append(res.AssignmentIDs, aid)
	}

	// 4. Laboratory assignment.
	workers, _ := eligibleWorkers(ctx, tx, "laboratory_team", "")
	var w *workerSummary
	for j := range workers {
		if workers[j].AssignedLocationID != nil && *workers[j].AssignedLocationID == labID {
			w = &workers[j]
			break
		}
	}
	if w == nil {
		w = chooseWorker(ctx, tx, workers)
	}
	aid := uuidStr()
	var workerID *string
	var offerExp *time.Time
	if w != nil {
		workerID = &w.UserID
		exp := time.Now().UTC().Add(30 * time.Minute)
		offerExp = &exp
	}
	_, err = tx.Exec(ctx, `INSERT INTO assignments (assignment_id, journey_id, kind, sequence, status, from_location_id, to_location_id, worker_id, sample_id, laboratory_id, offer_expires_at, offer_rank)
		VALUES ($1,$2,'laboratory',$3,'offered',$4,$4,$5,$6,$4,$7,$3)`,
		aid, journeyID, len(route), labID, workerID, in.sampleID, offerExp)
	if err != nil {
		return nil, errCode(500, "internal_error", err.Error())
	}
	res.LabAssigns = append(res.LabAssigns, aid)
	res.AssignmentIDs = append(res.AssignmentIDs, aid)

	return res, nil
}

