		_ = tx.QueryRow(ctx, `SELECT connection_id::text FROM connections WHERE from_location_id::text=$1 AND to_location_id::text=$2 AND cooled=$3 ORDER BY active DESC LIMIT 1`, from, to, cooled).Scan(&connID)
		ensureCapacityRow(ctx, tx, connID, "connection")
		workers, _ := eligibleWorkers(ctx, tx, "delivery_partner", "")
