	}
	q := auditQuery{
		Query:      req.Query,
		EntityType: req.EntityType,
		EntityID:   req.EntityID,
		ActorID:    req.ActorID,
		Action:     req.Action,
		Role:       req.Role,
		Limit:      req.Limit,
		Offset:     req.Offset,
		Order:      req.Order,
	}
	if req.FromTime != "" {
