	}
	if err := decodeJSON(r, &req); err != nil {
		writeError(w, errInvalidJSON)
		return
	}
	if req.Limit <= 0 {
		req.Limit = 50
	}
	if req.Order == "" {
		req.Order = "newest_first"
	}
	q := auditQuery{
		Query:      req.Query,
		EntityType: req.EntityType,
		EntityID:   req.EntityID,
		ActorID:    req.ActorID,
		Action:     req.Action,
		Role:       req.Role,
		Limit:      req.Limit,
		Offset:     req.Offset,
		Order:      req.Order,
	}
	if req.FromTime != "" {
		if t, e := parseTime(req.FromTime, "invalid_time"); e == nil {
			q.FromTime = t
		} else {
			writeError(w, e)
			return
		}
	}
	if req.ToTime != "" {
		if t, e := parseTime(req.ToTime, "invalid_time"); e == nil {
			q.ToTime = t
		} else {
			writeError(w, e)
			return
		}
	}
	res, err := auditSearch(r.Context(), a, q)
	if err != nil {
		writeError(w, errInternal)
		return
	}
	writeData(w, 200, res)
}

