	if err != nil {
		writeError(w, errConflict)
		return
	}
	a.audit(r.Context(), u, "edit_active_plan", "journey", req.JourneyID, true, map[string]any{"planVersion": req.PlanVersion})
	writeData(w, 201, map[string]any{
		"journeyId":   req.JourneyID,
		"planVersion": cur + 1,
	})
}

// handleSplitJourney implements POST /api/split-journey.
func (a *App) handleSplitJourney(w http.ResponseWriter, r *http.Request) {
