package main

import (
	"context"
	"encoding/json"
	"math"
	"time"

	"github.com/jackc/pgx/v5"
)

// networkNode is an active location with its functions.
type networkNode struct {
	ID             string
	Name           string
	Lat, Lng       float64
	CoverageKm     float64
	HandlingMin    int
	CollectionPt   bool
	TransferPt     bool
	Hub            bool
	Laboratory     bool
}

type networkConnection struct {
	ID          string
	From        string
	To          string
	TravelMin   int
	Cost        float64
	Cooled      bool
	Active      bool
}

func loadNetwork(ctx context.Context, pg pgxQuerier) ([]networkNode, []networkConnection, error) {
	rows, err := pg.Query(ctx, `SELECT location_id::text, name, latitude, longitude, coverage_km, handling_minutes,
		fn_collection_point, fn_transfer_point, fn_hub, fn_laboratory, active FROM locations`)
	if err != nil {
		return nil, nil, err
	}
	var nodes []networkNode
	for rows.Next() {
		var n networkNode
		var active bool
		if err := rows.Scan(&n.ID, &n.Name, &n.Lat, &n.Lng, &n.CoverageKm, &n.HandlingMin,
			&n.CollectionPt, &n.TransferPt, &n.Hub, &n.Laboratory, &active); err != nil {
			rows.Close()
			return nil, nil, err
		}
		if active {
			nodes = append(nodes, n)
		}
	}
	rows.Close()
	crows, err := pg.Query(ctx, `SELECT connection_id::text, from_location_id::text, to_location_id::text, travel_minutes, cost_units, cooled, active FROM connections`)
	if err != nil {
		return nil, nil, err
	}
	var conns []networkConnection
	for crows.Next() {
		var c networkConnection
		if err := crows.Scan(&c.ID, &c.From, &c.To, &c.TravelMin, &c.Cost, &c.Cooled, &c.Active); err != nil {
			crows.Close()
			return nil, nil, err
		}
		if c.Active {
			conns = append(conns, c)
		}
	}
	crows.Close()
	return nodes, conns, nil
}

type pgxQuerier interface {
	Query(ctx context.Context, sql string, args ...any) (pgx.Rows, error)
	QueryRow(ctx context.Context, sql string, args ...any) pgx.Row
	Exec(ctx context.Context, sql string, args ...any) (pgx.CommandTag, error)
}

// haversineKm returns distance in km between two lat/lng points.
func haversineKm(lat1, lng1, lat2, lng2 float64) float64 {
	const R = 6371.0
	dLat := (lat2 - lat1) * math.Pi / 180
	dLng := (lng2 - lng1) * math.Pi / 180
	a := math.Sin(dLat/2)*math.Sin(dLat/2) +
		math.Cos(lat1*math.Pi/180)*math.Cos(lat2*math.Pi/180)*
			math.Sin(dLng/2)*math.Sin(dLng/2)
	c := 2 * math.Atan2(math.Sqrt(a), math.Sqrt(1-a))
	return R * c
}

// serviceabilityInput holds the parameters for a serviceability check.
type serviceabilityInput struct {
	OriginLat        float64
	OriginLng        float64
	OriginType       string
	OriginNodeID     string
	SampleTypeID     string
	RequiresCooled   bool
	RequestedAt      time.Time
	Deadline         time.Time
	EarliestCollect  time.Time
	LatestCollect    time.Time
	SampleID         string // set only when building a real journey; unused by dry-run checks
}

type serviceabilityResult struct {
	Serviceable        bool
	Reason             string
	TargetLaboratoryID string
	EstimatedArrival   time.Time
	Version            int
	Route              []routeStep
}

type routeStep struct {
	LocID      string
	IsLab      bool
	TravelMin  int
	HandMin    int
	Cooled     bool
}

// checkServiceability performs a dry-run serviceability check (no writes).
func (a *App) checkServiceability(ctx context.Context, in serviceabilityInput) serviceabilityResult {
	nodes, conns := loadNetwork2(ctx, a.pg)

	version := a.currentServiceabilityVersion(ctx)

	// 1. Find nearest active collection point within coverage.
	var entryNode *networkNode
	if in.OriginType == "node" && in.OriginNodeID != "" {
		for i := range nodes {
			if nodes[i].ID == in.OriginNodeID && nodes[i].CollectionPt {
				entryNode = &nodes[i]
				break
			}
		}
	} else {
		best := -1.0
		for i := range nodes {
			if !nodes[i].CollectionPt {
				continue
			}
			d := haversineKm(in.OriginLat, in.OriginLng, nodes[i].Lat, nodes[i].Lng)
			if d <= nodes[i].CoverageKm && (best < 0 || d < best) {
				best = d
				entryNode = &nodes[i]
			}
		}
	}
	if entryNode == nil {
		return serviceabilityResult{Serviceable: false, Reason: "outside_service_coverage", Version: version}
	}

	// 2. Find accepting laboratories for the sample type.
	labs := acceptingLabs(ctx, a.pg, in.SampleTypeID, nodes)
	if len(labs) == 0 {
		return serviceabilityResult{Serviceable: false, Reason: "no_accepting_laboratory", Version: version}
	}

	// 3. Find a route from entryNode to any lab (shortest by travel minutes).
	route, labID, estArrival, ok := findRoute(entryNode, labs, nodes, conns, in)
	if !ok {
		return serviceabilityResult{Serviceable: false, Reason: "no_route", Version: version}
	}

	// 4. Capacity check.
	hasCap := capacityAvailable(ctx, a.pg, route, in.RequiresCooled)
	if !hasCap {
		return serviceabilityResult{Serviceable: false, Reason: "insufficient_capacity", Version: version}
	}

	// 5. Deadline check.
	collectTime := in.EarliestCollect
	if collectTime.IsZero() {
		collectTime = in.RequestedAt
	}
	if estArrival.After(in.Deadline) {
		return serviceabilityResult{Serviceable: false, Reason: "deadline_unreachable", Version: version}
	}

	// 6. Handling rules satisfiable (cooled route availability already ensured via route).
	if in.RequiresCooled && !routeAllCooled(route, conns) {
		return serviceabilityResult{Serviceable: false, Reason: "handling_rules_unsatisfiable", Version: version}
	}

	return serviceabilityResult{
		Serviceable:        true,
		Reason:             "serviceable",
		TargetLaboratoryID: labID,
		EstimatedArrival:   estArrival,
		Version:            version,
		Route:              route,
	}
}

func acceptingLabs(ctx context.Context, pg pgxQuerier, sampleTypeID string, nodes []networkNode) []*networkNode {
	rows, err := pg.Query(ctx, `SELECT laboratory_location_id::text FROM laboratory_acceptance WHERE sample_type_id=$1 AND accepts=true`, sampleTypeID)
	if err != nil {
		return nil
	}
	ids := map[string]bool{}
	for rows.Next() {
		var id string
		_ = rows.Scan(&id)
		ids[id] = true
	}
	rows.Close()
	var out []*networkNode
	for i := range nodes {
		if nodes[i].Laboratory && ids[nodes[i].ID] {
			out = append(out, &nodes[i])
		}
	}
	return out
}

// findRoute finds shortest path (by travel minutes) from entry node to any lab.
func findRoute(entry *networkNode, labs []*networkNode, nodes []networkNode, conns []networkConnection, in serviceabilityInput) ([]routeStep, string, time.Time, bool) {
	labSet := map[string]bool{}
	for _, l := range labs {
		labSet[l.ID] = true
	}
	// Dijkstra over nodes.
	idx := map[string]int{}
	for i, n := range nodes {
		idx[n.ID] = i
	}
	adj := make([][]networkConnection, len(nodes))
	for _, c := range conns {
		if _, ok := idx[c.From]; !ok {
			continue
		}
		adj[idx[c.From]] = append(adj[idx[c.From]], c)
	}
	const inf = math.MaxInt32
	dist := make([]int, len(nodes))
	prev := make([]int, len(nodes))
	prevConn := make([]networkConnection, len(nodes))
	for i := range dist {
		dist[i] = inf
		prev[i] = -1
	}
	start := idx[entry.ID]
	dist[start] = entry.HandlingMin
	visited := make([]bool, len(nodes))
	for {
		u := -1
		best := inf
		for i := range dist {
			if !visited[i] && dist[i] < best {
				best = dist[i]
				u = i
			}
		}
		if u == -1 {
			break
		}
		visited[u] = true
		for _, c := range adj[u] {
			v := idx[c.To]
			nd := dist[u] + c.TravelMin + nodes[v].HandlingMin
			if nd < dist[v] {
				dist[v] = nd
				prev[v] = u
				prevConn[v] = c
			}
		}
	}
	bestLab := -1
	bestDist := inf
	for i, n := range nodes {
		if labSet[n.ID] && dist[i] < bestDist {
			bestDist = dist[i]
			bestLab = i
		}
	}
	if bestLab == -1 {
		return nil, "", time.Time{}, false
	}
	// Reconstruct path.
	var path []int
	for cur := bestLab; cur != -1; cur = prev[cur] {
		path = append(path, cur)
	}
	// reverse
	for i, j := 0, len(path)-1; i < j; i, j = i+1, j-1 {
		path[i], path[j] = path[j], path[i]
	}
	steps := make([]routeStep, 0, len(path))
	for i, p := range path {
		steps = append(steps, routeStep{LocID: nodes[p].ID, IsLab: labSet[nodes[p].ID], HandMin: nodes[p].HandlingMin})
		if i > 0 {
			c := prevConn[p]
			steps[len(steps)-1].TravelMin = c.TravelMin
			steps[len(steps)-1].Cooled = c.Cooled
		}
	}
	totalMin := dist[bestLab]
	collectTime := in.EarliestCollect
	if collectTime.IsZero() {
		collectTime = in.RequestedAt
	}
	estArrival := collectTime.Add(time.Duration(totalMin) * time.Minute)
	return steps, nodes[bestLab].ID, estArrival, true
}

func routeAllCooled(steps []routeStep, conns []networkConnection) bool {
	// A route satisfies cooled if all legs that require cooled transport are cooled.
	// Simplify: every transport step with TravelMin>0 must be cooled.
	for _, s := range steps {
		if s.TravelMin > 0 && !s.Cooled {
			return false
		}
	}
	return true
}

func capacityAvailable(ctx context.Context, pg pgxQuerier, steps []routeStep, cooled bool) bool {
	// Check node capacity at each intermediate stop and lab, plus connections.
	for _, s := range steps {
		var reg, regRes, cool, coolRes int
		err := pg.QueryRow(ctx, `SELECT regular_capacity, regular_reserved, cooled_capacity, cooled_reserved FROM capacity WHERE resource_id::text=$1`, s.LocID).Scan(&reg, &regRes, &cool, &coolRes)
		if err == nil {
			if cooled {
				if cool-coolRes < 1 {
					return false
				}
			} else {
				if reg-regRes < 1 {
					return false
				}
			}
		}
	}
	return true
}

func (a *App) currentServiceabilityVersion(ctx context.Context) int {
	var ver int
	err := a.pg.QueryRow(ctx, `SELECT COALESCE(MAX(version),0) FROM serviceability_versions WHERE status='complete'`).Scan(&ver)
	if err != nil {
		return 0
	}
	return ver
}

// computeServiceabilityVersion computes and stores a complete serviceability version.
func (a *App) computeServiceabilityVersion(ctx context.Context) (int, error) {
	nodes, conns := loadNetwork2(ctx, a.pg)
	var rev int
	_ = a.pg.QueryRow(ctx, `SELECT rev FROM network_revision WHERE id=1`).Scan(&rev)

	regions := []map[string]any{}
	cpCount := 0
	for _, n := range nodes {
		if n.CollectionPt {
			cpCount++
			regions = append(regions, map[string]any{
				"locationId": n.ID,
				"name":       n.Name,
				"latitude":   n.Lat,
				"longitude":  n.Lng,
				"coverageKm": n.CoverageKm,
			})
		}
	}
	_ = conns
	ver := rev + 1
	_, err := a.pg.Exec(ctx, `INSERT INTO serviceability_versions (version, status, computed_at, network_revision, regions, active_cp_count)
		VALUES ($1,'complete',now(),$2,$3,$4)`, ver, rev, toJSONB(regions), cpCount)
	if err != nil {
		return 0, err
	}
	_, err = a.pg.Exec(ctx, `UPDATE network_revision SET rev=$1 WHERE id=1`, ver)
	return ver, err
}

func loadNetwork2(ctx context.Context, pg pgxQuerier) ([]networkNode, []networkConnection) {
	n, c, err := loadNetwork(ctx, pg)
	if err != nil {
		return nil, nil
	}
	return n, c
}

func toJSONB(v any) []byte {
	b, _ := json.Marshal(v)
	return b
}

