// handleCheckServiceability implements POST /api/check-serviceability (requester).
func (a *App) handleCheckServiceability(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		writeError(w, errCode(405, "method_not_allowed", "POST required"))
		return
	}
	u := currentUser(r)
	if e := requireRole(u, "requester", "administrator", "dispatcher"); e != nil {
		writeError(w, e)
		return
	}
	var req struct {
		OriginType      string  `json:"originType"`
		OriginLatitude  float64 `json:"originLatitude"`
		OriginLongitude float64 `json:"originLongitude"`
		OriginNodeID    string  `json:"originNodeId"`
		SampleTypeID    string  `json:"sampleTypeId"`
		DeliveryDeadline string `json:"deliveryDeadline"`
		EarliestCollection string `json:"earliestCollection"`
		LatestCollection   string `json:"latestCollection"`
		IdempotencyKey   string  `json:"idempotencyKey"`
	}
	if err := decodeJSON(r, &req); err != nil {
		writeError(w, errInvalidJSON)
		return
	}
	deadline, e := parseTime(req.DeliveryDeadline, "invalid_time")
	if e != nil {
		writeError(w, e)
		return
	}
	var earliest, latest time.Time
	if req.EarliestCollection != "" {
		earliest, e = parseTime(req.EarliestCollection, "invalid_time")
		if e != nil {
			writeError(w, e)
			return
		}
	}
	if req.LatestCollection != "" {
		latest, e = parseTime(req.LatestCollection, "invalid_time")
		if e != nil {
			writeError(w, e)
			return
		}
	}
	st, err := loadSampleType(r.Context(), a.pg, req.SampleTypeID)
	if err != nil {
		writeError(w, errCode(400, "invalid_sample_type", "unknown sample type"))
		return
	}
	in := serviceabilityInput{
		OriginType:     req.OriginType,
		OriginLat:      req.OriginLatitude,
		OriginLng:      req.OriginLongitude,
		OriginNodeID:   req.OriginNodeID,
		SampleTypeID:   req.SampleTypeID,
		RequiresCooled: st.RequiresCooled,
		RequestedAt:    time.Now().UTC(),
		Deadline:       deadline,
		EarliestCollect: earliest,
		LatestCollect:   latest,
	}
	res := a.checkServiceability(r.Context(), in)
	// Dry run: write nothing but an audit trail marker.
	a.audit(r.Context(), u, "check_serviceability", "serviceability", req.SampleTypeID, res.Serviceable, map[string]any{"reason": res.Reason})
	out := map[string]any{
		"serviceable":  res.Serviceable,
		"reason":       res.Reason,
		"version":      res.Version,
		"deliveryDeadline": req.DeliveryDeadline,
	}
	if res.Serviceable {
		out["targetLaboratoryId"] = res.TargetLaboratoryID
		out["estimatedArrival"] = rfc(res.EstimatedArrival)
		steps := make([]map[string]any, 0, len(res.Route))
		for _, s := range res.Route {
			steps = append(steps, map[string]any{
				"locationId": s.LocID,
				"isLab":      s.IsLab,
				"travelMinutes": s.TravelMin,
				"handlingMinutes": s.HandMin,
				"cooled":     s.Cooled,
			})
		}
		out["route"] = steps
	}
	writeData(w, 200, out)
}

// handleCreateCollectionRequest implements POST /api/create-collection-request (requester).
func (a *App) handleCreateCollectionRequest(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		writeError(w, errCode(405, "method_not_allowed", "POST required"))
		return
	}
	u := currentUser(r)
	if e := requireRole(u, "requester"); e != nil {
		writeError(w, e)
		return
	}
	var req struct {
		OriginType        string  `json:"originType"`
		OriginLatitude    float64 `json:"originLatitude"`
		OriginLongitude   float64 `json:"originLongitude"`
		OriginNodeId      string  `json:"originNodeId"`
		OriginAddress     string  `json:"originAddress"`
		SampleTypeId      string  `json:"sampleTypeId"`
		DeliveryDeadline  string  `json:"deliveryDeadline"`
		EarliestCollection string `json:"earliestCollection"`
		LatestCollection   string  `json:"latestCollection"`
		Notes             string  `json:"notes"`
		IdempotencyKey    string  `json:"idempotencyKey"`
	}
	if err := decodeJSON(r, &req); err != nil {
		writeError(w, errInvalidJSON)
		return
	}
	if req.OriginType == "home" {
		// home origin must not have a node id
	} else if req.OriginType != "clinic" && req.OriginType != "node" {
		writeError(w, errCode(400, "invalid_origin", "invalid origin type"))
		return
	}
	deadline, e := parseTime(req.DeliveryDeadline, "invalid_time")
	if e != nil {
		writeError(w, e)
		return
	}
	var earliest, latest time.Time
	if req.EarliestCollection != "" {
