   155	func normalizeRealtime(d map[string]any) map[string]any {
   156		out := map[string]any{}
   157		for k, v := range d {
   158			if k == "_id" {
   159				continue
   160			}
   161			out[k] = v
   162		}
   163		if _, ok := out["id"]; !ok {
   164			if s, ok := out["seq"]; ok {
   165				out["id"] = s
   166			}
   167		}
   168		return out
   169	}
