   171	func parseQueryInt(r *http.Request, key string) int64 {
   172		v := r.URL.Query().Get(key)
   173		if v == "" {
   174			return 0
   175		}
   176		var n int64
   177		for _, c := range v {
   178			if c < '0' || c > '9' {
   179				return 0
   180			}
   181			n = n*10 + int64(c-'0')
   182		}
   183		return n
   184	}
