   322		// Check node capacity at each intermediate stop and lab, plus connections.
   323		for _, s := range steps {
   324			var reg, regRes, cool, coolRes int
   325			err := pg.QueryRow(ctx, `SELECT regular_capacity, regular_reserved, cooled_capacity, cooled_reserved FROM capacity WHERE resource_id::text=$1`, s.LocID).Scan(&reg, &regRes, &cool, &coolRes)
   326			if err == nil {
   327				if cooled {
   328					if cool-coolRes < 1 {
   329						return false
   330					}
   331				} else {
   332					if reg-regRes < 1 {
   333						return false
   334					}
   335				}
   336			}
   337		}
   338		return true
   339	}
