   190	// parseTime parses an RFC3339 timestamp, returning an apiError on failure.
   191	func parseTime(s string, code string) (time.Time, *apiError) {
   192		if s == "" {
   193			return time.Time{}, errCode(400, code, "missing time")
   194		}
   195		t, err := time.Parse(time.RFC3339Nano, s)
   196		if err != nil {
   197			t, err = time.Parse(time.RFC3339, s)
   198			if err != nil {
   199				return time.Time{}, errCode(400, code, "invalid time")
   200			}
   201		}
   202		return t.UTC(), nil
   203	}
