   277	// reofferAssignment clears the current worker and offers to the next eligible worker.
   278	func (a *App) reofferAssignment(ctx context.Context, ar *assignmentRow, declinedWorker string) {
   279		role := roleForKind(ar.Kind)
   280		qual := ""
   281		if ar.Kind == "collection" {
   282			var stName string
   283			_ = a.pg.QueryRow(ctx, `SELECT st.name FROM samples s JOIN sample_types st ON st.sample_type_id=s.sample_type_id WHERE s.sample_id::text=$1`, strPtr(ar.SampleID)).Scan(&stName)
   284			qual = stName
   285		}
   286		workers, _ := eligibleWorkers(ctx, a.pg, role, qual)
   287		var next *workerSummary
   288		for i := range workers {
   289			if workers[i].UserID == declinedWorker {
   290				continue
   291			}
   292			if ar.Kind == "node" || ar.Kind == "laboratory" {
   293				locID := strPtr(ar.NodeID)
   294				if ar.Kind == "laboratory" {
   295					locID = strPtr(ar.LabID)
   296				}
   297				if workers[i].AssignedLocationID != nil && *workers[i].AssignedLocationID == locID {
   298					next = &workers[i]
   299					break
   300				}
   301				continue
   302			}
   303			next = &workers[i]
   304			break
   305		}
   306		var workerID *string
   307		var exp *time.Time
   308		if next != nil {
   309			workerID = &next.UserID
   310			e := time.Now().UTC().Add(30 * time.Minute)
   311			exp = &e
   312		}
   313		_, _ = a.pg.Exec(ctx, `UPDATE assignments SET worker_id=$1, offer_expires_at=$2, offer_rank=offer_rank+1 WHERE assignment_id::text=$3`, workerID, exp, ar.AssignmentID)
   314	}
