   125	// checkServiceability performs a dry-run serviceability check (no writes).
   126	func (a *App) checkServiceability(ctx context.Context, in serviceabilityInput) serviceabilityResult {
   127		nodes, conns := loadNetwork2(ctx, a.pg)
   128	
   129		version := a.currentServiceabilityVersion(ctx)
   130	
   131		// 1. Find nearest active collection point within coverage.
   132		var entryNode *networkNode
   133		if in.OriginType == "node" && in.OriginNodeID != "" {
   134			for i := range nodes {
   135				if nodes[i].ID == in.OriginNodeID && nodes[i].CollectionPt {
   136					entryNode = &nodes[i]
   137					break
   138				}
   139			}
   140		} else {
   141			best := -1.0
   142			for i := range nodes {
   143				if !nodes[i].CollectionPt {
   144					continue
   145				}
   146				d := haversineKm(in.OriginLat, in.OriginLng, nodes[i].Lat, nodes[i].Lng)
   147				if d <= nodes[i].CoverageKm && (best < 0 || d < best) {
   148					best = d
   149					entryNode = &nodes[i]
   150				}
   151			}
   152		}
   153		if entryNode == nil {
   154			return serviceabilityResult{Serviceable: false, Reason: "outside_service_coverage", Version: version}
   155		}
   156	
   157		// 2. Find accepting laboratories for the sample type.
   158		labs := acceptingLabs(ctx, a.pg, in.SampleTypeID, nodes)
   159		if len(labs) == 0 {
   160			return serviceabilityResult{Serviceable: false, Reason: "no_accepting_laboratory", Version: version}
   161		}
   162	
   163		// 3. Find a route from entryNode to any lab (shortest by travel minutes).
   164		route, labID, estArrival, ok := findRoute(entryNode, labs, nodes, conns, in)
   165		if !ok {
   166			return serviceabilityResult{Serviceable: false, Reason: "no_route", Version: version}
   167		}
   168	
   169		// 4. Capacity check.
   170		hasCap := capacityAvailable(ctx, a.pg, route, in.RequiresCooled)
   171		if !hasCap {
   172			return serviceabilityResult{Serviceable: false, Reason: "insufficient_capacity", Version: version}
   173		}
   174	
   175		// 5. Deadline check.
   176		collectTime := in.EarliestCollect
   177		if collectTime.IsZero() {
   178			collectTime = in.RequestedAt
   179		}
   180		if estArrival.After(in.Deadline) {
   181			return serviceabilityResult{Serviceable: false, Reason: "deadline_unreachable", Version: version}
   182		}
   183	
   184		// 6. Handling rules satisfiable (cooled route availability already ensured via route).
   185		if in.RequiresCooled && !routeAllCooled(route, conns) {
   186			return serviceabilityResult{Serviceable: false, Reason: "handling_rules_unsatisfiable", Version: version}
   187		}
   188	
   189		return serviceabilityResult{
   190			Serviceable:        true,
   191			Reason:             "serviceable",
   192			TargetLaboratoryID: labID,
   193			EstimatedArrival:   estArrival,
   194			Version:            version,
   195			Route:              route,
   196		}
   197	}
