   118	// eligibleWorkers returns workers holding one of the given roles and (for collectors) the qualification.
   119	func eligibleWorkers(ctx context.Context, pg pgxQuerier, role string, requireQual string) ([]workerSummary, error) {
   120		rows, err := pg.Query(ctx, `
   121			SELECT u.user_id::text, u.full_name, u.roles, u.qualifications, u.assigned_location_id::text,
   122				COALESCE(wp.available,true), COALESCE(wp.capacity_units,1)
   123			FROM users u LEFT JOIN worker_profiles wp ON wp.worker_id=u.user_id
   124			WHERE u.active=true AND $1=ANY(u.roles)`, role)
   125		if err != nil {
   126			return nil, err
   127		}
   128		defer rows.Close()
   129		var out []workerSummary
   130		for rows.Next() {
   131			var w workerSummary
   132			var roles, quals []string
   133			var assigned *string
   134			if err := rows.Scan(&w.UserID, &w.FullName, &roles, &quals, &assigned, &w.Available, &w.Capacity); err != nil {
   135				return nil, err
   136			}
   137			w.Roles = roles
   138			w.Qualifications = quals
   139			if assigned != nil {
   140				s := *assigned
   141				w.AssignedLocationID = &s
   142			}
   143			if requireQual != "" {
   144				has := false
   145				for _, q := range quals {
   146					if q == requireQual {
   147						has = true
   148						break
   149					}
   150				}
   151				if !has {
   152					continue
   153				}
   154			}
   155			out = append(out, w)
   156		}
   157		return out, nil
   158	}
