   194	// reserveCapacity increments reserved units for a resource (cooled or regular).
   195	func reserveCapacity(ctx context.Context, pg pgxQuerier, resourceID string, cooled bool) error {
   196		if resourceID == "" {
   197			return nil
   198		}
   199		if cooled {
