   227	func (a *App) buildJourneyOn(ctx context.Context, tx pgxTx, in serviceabilityInput, st *sampleTypeRow, entry *networkNode, route []routeStep, labID string, estArrival time.Time, alreadySealed bool, sampleID string) (*planJourneyResult, *apiError) {
   228		journeyID := uuidStr()
   229		routeMode := "direct"
   230		if len(route) > 2 {
   231			routeMode = "multi_stop"
   232		}
   233		collectTime := in.EarliestCollect
   234		if collectTime.IsZero() {
   235			collectTime = in.RequestedAt
   236		}
   237		var totalCost float64
   238		for _, s := range route {
   239			totalCost += float64(s.TravelMin)
   240		}
   241	
   242		_, err := tx.Exec(ctx, `INSERT INTO journeys (journey_id, parent_journey_id, plan_version, route_mode, status, estimated_delivery_at, total_cost_units, valid, target_laboratory_id, already_sealed)
   243			VALUES ($1,NULL,1,$2,'planned',$3,$4,true,$5,$6)`,
   244			journeyID, routeMode, estArrival, totalCost, labID, alreadySealed)
   245		if err != nil {
   246			return nil, errCode(500, "internal_error", err.Error())
   247		}
   248	
   249		res := &planJourneyResult{
   250			JourneyID:          journeyID,
   251			PlanVersion:        1,
   252			RouteMode:          routeMode,
   253			TargetLaboratoryID: labID,
   254			EstimatedArrival:   estArrival,
   255			TotalCost:           totalCost,
   256		}
   257	
   258		seq := 0
   259		nowOffset := collectTime
   260		for i, s := range route {
   261			seq++
   262			stopID := uuidStr()
   263			stopType := "handoff"
   264			if i == 0 {
   265				stopType = "pickup"
   266			}
   267			if s.IsLab {
   268				stopType = "delivery"
   269			}
   270			est := nowOffset
   271			if i > 0 {
   272				est = nowOffset.Add(time.Duration(s.TravelMin) * time.Minute)
   273			}
   274			_, err := tx.Exec(ctx, `INSERT INTO journey_stops (stop_id, journey_id, location_id, stop_type, sequence, estimated_at, dwell_minutes)
   275				VALUES ($1,$2,$3,$4,$5,$6,$7)`, stopID, journeyID, s.LocID, stopType, seq, est, s.HandMin)
   276			if err != nil {
   277				return nil, errCode(500, "internal_error", err.Error())
   278			}
   279			res.Stops = append(res.Stops, planRouteStep{LocID: s.LocID, IsLab: s.IsLab, IsEntry: i == 0, TravelMin: s.TravelMin, HandMin: s.HandMin, Cooled: s.Cooled})
   280			nowOffset = est.Add(time.Duration(s.HandMin) * time.Minute)
   281		}
   282	
   283		// 1. Collection assignment (skip when already sealed).
   284		if !alreadySealed {
   285			workers, _ := eligibleWorkers(ctx, tx, "collection_professional", st.Name)
   286			w := chooseWorker(ctx, tx, workers)
   287			aid := uuidStr()
   288			var workerID *string
   289			var offerExp *time.Time
   290			if w != nil {
   291				workerID = &w.UserID
   292				exp := time.Now().UTC().Add(30 * time.Minute)
   293				offerExp = &exp
   294			}
   295			_, err := tx.Exec(ctx, `INSERT INTO assignments (assignment_id, journey_id, kind, sequence, status, from_location_id, to_location_id, worker_id, sample_id, node_id, offer_expires_at, offer_rank)
   296				VALUES ($1,$2,'collection',1,'offered',$3,$3,$4,$5,$3,$6,0)`,
   297				aid, journeyID, entry.ID, workerID, sampleID, offerExp)
   298			if err != nil {
   299				return nil, errCode(500, "internal_error", err.Error())
   300			}
