   310			var connID string
   311			_ = tx.QueryRow(ctx, `SELECT connection_id::text FROM connections WHERE from_location_id::text=$1 AND to_location_id::text=$2 AND cooled=$3 ORDER BY active DESC LIMIT 1`, from, to, cooled).Scan(&connID)
   312			ensureCapacityRow(ctx, tx, connID, "connection")
   313			workers, _ := eligibleWorkers(ctx, tx, "delivery_partner", "")
   314			w := chooseWorker(ctx, tx, workers)
   315			aid := uuidStr()
   316			var workerID *string
   317			var offerExp *time.Time
   318			if w != nil {
   319				workerID = &w.UserID
