   337			}
   338			workers, _ := eligibleWorkers(ctx, tx, "node_handler", "")
   339			var w *workerSummary
   340			for j := range workers {
   341				if workers[j].AssignedLocationID != nil && *workers[j].AssignedLocationID == s.LocID {
   342					w = &workers[j]
   343					break
   344				}
   345			}
   346			if w == nil {
   347				w = chooseWorker(ctx, tx, workers)
   348			}
   349			aid := uuidStr()
   350			var workerID *string
   351			var offerExp *time.Time
   352			if w != nil {
   353				workerID = &w.UserID
   354				exp := time.Now().UTC().Add(30 * time.Minute)
   355				offerExp = &exp
   356			}
   357			_, err := tx.Exec(ctx, `INSERT INTO assignments (assignment_id, journey_id, kind, sequence, status, from_location_id, to_location_id, worker_id, sample_id, node_id, offer_expires_at, offer_rank)
   358				VALUES ($1,$2,'node',$3,'offered',$4,$4,$5,$6,$4,$7,$3)`,
   359				aid, journeyID, i, s.LocID, workerID, sampleID, offerExp)
   360			if err != nil {
   361				return nil, errCode(500, "internal_error", err.Error())
   362			}
   363			res.NodeAssigns = append(res.NodeAssigns, aid)
   364			res.AssignmentIDs = append(res.AssignmentIDs, aid)
   365		}
   366	
   367		// 4. Laboratory assignment.
   368		workers, _ := eligibleWorkers(ctx, tx, "laboratory_team", "")
   369		var w *workerSummary
   370		for j := range workers {
   371			if workers[j].AssignedLocationID != nil && *workers[j].AssignedLocationID == labID {
   372				w = &workers[j]
   373				break
   374			}
   375		}
   376		if w == nil {
