   378		}
   379		aid := uuidStr()
   380		var workerID *string
   381		var offerExp *time.Time
   382		if w != nil {
   383			workerID = &w.UserID
   384			exp := time.Now().UTC().Add(30 * time.Minute)
   385			offerExp = &exp
   386		}
   387		_, err = tx.Exec(ctx, `INSERT INTO assignments (assignment_id, journey_id, kind, sequence, status, from_location_id, to_location_id, worker_id, sample_id, laboratory_id, offer_expires_at, offer_rank)
   388			VALUES ($1,$2,'laboratory',$3,'offered',$4,$4,$5,$6,$4,$7,$3)`,
   389			aid, journeyID, len(route), labID, workerID, sampleID, offerExp)
