    70	// tx runs fn inside a serializable transaction with retry on snapshot conflict.
    71	func (a *App) tx(ctx context.Context, fn func(pgxTx) error) error {
    72		for i := 0; i < 4; i++ {
    73			err := func() error {
    74				t, err := a.pg.BeginTx(ctx, pgx.TxOptions{IsoLevel: pgx.Serializable})
    75				if err != nil {
    76					return err
    77				}
    78				defer t.Rollback(ctx)
    79				if err := fn(t); err != nil {
    80					return err
    81				}
    82				return t.Commit(ctx)
    83			}()
    84			if err == nil {
    85				return nil
    86			}
    87			if isSnapshotConflict(err) {
    88				time.Sleep(time.Duration(20<<(i)) * time.Millisecond)
    89				continue
    90			}
    91			return err
    92		}
    93		return errors.New("concurrent_conflict")
    94	}
