    11	// MaterializeMongo creates collections and indexes so reset materializes structure.
    12	func (a *App) MaterializeMongo(ctx context.Context) error {
    13		db := a.mdb
    14		colls := []string{"audit_events", "realtime_events", "audit_requests"}
    15		for _, c := range colls {
    16			if err := db.CreateCollection(ctx, c); err != nil {
    17				// ignore already exists
    18				if !isMongoAlreadyExists(err) {
    19					return err
    20				}
    21			}
    22		}
    23		indexes := map[string][]mongoIndex{
    24			"audit_events": {
    25				{Keys: bson.D{{Key: "occurredAt", Value: 1}}},
    26				{Keys: bson.D{{Key: "entityType", Value: 1}, {Key: "entityId", Value: 1}}},
    27				{Keys: bson.D{{Key: "actorId", Value: 1}, {Key: "occurredAt", Value: -1}}},
    28				{Keys: bson.D{{Key: "action", Value: 1}}},
    29			},
    30			"realtime_events": {
    31				{Keys: bson.D{{Key: "seq", Value: 1}}, Unique: true},
    32				{Keys: bson.D{{Key: "createdAt", Value: 1}}},
    33				{Keys: bson.D{{Key: "entityType", Value: 1}, {Key: "createdAt", Value: -1}}},
    34			},
    35			"audit_requests": {
    36				{Keys: bson.D{{Key: "requestId", Value: 1}}},
    37			},
    38		}
    39		for coll, idxs := range indexes {
    40			c := db.Collection(coll)
    41			var models []mongo.IndexModel
    42			for _, ix := range idxs {
    43				im := mongo.IndexModel{Keys: ix.Keys}
    44				iopts := options.Index()
    45				if ix.Unique {
    46					iopts.SetUnique(true)
    47				}
    48				im.Options = iopts
    49				models = append(models, im)
    50			}
    51			_, err := c.Indexes().CreateMany(ctx, models)
    52			if err != nil && !isMongoAlreadyExists(err) {
    53				return err
    54			}
    55		}
    56		return nil
    57	}
