   149		order := 1
   150		if q.Order == "newest_first" {
   151			order = -1
   152		}
   153		opts := options.Find().SetSort(bson.D{{Key: "occurredAt", Value: order}, {Key: "_id", Value: order}}).
   154			SetSkip(int64(q.Offset)).SetLimit(int64(q.Limit))
   155		cur, err := a.mdb.Collection("audit_events").Find(ctx, filter, opts)
   156		if err != nil {
