   177	// chooseWorker picks the eligible available worker with the fewest current assignments (fair assignment).
   178	func chooseWorker(ctx context.Context, pg pgxQuerier, workers []workerSummary) *workerSummary {
   179		var best *workerSummary
   180		bestCount := -1
   181		for i := range workers {
   182			if !workers[i].Available {
   183				continue
   184			}
   185			n := assignmentCount(ctx, pg, workers[i].UserID)
   186			if bestCount < 0 || n < bestCount {
   187				bestCount = n
   188				best = &workers[i]
   189			}
   190		}
   191		return best
   192	}
