    81	// haversineKm returns distance in km between two lat/lng points.
    82	func haversineKm(lat1, lng1, lat2, lng2 float64) float64 {
    83		const R = 6371.0
    84		dLat := (lat2 - lat1) * math.Pi / 180
    85		dLng := (lng2 - lng1) * math.Pi / 180
    86		a := math.Sin(dLat/2)*math.Sin(dLat/2) +
    87			math.Cos(lat1*math.Pi/180)*math.Cos(lat2*math.Pi/180)*
    88				math.Sin(dLng/2)*math.Sin(dLng/2)
    89		c := 2 * math.Atan2(math.Sqrt(a), math.Sqrt(1-a))
    90		return R * c
    91	}
