   220	// findRoute finds shortest path (by travel minutes) from entry node to any lab.
   221	func findRoute(entry *networkNode, labs []*networkNode, nodes []networkNode, conns []networkConnection, in serviceabilityInput) ([]routeStep, string, time.Time, bool) {
   222		labSet := map[string]bool{}
   223		for _, l := range labs {
   224			labSet[l.ID] = true
   225		}
   226		// Dijkstra over nodes.
   227		idx := map[string]int{}
   228		for i, n := range nodes {
   229			idx[n.ID] = i
   230		}
   231		adj := make([][]networkConnection, len(nodes))
   232		for _, c := range conns {
   233			if _, ok := idx[c.From]; !ok {
   234				continue
   235			}
   236			adj[idx[c.From]] = append(adj[idx[c.From]], c)
   237		}
   238		const inf = math.MaxInt32
   239		dist := make([]int, len(nodes))
   240		prev := make([]int, len(nodes))
   241		prevConn := make([]networkConnection, len(nodes))
   242		for i := range dist {
   243			dist[i] = inf
   244			prev[i] = -1
   245		}
   246		start := idx[entry.ID]
   247		dist[start] = entry.HandlingMin
   248		visited := make([]bool, len(nodes))
   249		for {
   250			u := -1
   251			best := inf
   252			for i := range dist {
   253				if !visited[i] && dist[i] < best {
   254					best = dist[i]
   255					u = i
   256				}
   257			}
   258			if u == -1 {
   259				break
   260			}
   261			visited[u] = true
   262			for _, c := range adj[u] {
   263				v := idx[c.To]
   264				nd := dist[u] + c.TravelMin + nodes[v].HandlingMin
   265				if nd < dist[v] {
   266					dist[v] = nd
   267					prev[v] = u
   268					prevConn[v] = c
   269				}
   270			}
   271		}
   272		bestLab := -1
   273		bestDist := inf
   274		for i, n := range nodes {
   275			if labSet[n.ID] && dist[i] < bestDist {
   276				bestDist = dist[i]
   277				bestLab = i
   278			}
   279		}
   280		if bestLab == -1 {
   281			return nil, "", time.Time{}, false
   282		}
   283		// Reconstruct path.
   284		var path []int
   285		for cur := bestLab; cur != -1; cur = prev[cur] {
   286			path = append(path, cur)
   287		}
   288		// reverse
   289		for i, j := 0, len(path)-1; i < j; i, j = i+1, j-1 {
   290			path[i], path[j] = path[j], path[i]
   291		}
   292		steps := make([]routeStep, 0, len(path))
   293		for i, p := range path {
   294			steps = append(steps, routeStep{LocID: nodes[p].ID, IsLab: labSet[nodes[p].ID], HandMin: nodes[p].HandlingMin})
   295			if i > 0 {
   296				c := prevConn[p]
   297				steps[len(steps)-1].TravelMin = c.TravelMin
   298				steps[len(steps)-1].Cooled = c.Cooled
   299			}
   300		}
   301		totalMin := dist[bestLab]
   302		collectTime := in.EarliestCollect
   303		if collectTime.IsZero() {
   304			collectTime = in.RequestedAt
   305		}
   306		estArrival := collectTime.Add(time.Duration(totalMin) * time.Minute)
   307		return steps, nodes[bestLab].ID, estArrival, true
   308	}
   309	
   310	func routeAllCooled(steps []routeStep, conns []networkConnection) bool {
   311		// A route satisfies cooled if all legs that require cooled transport are cooled.
   312		// Simplify: every transport step with TravelMin>0 must be cooled.
   313		for _, s := range steps {
   314			if s.TravelMin > 0 && !s.Cooled {
   315				return false
   316			}
   317		}
   318		return true
   319	}
   320	
   321	func capacityAvailable(ctx context.Context, pg pgxQuerier, steps []routeStep, cooled bool) bool {
   322		// Check node capacity at each intermediate stop and lab, plus connections.
   323		for _, s := range steps {
   324			var reg, regRes, cool, coolRes int
   325			err := pg.QueryRow(ctx, `SELECT regular_capacity, regular_reserved, cooled_capacity, cooled_reserved FROM capacity WHERE resource_id::text=$1`, s.LocID).Scan(&reg, &regRes, &cool, &coolRes)
   326			if err == nil {
   327				if cooled {
   328					if cool-coolRes < 1 {
   329						return false
   330					}
   331				} else {
   332					if reg-regRes < 1 {
   333						return false
   334					}
   335				}
   336			}
   337		}
   338		return true
   339	}
