   350	// computeServiceabilityVersion computes and stores a complete serviceability version.
   351	func (a *App) computeServiceabilityVersion(ctx context.Context) (int, error) {
   352		nodes, conns := loadNetwork2(ctx, a.pg)
   353		var rev int
   354		_ = a.pg.QueryRow(ctx, `SELECT rev FROM network_revision WHERE id=1`).Scan(&rev)
   355	
   356		regions := []map[string]any{}
   357		cpCount := 0
   358		for _, n := range nodes {
   359			if n.CollectionPt {
   360				cpCount++
   361				regions = append(regions, map[string]any{
   362					"locationId": n.ID,
   363					"name":       n.Name,
   364					"latitude":   n.Lat,
   365					"longitude":  n.Lng,
   366					"coverageKm": n.CoverageKm,
   367				})
   368			}
   369		}
   370		_ = conns
   371		ver := rev + 1
   372		_, err := a.pg.Exec(ctx, `INSERT INTO serviceability_versions (version, status, computed_at, network_revision, regions, active_cp_count)
   373			VALUES ($1,'complete',now(),$2,$3,$4)`, ver, rev, toJSONB(regions), cpCount)
   374		if err != nil {
   375			return 0, err
   376		}
   377		_, err = a.pg.Exec(ctx, `UPDATE network_revision SET rev=$1 WHERE id=1`, ver)
   378		return ver, err
   379	}
