   320	func (a *App) handleConfigureCapacity(w http.ResponseWriter, r *http.Request) {
   321		if r.Method != http.MethodPost {
   322			writeError(w, errCode(405, "method_not_allowed", "POST required"))
   323			return
   324		}
   325		u := currentUser(r)
   326		if e := requireRole(u, "administrator", "dispatcher", "node_handler", "laboratory_team"); e != nil {
   327			writeError(w, e)
   328			return
   329		}
   330		var req struct {
   331			ResourceID       string  `json:"resourceId"`
   332			ResourceKind    string  `json:"resourceKind"`
   333			RegularCapacity  *int    `json:"regularCapacity"`
   334			CooledCapacity   *int    `json:"cooledCapacity"`
   335		}
   336		if err := decodeJSON(r, &req); err != nil {
   337			writeError(w, errInvalidJSON)
   338			return
   339		}
   340		if req.ResourceID == "" || req.ResourceKind == "" {
   341			writeError(w, errCode(400, "invalid_capacity", "missing fields"))
   342			return
   343		}
   344		// Node/lab handlers may only configure their own assigned node/lab.
   345		if u.ActiveRole == "node_handler" || u.ActiveRole == "laboratory_team" {
   346			var assigned *string
   347			_ = a.pg.QueryRow(r.Context(), `SELECT assigned_location_id::text FROM users WHERE user_id::text=$1`, u.UserID).Scan(&assigned)
   348			if assigned == nil || *assigned != req.ResourceID {
   349				writeError(w, errForbidden)
   350				return
   351			}
   352		}
   353		ensureCapacityRow(r.Context(), a.pg, req.ResourceID, req.ResourceKind)
   354		if req.RegularCapacity != nil {
   355			_, _ = a.pg.Exec(r.Context(), `UPDATE capacity SET regular_capacity=$1 WHERE resource_id::text=$2`, *req.RegularCapacity, req.ResourceID)
   356		}
   357		if req.CooledCapacity != nil {
   358			_, _ = a.pg.Exec(r.Context(), `UPDATE capacity SET cooled_capacity=$1 WHERE resource_id::text=$2`, *req.CooledCapacity, req.ResourceID)
   359		}
   360		a.audit(r.Context(), u, "configure_capacity", "capacity", req.ResourceID, true, map[string]any{"regular": req.RegularCapacity, "cooled": req.CooledCapacity})
   361		writeData(w, 201, a.capacityOut(r.Context(), req.ResourceID))
   362	}
