   212	func parseUUID(s string) (string, bool) {
   213		if len(s) != 36 {
   214			return "", false
   215		}
   216		// basic shape check
   217		for i, c := range s {
   218			switch i {
   219			case 8, 13, 18, 23:
   220				if c != '-' {
   221					return "", false
   222				}
   223			default:
   224				if !((c >= '0' && c <= '9') || (c >= 'a' && c <= 'f') || (c >= 'A' && c <= 'F')) {
   225					return "", false
   226				}
   227			}
   228		}
   229		return strings.ToLower(s), true
   230	}
