   232	// withIdempotency wraps a handler that needs idempotency_key, returning stored response on repeat.
   233	func (a *App) withIdempotency(r *http.Request, op, key string, fn func() (any, int, *apiError)) (any, int, *apiError) {
   234		if key == "" {
   235			return nil, 400, errCode(400, "idempotency_required", "idempotencyKey required")
   236		}
   237		// check existing
   238		var respBytes []byte
   239		var sc int
   240		err := a.pg.QueryRow(r.Context(), `SELECT response, status_code FROM idempotency_keys WHERE key=$1 AND operation=$2`, key, op).Scan(&respBytes, &sc)
   241		if err == nil {
   242			// replay
   243			var data any
   244			_ = json.Unmarshal(respBytes, &data)
   245			return data, sc, nil
   246		}
   247		data, status, e := fn()
   248		if e != nil {
   249			return nil, e.status, e
   250		}
   251		b, _ := json.Marshal(data)
   252		_, _ = a.pg.Exec(r.Context(), `INSERT INTO idempotency_keys (key, operation, response, status_code) VALUES ($1,$2,$3,$4) ON CONFLICT DO NOTHING`, key, op, b, status)
   253		return data, status, nil
   254	}

