   222	// handleConfirmHandoff implements POST /api/confirm-handoff.
   223	func (a *App) handleConfirmHandoff(w http.ResponseWriter, r *http.Request) {
   224		if r.Method != http.MethodPost {
   225			writeError(w, errCode(405, "method_not_allowed", "POST required"))
   226			return
   227		}
   228		u := currentUser(r)
   229		if e := requireRole(u, workerRoles()...); e != nil {
   230			writeError(w, e)
   231			return
   232		}
   233		var req struct {
   234			HandoffID string `json:"handoffId"`
   235		}
   236		if err := decodeJSON(r, &req); err != nil {
   237			writeError(w, errInvalidJSON)
   238			return
   239		}
   240		var sampleID, toAssignID, senderID, receiverID string
   241		var senderConf bool
   242		err := a.pg.QueryRow(r.Context(), `SELECT sample_id::text, to_assignment_id::text, sender_id::text, COALESCE(receiver_id::text,''), sender_confirmed FROM handoffs WHERE handoff_id::text=$1`, req.HandoffID).
   243			Scan(&sampleID, &toAssignID, &senderID, &receiverID, &senderConf)
   244		if err != nil {
   245			writeError(w, errNotFound)
   246			return
   247		}
   248		// Determine whether current user is receiver (next assignment worker) or sender confirming.
   249		if u.UserID == senderID {
   250			_, _ = a.pg.Exec(r.Context(), `UPDATE handoffs SET sender_confirmed=true WHERE handoff_id::text=$1`, req.HandoffID)
   251		} else {
   252			_, _ = a.pg.Exec(r.Context(), `UPDATE handoffs SET receiver_confirmed=true, receiver_id=$1 WHERE handoff_id::text=$2`, u.UserID, req.HandoffID)
   253		}
   254		// Check both confirmed.
   255		var s, rc bool
   256		_ = a.pg.QueryRow(r.Context(), `SELECT sender_confirmed, receiver_confirmed FROM handoffs WHERE handoff_id::text=$1`, req.HandoffID).Scan(&s, &rc)
   257		if s && rc {
   258			_, _ = a.pg.Exec(r.Context(), `UPDATE handoffs SET status='completed', completed_at=now() WHERE handoff_id::text=$1`, req.HandoffID)
   259			// Transfer custody to receiver.
   260			var newHolder string
   261			_ = a.pg.QueryRow(r.Context(), `SELECT COALESCE(worker_id::text,'') FROM assignments WHERE assignment_id::text=$1`, toAssignID).Scan(&newHolder)
   262			if newHolder == "" {
   263				newHolder = u.UserID
   264			}
   265			_, _ = a.pg.Exec(r.Context(), `UPDATE samples SET current_holder_id=$1 WHERE sample_id::text=$2`, newHolder, sampleID)
   266			// Mark previous assignment completed; mark next assignment in_progress.
   267			_, _ = a.pg.Exec(r.Context(), `UPDATE assignments SET status='completed' WHERE (SELECT from_assignment_id FROM handoffs WHERE handoff_id::text=$1)::text=assignment_id::text`, req.HandoffID)
   268			if toAssignID != "" {
   269				_, _ = a.pg.Exec(r.Context(), `UPDATE assignments SET status='in_progress' WHERE assignment_id::text=$1`, toAssignID)
   270			}
   271			// If next assignment is laboratory kind, sample becomes received.
   272			var kind string
   273			_ = a.pg.QueryRow(r.Context(), `SELECT kind FROM assignments WHERE assignment_id::text=$1`, toAssignID).Scan(&kind)
   274			if kind == "laboratory" {
   275				_, _ = a.pg.Exec(r.Context(), `UPDATE samples SET status='at_lab' WHERE sample_id::text=$1`, sampleID)
   276			} else {
   277				_, _ = a.pg.Exec(r.Context(), `UPDATE samples SET status='in_transit' WHERE sample_id::text=$1`, sampleID)
   278			}
   279			a.emitRealtime(r.Context(), "handoff.completed", "sample", sampleID, map[string]any{"holder": newHolder})
   280		}
   281		a.audit(r.Context(), u, "confirm_handoff", "handoff", req.HandoffID, true, nil)
   282		writeData(w, 201, map[string]any{
   283			"handoffId":       req.HandoffID,
   284			"status":          handoffStatus(s, rc),
   285			"senderConfirmed": s,
   286			"receiverConfirmed": rc,
   287		})
   288	}
   289	
   290	func handoffStatus(s, rc bool) string {
   291		if s && rc {
   292			return "completed"
   293		}
   294		return "pending"
   295	}
