package main

import (
	"context"
	"encoding/json"
	"errors"
	"io"
	"net/http"
	"strings"
	"time"

	"github.com/jackc/pgx/v5"
)

// ctxKey types
type ctxKey int

const (
	ckUser ctxKey = iota
)

// AuthUser holds the authenticated user context.
type AuthUser struct {
	UserID           string
	Username         string
	FullName         string
	Roles            []string
	ActiveRole       string
	Qualifications   []string
	AssignedLocation *string
}

func (u *AuthUser) hasRole(r string) bool {
	for _, x := range u.Roles {
		if x == r {
			return true
		}
	}
	return false
}

// apiError carries an HTTP status and a contract code.
type apiError struct {
	status int
	code   string
	msg    string
}

func (e *apiError) Error() string { return e.msg }

func errCode(status int, code, msg string) *apiError {
	if msg == "" {
		msg = code
	}
	return &apiError{status: status, code: code, msg: msg}
}

var (
	errUnauthorized = errCode(401, "unauthorized", "authentication required")
	errForbidden    = errCode(403, "forbidden", "forbidden")
	errNotFound     = errCode(404, "not_found", "not found")
	errRoleNotSel   = errCode(409, "role_not_selected", "active role not selected")
	errInvalidJSON  = errCode(400, "invalid_json", "invalid json body")
	errInternal     = errCode(500, "internal_error", "internal error")
	errSnapshot     = errCode(409, "state_snapshot_changed", "state snapshot changed")
	errConflict     = errCode(409, "concurrent_conflict", "concurrent conflict")
)

func writeData(w http.ResponseWriter, status int, data any) {
	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(status)
	_ = json.NewEncoder(w).Encode(map[string]any{"data": data})
}

func writeError(w http.ResponseWriter, e *apiError) {
	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(e.status)
	_ = json.NewEncoder(w).Encode(map[string]any{"error": e.msg, "code": e.code})
}

// decodeJSON decodes a strict JSON body (no extra fields enforced loosely here).
func decodeJSON(r *http.Request, dst any) error {
	if r.Body == nil {
		return errors.New("empty body")
	}
	body, err := io.ReadAll(r.Body)
	if err != nil {
		return err
	}
	if len(strings.TrimSpace(string(body))) == 0 {
		return errors.New("empty body")
	}
	dec := json.NewDecoder(strings.NewReader(string(body)))
	dec.DisallowUnknownFields()
	if err := dec.Decode(dst); err != nil {
		return err
	}
	return nil
}

// authMiddleware extracts the bearer [REDACTED] and loads the user.
func (a *App) authMiddleware(next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		token := bearerToken(r)
		if token == "" {
			writeError(w, errUnauthorized)
			return
		}
		u, err := a.loadUserByToken(r.Context(), token)
		if err != nil {
			writeError(w, errUnauthorized)
			return
		}
		ctx := context.WithValue(r.Context(), ckUser, u)
		next.ServeHTTP(w, r.WithContext(ctx))
	})
}

func currentUser(r *http.Request) *AuthUser {
	if u, ok := r.Context().Value(ckUser).(*AuthUser); ok {
		return u
	}
	return nil
}

func bearerToken(r *http.Request) string {
	h := r.Header.Get("Authorization")
	if strings.HasPrefix(h, "Bearer ") {
		return strings.TrimPrefix(h, "Bearer ")
	}
	if c, err := r.Cookie("session"); err == nil && c.Value != "" {
		return c.Value
	}
	return ""
}

// requireRole returns an apiError if the active role is not in allowed.
// allowedRoles is the set of roles permitted for the operation.
func requireRole(u *AuthUser, allowed ...string) *apiError {
	if u.ActiveRole == "" {
		return errRoleNotSel
	}
	ok := false
	for _, r := range allowed {
		if u.ActiveRole == r {
			ok = true
			break
		}
	}
	if !ok {
		return errForbidden
	}
	// active role must be one of the user's roles
	if !u.hasRole(u.ActiveRole) {
		return errForbidden
	}
	return nil
}

// loadUserByToken loads user + active role from session.
func (a *App) loadUserByToken(ctx context.Context, token string) (*AuthUser, error) {
	var (
		userID, username, fullName string
		roles, quals                []string
		activeRole                 string
		assignedLoc                 *string
	)
	err := a.pg.QueryRow(ctx, `
		SELECT u.user_id, u.username, u.full_name, u.roles, u.qualifications, s.active_role, u.assigned_location_id::text
		FROM sessions s JOIN users u ON u.user_id = s.user_id
		WHERE s.token = $1 AND u.active = true`, token).
		Scan(&userID, &username, &fullName, &roles, &quals, &activeRole, &assignedLoc)
	if err != nil {
		if errors.Is(err, pgx.ErrNoRows) {
			return nil, errors.New("no session")
		}
		return nil, err
	}
	return &AuthUser{
		UserID:           userID,
		Username:         username,
		FullName:         fullName,
		Roles:            roles,
		ActiveRole:       activeRole,
		Qualifications:   quals,
		AssignedLocation: assignedLoc,
	}, nil
}

// parseTime parses an RFC3339 timestamp, returning an apiError on failure.
func parseTime(s string, code string) (time.Time, *apiError) {
	if s == "" {
		return time.Time{}, errCode(400, code, "missing time")
	}
	t, err := time.Parse(time.RFC3339Nano, s)
	if err != nil {
		t, err = time.Parse(time.RFC3339, s)
		if err != nil {
			return time.Time{}, errCode(400, code, "invalid time")
		}
	}
