// handleCreateConnection implements POST /api/create-connection (admin only).
func (a *App) handleCreateConnection(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		writeError(w, errCode(405, "method_not_allowed", "POST required"))
