	}
	cid := uuidStr()
	_, err := a.pg.Exec(r.Context(), `INSERT INTO connections (connection_id, from_location_id, to_location_id, travel_minutes, cost_units, cooled, active)
		VALUES ($1,$2,$3,$4,$5,$6,$7)`, cid, req.FromLocationID, req.ToLocationID, req.TravelMinutes, req.CostUnits, req.Cooled, req.Active)
	if err != nil {
		writeError(w, errConflict)
		return
	}
	ensureCapacityRow(r.Context(), a.pg, cid, "connection")
	a.audit(r.Context(), u, "create_connection", "connection", cid, true, nil)
	go a.recomputeServiceability()
	writeData(w, 201, map[string]any{
		"connectionId":  cid,
