func (a *App) handleConfigureCapacity(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		writeError(w, errCode(405, "method_not_allowed", "POST required"))
		return
	}
	u := currentUser(r)
	if e := requireRole(u, "administrator", "dispatcher", "node_handler", "laboratory_team"); e != nil {
		writeError(w, e)
		return
	}
	var req struct {
		ResourceID       string  `json:"resourceId"`
		ResourceKind    string  `json:"resourceKind"`
		RegularCapacity  *int    `json:"regularCapacity"`
		CooledCapacity   *int    `json:"cooledCapacity"`
	}
	if err := decodeJSON(r, &req); err != nil {
		writeError(w, errInvalidJSON)
		return
	}
	if req.ResourceID == "" || req.ResourceKind == "" {
		writeError(w, errCode(400, "invalid_capacity", "missing fields"))
		return
	}
	// Node/lab handlers may only configure their own assigned node/lab.
	if u.ActiveRole == "node_handler" || u.ActiveRole == "laboratory_team" {
		var assigned *string
		_ = a.pg.QueryRow(r.Context(), `SELECT assigned_location_id::text FROM users WHERE user_id::text=$1`, u.UserID).Scan(&assigned)
		if assigned == nil || *assigned != req.ResourceID {
			writeError(w, errForbidden)
			return
		}
	}
	ensureCapacityRow(r.Context(), a.pg, req.ResourceID, req.ResourceKind)
	if req.RegularCapacity != nil {
		_, _ = a.pg.Exec(r.Context(), `UPDATE capacity SET regular_capacity=$1 WHERE resource_id::text=$2`, *req.RegularCapacity, req.ResourceID)
	}
	if req.CooledCapacity != nil {
		_, _ = a.pg.Exec(r.Context(), `UPDATE capacity SET cooled_capacity=$1 WHERE resource_id::text=$2`, *req.CooledCapacity, req.ResourceID)
	}
	a.audit(r.Context(), u, "configure_capacity", "capacity", req.ResourceID, true, map[string]any{"regular": req.RegularCapacity, "cooled": req.CooledCapacity})
	writeData(w, 201, a.capacityOut(r.Context(), req.ResourceID))
}

