func (a *App) locationOut(ctx context.Context, id string) map[string]any {
	var (
		name        string
		lat, lng, cov float64
		hand        int
		active, cp, tp, hub, lab bool
	)
	err := a.pg.QueryRow(ctx, `SELECT name, latitude, longitude, coverage_km, handling_minutes, active, fn_collection_point, fn_transfer_point, fn_hub, fn_laboratory FROM locations WHERE location_id::text=$1`, id).
		Scan(&name, &lat, &lng, &cov, &hand, &active, &cp, &tp, &hub, &lab)
	if err != nil {
		return map[string]any{"locationId": id}
	}
	return map[string]any{
		"locationId":      id,
		"name":            name,
		"coordinate":      map[string]any{"latitude": lat, "longitude": lng},
		"functions": map[string]any{
			"collection_point": cp,
			"transfer_point":   tp,
			"hub":              hub,
			"laboratory":       lab,
		},
		"coverageKm":      cov,
		"handlingMinutes": hand,
		"active":          active,
	}
}

func (a *App) sampleTypeOut(ctx context.Context, id string) map[string]any {
	st, err := loadSampleType(ctx, a.pg, id)
	if err != nil {
		return map[string]any{"sampleTypeId": id}
	}
	return map[string]any{
		"sampleTypeId":                 st.ID,
		"name":                         st.Name,
		"qualifiedCollectorRequired":   st.QualifiedRequired,
		"requiredQualification":        st.RequiredQualification,
		"containerType":                st.ContainerType,
		"temperatureMinC":               st.TempMin,
		"temperatureMaxC":               st.TempMax,
		"requiresCooledRoute":          st.RequiresCooled,
		"batchingAllowed":              st.BatchingAllowed,
		"incompatibleSampleTypes":      orEmpty(st.Incompatible),
	}
}

func (a *App) capacityOut(ctx context.Context, id string) map[string]any {
	var reg, regRes, cool, coolRes int
	_ = a.pg.QueryRow(ctx, `SELECT regular_capacity, regular_reserved, cooled_capacity, cooled_reserved FROM capacity WHERE resource_id::text=$1`, id).
		Scan(&reg, &regRes, &cool, &coolRes)
	return map[string]any{
		"capacityUnits":        reg,
		"reservedUnits":        regRes,
		"availableUnits":       reg - regRes,
		"cooledCapacityUnits":  cool,
		"cooledReservedUnits":  coolRes,
		"cooledAvailableUnits": cool - coolRes,
	}
}

// recomputeServiceability computes a new complete version synchronously (guarded).
func (a *App) recomputeServiceability() {
	ctx := context.Background()
	a.rtMu.Lock()
	defer a.rtMu.Unlock()
	_, _ = a.computeServiceabilityVersion(ctx)
}

// requesterSamples returns sample summaries owned by the requester.
func (a *App) requesterSamples(ctx context.Context, userID string) []map[string]any {
	rows, err := a.pg.Query(ctx, `SELECT s.sample_id::text, s.status, s.sealed, s.origin_type, st.name
		FROM samples s JOIN sample_types st ON st.sample_type_id=s.sample_type_id
		WHERE s.requester_id::text=$1 ORDER BY s.created_at DESC LIMIT 100`, userID)
	if err != nil {
		return []map[string]any{}
	}
	defer rows.Close()
	out := []map[string]any{}
	for rows.Next() {
		var id, status, origin, stName string
		var sealed bool
		_ = rows.Scan(&id, &status, &sealed, &origin, &stName)
		out = append(out, map[string]any{
			"sampleId":   id,
			"status":     status,
			"sealed":     sealed,
			"originType": origin,
			"sampleType": stName,
		})
	}
	return out
}

