// handleUpdateLocation implements POST /api/update-location (admin only).
func (a *App) handleUpdateLocation(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		writeError(w, errCode(405, "method_not_allowed", "POST required"))
		return
	}
	u := currentUser(r)
	if e := requireRole(u, "administrator"); e != nil {
		writeError(w, e)
		return
	}
	var req struct {
		LocationID string    `json:"locationId"`
		Name       string    `json:"name"`
		Coordinate *coordIn  `json:"coordinate"`
		Functions  []string  `json:"functions"`
		CoverageKm float64   `json:"coverageKm"`
		HandlingMin int      `json:"handlingMinutes"`
		Active     bool     `json:"active"`
	}
	if err := decodeJSON(r, &req); err != nil {
		writeError(w, errInvalidJSON)
		return
	}
	for _, f := range req.Functions {
		if !validLocationFunction(f) {
			writeError(w, errCode(400, "invalid_location", "invalid function"))
			return
		}
	}
	fm := funcsFromList(req.Functions)
	args := []any{req.Name, req.CoverageKm, req.HandlingMin, req.Active, fm["collection_point"], fm["transfer_point"], fm["hub"], fm["laboratory"], req.LocationID, locTypeFromFuncs(fm)}
	sql := `UPDATE locations SET name=$1, coverage_km=$2, handling_minutes=$3, active=$4,
		fn_collection_point=$5, fn_transfer_point=$6, fn_hub=$7, fn_laboratory=$8, location_type=$10`
	if req.Coordinate != nil {
		sql += `, latitude=$11, longitude=$12`
		args = append(args, req.Coordinate.Latitude, req.Coordinate.Longitude)
	}
	sql += ` WHERE location_id::text=$9`
	_, err := a.pg.Exec(r.Context(), sql, args...)
	if err != nil {
		writeError(w, errNotFound)
		return
	}
	a.audit(r.Context(), u, "update_location", "location", req.LocationID, true, nil)
	go a.recomputeServiceability()
	writeData(w, 201, a.locationOut(r.Context(), req.LocationID))
}

// locTypeFromFuncs derives a location_type label from the active functions.
func locTypeFromFuncs(fm map[string]bool) string {
	if fm["laboratory"] {
		return "laboratory"
	}
	if fm["hub"] {
		return "hub"
	}
	if fm["transfer_point"] {
		return "transfer_point"
	}
	return "collection_point"
}

