	var samples, active, exceptions, labs, nodes, workers int
	_ = a.pg.QueryRow(ctx, `SELECT COUNT(*) FROM samples`).Scan(&samples)
	_ = a.pg.QueryRow(ctx, `SELECT COUNT(*) FROM samples WHERE status IN ('pending','in_transit','collected','at_node')`).Scan(&active)
	_ = a.pg.QueryRow(ctx, `SELECT COUNT(*) FROM samples WHERE exception IS NOT NULL`).Scan(&exceptions)
	_ = a.pg.QueryRow(ctx, `SELECT COUNT(*) FROM locations WHERE fn_laboratory`).Scan(&labs)
	_ = a.pg.QueryRow(ctx, `SELECT COUNT(*) FROM locations WHERE active`).Scan(&nodes)
	_ = a.pg.QueryRow(ctx, `SELECT COUNT(*) FROM users WHERE array_length(roles,1) > 0 AND active=true`).Scan(&workers)
	return map[string]any{
		"samples":       samples,
		"activeSamples": active,
		"exceptions":    exceptions,
		"laboratories":  labs,
		"nodes":         nodes,
		"workers":        workers,
	}
}

