// handleConfigureCapacity implements POST /api/configure-capacity.
func (a *App) handleConfigureCapacity(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		writeError(w, errCode(405, "method_not_allowed", "POST required"))
		return
	}
	u := currentUser(r)
	if e := requireRole(u, "administrator", "dispatcher", "node_handler", "laboratory_team"); e != nil {
		writeError(w, e)
		return
	}
	var req struct {
		ResourceID          string `json:"resourceId"`
		CapacityUnits       *int   `json:"capacityUnits"`
		CooledCapacityUnits *int   `json:"cooledCapacityUnits"`
	}
	if err := decodeJSON(r, &req); err != nil {
		writeError(w, errInvalidJSON)
		return
	}
	if req.ResourceID == "" {
		writeError(w, errCode(400, "invalid_capacity", "missing resourceId"))
		return
	}
	// Node/lab handlers may only configure their own assigned node/lab.
	if u.ActiveRole == "node_handler" || u.ActiveRole == "laboratory_team" {
		var assigned *string
		_ = a.pg.QueryRow(r.Context(), `SELECT assigned_location_id::text FROM users WHERE user_id::text=$1`, u.UserID).Scan(&assigned)
		if assigned == nil || *assigned != req.ResourceID {
			writeError(w, errForbidden)
			return
		}
	}
	ensureCapacityRow(r.Context(), a.pg, req.ResourceID, "resource")
	if req.CapacityUnits != nil {
		_, _ = a.pg.Exec(r.Context(), `UPDATE capacity SET regular_capacity=$1 WHERE resource_id::text=$2`, *req.CapacityUnits, req.ResourceID)
	}
	if req.CooledCapacityUnits != nil {
		_, _ = a.pg.Exec(r.Context(), `UPDATE capacity SET cooled_capacity=$1 WHERE resource_id::text=$2`, *req.CooledCapacityUnits, req.ResourceID)
	}
	a.audit(r.Context(), u, "configure_capacity", "capacity", req.ResourceID, true, map[string]any{"regular": req.CapacityUnits, "cooled": req.CooledCapacityUnits})
	writeData(w, 200, a.configureCapacityOut(r.Context(), req.ResourceID))
}

