	id := uuidStr()
	_, err := a.pg.Exec(r.Context(), `INSERT INTO sample_types
		(sample_type_id, name, qualified_collector_required, required_qualification, container_type, temperature_min_c, temperature_max_c, requires_cooled_route, batching_allowed, incompatible, is_default)
