    91			rows, _ := a.pg.Query(ctx, `SELECT a.assignment_id::text, a.kind, a.status, a.sample_id::text, a.from_location_id::text, a.to_location_id::text, a.node_id::text, a.laboratory_id::text, j.status, s.status
    92				FROM assignments a JOIN journeys j ON j.journey_id=a.journey_id
    93				LEFT JOIN samples s ON s.sample_id=a.sample_id
