   105		if rows == nil {
   106			return []map[string]any{}, []map[string]any{}
   107		}
   108		defer rows.Close()
   109		current := []map[string]any{}
   110		past := []map[string]any{}
   111		for rows.Next() {
   112			var aid, kind, status, jStatus, sStatus string
   113			var sampleID, from, to, node, lab *string
   114			_ = rows.Scan(&aid, &kind, &status, &sampleID, &from, &to, &node, &lab, &jStatus, &sStatus)
   115			item := map[string]any{
   116				"assignmentId": aid,
   117				"kind":         kind,
   118				"status":       status,
   119				"sampleId":     strPtr(sampleID),
