   194		if r.Method != http.MethodPost {
   195			writeError(w, errCode(405, "method_not_allowed", "POST required"))
   196			return
   197		}
   198		u := currentUser(r)
   199		if e := requireRole(u, workerRoles()...); e != nil {
   200			writeError(w, e)
   201			return
   202		}
   203		var req struct {
   204			AssignmentID string `json:"assignmentId"`
   205		}
   206		if err := decodeJSON(r, &req); err != nil {
   207			writeError(w, errInvalidJSON)
   208			return
   209		}
   210		ar, e := loadAssignment(r.Context(), a.pg, req.AssignmentID)
