   216			writeError(w, errCode(403, "not_assigned", "assignment not offered to you"))
   217			return
   218		}
   219		if ar.Status != "offered" {
   220			writeError(w, errCode(409, "invalid_state", "assignment not offered"))
   221			return
   222		}
   223		_, err := a.pg.Exec(r.Context(), `UPDATE assignments SET status='accepted' WHERE assignment_id::text=$1 AND status='offered'`, req.AssignmentID)
