   229			_, _ = a.pg.Exec(r.Context(), `UPDATE samples SET current_holder_id=$1 WHERE sample_id::text=$2`, u.UserID, *ar.SampleID)
   230		}
   231		a.audit(r.Context(), u, "accept_assignment", "assignment", req.AssignmentID, true, nil)
