   339		}
   340		var labID *string
   341		if req.AssignmentID != "" {
   342			ar, e := loadAssignment(r.Context(), a.pg, req.AssignmentID)
   343			if e != nil {
   344				writeError(w, e)
   345				return
   346			}
   347			if ar.WorkerID == nil || *ar.WorkerID != u.UserID {
   348				writeError(w, errForbidden)
