def resolve(ref): return c['components']['schemas'][ref.split('/')[-1]]
ops=['accept_assignment','decline_assignment','collect_and_seal_sample','initiate_handoff','confirm_handoff','update_assignment_progress','record_worker_location','record_handling_checkpoint','confirm_laboratory_receipt','record_laboratory_exception','set_worker_availability','read_sample_lifecycle','list_role_work']
for path,methods in c['paths'].items():
    for m,op in methods.items():
        if op.get('operationId') in ops:
            sc=op.get('responses',{}).get('200') or op.get('responses',{}).get('201')
            sc=sc.get('content',{}).get('application/json',{}).get('schema',{})
            if '\$ref' in sc: sc=resolve(sc['\$ref'])
            data=sc.get('properties',{}).get('data',{})
            if '\$ref' in data: data=resolve(data['\$ref'])
            print('===',op['operationId'])
            print(json.dumps(data,indent=0))
