// withIdempotency wraps a handler that needs idempotency_key, returning stored response on repeat.
func (a *App) withIdempotency(r *http.Request, op, key string, fn func() (any, int, *apiError)) (any, int, *apiError) {
	if key == "" {
		return nil, 400, errCode(400, "idempotency_required", "idempotencyKey required")
	}
	// check existing
	var respBytes []byte
	var sc int
	err := a.pg.QueryRow(r.Context(), `SELECT response, status_code FROM idempotency_keys WHERE key=$1 AND operation=$2`, key, op).Scan(&respBytes, &sc)
	if err == nil {
		// replay
		var data any
		_ = json.Unmarshal(respBytes, &data)
		return data, sc, nil
	}
	data, status, e := fn()
	if e != nil {
		return nil, e.status, e
	}
	b, _ := json.Marshal(data)
	_, _ = a.pg.Exec(r.Context(), `INSERT INTO idempotency_keys (key, operation, response, status_code) VALUES ($1,$2,$3,$4) ON CONFLICT DO NOTHING`, key, op, b, status)
	return data, status, nil
}

