			{Keys: bson.D{{Key: "occurredAt", Value: 1}}},
			{Keys: bson.D{{Key: "entityType", Value: 1}, {Key: "entityId", Value: 1}}},
			{Keys: bson.D{{Key: "actorId", Value: 1}, {Key: "occurredAt", Value: -1}}},
			{Keys: bson.D{{Key: "action", Value: 1}}},
		},
		"realtime_events": {
			{Keys: bson.D{{Key: "seq", Value: 1}}, Unique: true},
			{Keys: bson.D{{Key: "createdAt", Value: 1}}},
			{Keys: bson.D{{Key: "entityType", Value: 1}, {Key: "createdAt", Value: -1}}},
		},
		"audit_requests": {
			{Keys: bson.D{{Key: "requestId", Value: 1}}},
		},
	}
	for coll, idxs := range indexes {
		c := db.Collection(coll)
		var models []mongo.IndexModel
		for _, ix := range idxs {
			im := mongo.IndexModel{Keys: ix.Keys}
			iopts := options.Index()
			if ix.Unique {
				iopts.SetUnique(true)
			}
			im.Options = iopts
			models = append(models, im)
		}
		_, err := c.Indexes().CreateMany(ctx, models)
		if err != nil && !isMongoAlreadyExists(err) {
			return err
		}
	}
	return nil
}

type mongoIndex struct {
	Keys   any
	Unique bool
}

func isMongoAlreadyExists(err error) bool {
	s := err.Error()
	return contains(s, "already exists") || contains(s, "NamespaceExists")
}

func (a *App) ResetMongo(ctx context.Context) error {
	colls := []string{"audit_events", "realtime_events", "audit_requests"}
	for _, c := range colls {
		_ = a.mdb.Collection(c).Drop(ctx)
	}
	return a.MaterializeMongo(ctx)
