		"id":          seq,
		"seq":         seq,
		"type":        etype,
		"entityType":  entityType,
		"entityId":    entityID,
		"payload":     payload,
		"createdAt":   time.Now().UTC(),
		"timestamp":   time.Now().UTC(),
	})
}

