package main

import (
	"context"
	"log"
	"net/http"
	"os"
	"os/signal"
	"syscall"
	"time"
)

const listenAddr = ":8080"

func main() {
	log.SetFlags(log.LstdFlags | log.Lshortfname)

	// `labpd reset` materializes a clean datastore structure and exits.
	if len(os.Args) > 1 && os.Args[1] == "reset" {
		cfg := loadConfig()
		ctx := context.Background()
		app, err := NewApp(ctx, cfg)
		if err != nil {
			log.Fatalf("connect failed: %v", err)
		}
		defer app.Close()
		if err := app.ResetSchema(ctx); err != nil {
			log.Fatalf("pg reset failed: %v", err)
		}
		if err := app.MaterializeMongo(ctx); err != nil {
			log.Fatalf("mongo materialize failed: %v", err)
		}
		if err := app.SeedDefaults(ctx); err != nil {
			log.Fatalf("seed failed: %v", err)
		}
		log.Printf("reset complete")
		return
	}

	cfg := loadConfig()

	ctx, cancel := context.WithCancel(context.Background())
	defer cancel()

	app, err := NewApp(ctx, cfg)
	if err != nil {
		log.Fatalf("startup failed: %v", err)
	}
	defer app.Close()
	ready.Store(true)

	if err := app.EnsureInitialAdmin(ctx); err != nil {
		log.Fatalf("initial admin failed: %v", err)
	}

	srv := &http.Server{
		Addr:              listenAddr,
		Handler:           app.Router(),
		ReadHeaderTimeout: 15 * time.Second,
		IdleTimeout:       120 * time.Second,
	}

	stop := make(chan os.Signal, 2)
	signal.Notify(stop, os.Interrupt, syscall.SIGTERM)

	go func() {
		log.Printf("labpd listening on %s", listenAddr)
		if err := srv.ListenAndServe(); err != nil && err != http.ErrServerClosed {
			log.Fatalf("server error: %v", err)
		}
	}()

	<-stop
	log.Printf("shutting down...")
	shutCtx, c2 := context.WithTimeout(context.Background(), 10*time.Second)
	defer c2()
	_ = srv.Shutdown(shutCtx)
}

