			VALUES ($1,$2,$3,$4,'in_transit',true,now(),$5,$6,$7,$8,$9,NULL)`,
			sid, rid, u.UserID, req.SampleTypeId, u.UserID, req.OriginType, st.ContainerType, st.TempMin, st.TempMax)
		if err != nil {
