export type Role =
  | "administrator"
  | "dispatcher"
  | "requester"
  | "collection_professional"
  | "delivery_partner"
  | "node_handler"
  | "laboratory_team";

export type LocationFunction =
  | "collection_point"
  | "transfer_point"
  | "hub"
  | "laboratory";

export interface Coordinate {
  latitude: number;
  longitude: number;
}

export interface Capacity {
  capacityUnits: number;
  reservedUnits: number;
  availableUnits: number;
  cooledCapacityUnits: number;
  cooledReservedUnits: number;
  cooledAvailableUnits: number;
}

export interface Certification {
  code: string;
  active: boolean;
  expiresAt?: string;
}

export interface TimelineEntry {
  eventId: number;
  action: string;
  actorId: string;
  role: string;
  entityType: string;
  entityId: string;
  success: boolean;
  occurredAt: string;
  details: Record<string, unknown>;
}

export interface AuditEntry {
  auditId: string;
  actorId: string;
  role: string;
  actorRole: string;
  action: string;
  entityType: string;
  entityId: string;
  success: boolean;
  occurredAt: string;
  details: Record<string, unknown>;
}

export interface AuditSearchResult {
  entries: AuditEntry[];
  total: number;
  returned: number;
  offset: number;
  limit: number;
  order: string;
  hasMore: boolean;
  nextOffset?: number;
}

export interface RoleWorkItem {
  kind?: string;
  [k: string]: unknown;
}

export interface RoleWork {
  pending: RoleWorkItem[];
  inProgress: RoleWorkItem[];
  completed: RoleWorkItem[];
}

export interface BootstrapUser {
  userId: string;
  username: string;
  fullName: string;
  roles: Role[];
  activeRole: Role;
  roleSelectionRequired: boolean;
}

export interface Bootstrap {
  user: BootstrapUser;
  serverTime: string;
  operations: {
    samples: number;
    activeSamples: number;
    exceptions: number;
    workers: number;
    nodes: number;
    laboratories: number;
  };
  requesterSamples?: unknown[] | null;
}

export interface ServiceabilityResult {
  serviceable: boolean;
  reason: string;
  targetLaboratoryId?: string;
  estimatedArrivalAt?: string;
  serviceabilityVersion?: number;
}

export interface SampleState {
  sampleId: string;
  requestId: string;
  requesterId: string;
  origin: Coordinate;
  originType: string;
  requestedAt: string;
  deliveryDeadline: string;
  sampleTypeId: string;
  containerType: string;
  temperatureMinC: number;
  temperatureMaxC: number;
  incompatibleSampleTypes: string[];
  serviceability: string;
  activeAssignmentIds: string[];
  state: { status: string };
  timeline: TimelineEntry[];
  activeJourneyId?: string;
  targetLaboratoryId?: string;
  latestLocation?: Coordinate;
  locationRecordedAt?: string;
  locationStale: boolean;
}

export interface SampleLifecycle {
  sampleId: string;
  status: string;
  sealed: boolean;
  completedLegIds: string[];
  activeReplacementPlanIds: string[];
  timeline: TimelineEntry[];
  activeJourneyId?: string;
  currentHolderId?: string;
  receivedLaboratoryId?: string;
  exception?: Record<string, unknown>;
  pendingHandoffId?: string;
  pendingHandoff?: Record<string, unknown>;
  latestLocation?: Coordinate;
  locationRecordedAt?: string;
  locationStale: boolean;
}

export interface JourneyStop {
  stopId: string;
  locationId: string;
  stopType: string;
  sequence: number;
  estimatedAt: string;
  dwellMinutes?: number;
  coordinate?: Coordinate;
  completedAt?: string;
}

export interface JourneyLeg {
  assignmentId: string;
  sequence: number;
  status: string;
  fromLocationId?: string;
  toLocationId?: string;
  workerId?: string;
  sampleId?: string;
}

export interface JourneyPlan {
  journeyId: string;
  parentJourneyId?: string;
  planVersion: number;
  routeMode: string;
  status: string;
  estimatedDeliveryAt?: string;
  totalCostUnits?: number;
  capacityUsed?: number;
  capacityAvailable?: number;
  sampleIds: string[];
  orderedStops: JourneyStop[];
  legs: JourneyLeg[];
  assignedWorkerIds?: string[];
  collectionAssignmentId?: string;
  collectionAssignmentIds?: string[];
  nodeAssignmentIds?: string[];
  laboratoryAssignmentIds?: string[];
  firstTransportAssignmentId?: string;
  middleTransportAssignmentId?: string;
  finalTransportAssignmentId?: string;
  valid?: boolean;
  replanStatus?: string;
  splitJourney?: JourneyPlan;
  replacementJourney?: JourneyPlan;
}

export interface OperationsState {
  samples: Array<Record<string, unknown>>;
  workers: Array<Record<string, unknown>>;
  locations: Array<Record<string, unknown>>;
  connections: Array<Record<string, unknown>>;
  exceptions: Array<Record<string, unknown>>;
  activeSamples?: number;
  samples_count?: number;
  exceptions_count?: number;
  workers_count?: number;
  nodes?: number;
  laboratories?: number;
}

export interface ServiceabilityRegion {
  locationId: string;
  name: string;
  latitude: number;
  longitude: number;
  coverageKm: number;
}

export interface ServiceabilitySnapshot {
  version: number;
  status: string;
  computedAt: string;
  networkRevision: number;
  regions: ServiceabilityRegion[];
  activeCollectionPointCount: number;
}

export interface UserInfo {
  userId: string;
  username: string;
  email?: string;
  fullName?: string;
  phone?: string;
  roles: Role[];
  qualifications: string[];
  certifications: Certification[];
  active: boolean;
  assignedLocationId?: string;
}

export interface RealtimeEvent {
  id: number;
  type: string;
  entityType: string;
  entityId: string;
  payload: Record<string, unknown>;
  createdAt: string;
}

export interface ApiError {
  code: string;
  error: string;
}

