import type {
  ApiError,
  Bootstrap,
  ServiceabilityResult,
  ServiceabilitySnapshot,
  SampleState,
  SampleLifecycle,
  RoleWork,
  OperationsState,
  JourneyPlan,
  AuditSearchResult,
  UserInfo,
  Role,
} from "./types";

const BASE = "";

let token: string | null = null;

export function getToken(): string | null {
  return token;
}

export function setToken(t: string | null) {
  token = t;
  if (t) localStorage.setItem("labpd_token", t);
  else localStorage.removeItem("labpd_token");
}

export function loadStoredToken() {
  const t = localStorage.getItem("labpd_token");
  if (t) token = t;
}

async function req<T>(
  method: string,
  path: string,
  body?: unknown
): Promise<T> {
  const headers: Record<string, string> = {};
  let url = BASE + path;
  const init: RequestInit = { method, headers };
  if (token) headers["Authorization"] = "Bearer " + token;
  if (body !== undefined) {
    headers["Content-Type"] = "application/json";
    init.body = JSON.stringify(body);
  }
  const res = await fetch(url, init);
  const text = await res.text();
  let data: unknown = null;
  if (text) {
    try {
      data = JSON.parse(text);
    } catch {
      data = text;
    }
  }
  if (!res.ok) {
    const err = (data && typeof data === "object" ? data : { error: String(data) }) as ApiError;
    const e = new Error(err.error || `HTTP ${res.status}`) as Error & {
      code?: string;
      status?: number;
    };
    e.code = err.code;
    e.status = res.status;
    throw e;
  }
  // unwrap { data: ... }
  if (data && typeof data === "object" && "data" in (data as Record<string, unknown>)) {
    return (data as { data: T }).data;
  }
  return data as T;
}

export const api = {
  authenticate: (username: string, password: string) =>
    req<{ sessionToken: string; userId: string; roles: string[]; activeRole: string }>(
      "POST",
      "/api/authenticate-user",
      { username, password }
    ),
  bootstrap: () => req<Bootstrap>("GET", "/api/ui/bootstrap"),
  selectRole: (role: Role) => req<{ activeRole: Role }>("POST", "/api/select-active-role", { role }),
  readUser: (userId: string) => req<UserInfo>("GET", `/api/read-user/${userId}`),
  createUser: (b: Record<string, unknown>) => req<Record<string, unknown>>("POST", "/api/create-user", b),
  updateUserAccess: (b: Record<string, unknown>) => req<Record<string, unknown>>("POST", "/api/update-user-access", b),
  createLocation: (b: Record<string, unknown>) => req<Record<string, unknown>>("POST", "/api/create-location", b),
  updateLocation: (b: Record<string, unknown>) => req<Record<string, unknown>>("POST", "/api/update-location", b),
  setLocationStatus: (b: Record<string, unknown>) => req<Record<string, unknown>>("POST", "/api/set-location-status", b),
  setLocationFunctionStatus: (b: Record<string, unknown>) =>
    req<Record<string, unknown>>("POST", "/api/set-location-function-status", b),
  createConnection: (b: Record<string, unknown>) => req<Record<string, unknown>>("POST", "/api/create-connection", b),
  setConnectionStatus: (b: Record<string, unknown>) => req<Record<string, unknown>>("POST", "/api/set-connection-status", b),
  createSampleType: (b: Record<string, unknown>) => req<Record<string, unknown>>("POST", "/api/create-sample-type", b),
  updateSampleType: (b: Record<string, unknown>) => req<Record<string, unknown>>("POST", "/api/update-sample-type", b),
  configureCapacity: (b: Record<string, unknown>) => req<Record<string, unknown>>("POST", "/api/configure-capacity", b),
  configureLabAcceptance: (b: Record<string, unknown>) =>
    req<Record<string, unknown>>("POST", "/api/configure-laboratory-acceptance", b),
  checkServiceability: (b: Record<string, unknown>) => req<ServiceabilityResult>("POST", "/api/check-serviceability", b),
  createCollectionRequest: (b: Record<string, unknown>) =>
    req<Record<string, unknown>>("POST", "/api/create-collection-request", b),
  readServiceabilitySnapshot: () =>
    req<ServiceabilitySnapshot>("POST", "/api/read-serviceability-snapshot", {}),
  listRoleWork: (role?: string) =>
    req<RoleWork>("POST", "/api/list-role-work", role ? { role } : {}),
  readSampleState: (sampleId: string) => req<SampleState>("GET", `/api/read-sample-state/${sampleId}`),
  readSampleLifecycle: (sampleId: string) =>
    req<SampleLifecycle>("POST", "/api/read-sample-lifecycle", { sampleId }),
  readJourneyPlan: (b: Record<string, unknown>) => req<JourneyPlan>("POST", "/api/read-journey-plan", b),
  readOperationsState: () => req<OperationsState>("POST", "/api/read-operations-state", {}),
  acceptAssignment: (b: Record<string, unknown>) => req<Record<string, unknown>>("POST", "/api/accept-assignment", b),
  declineAssignment: (b: Record<string, unknown>) => req<Record<string, unknown>>("POST", "/api/decline-assignment", b),
  collectAndSeal: (b: Record<string, unknown>) => req<Record<string, unknown>>("POST", "/api/collect-and-seal-sample", b),
  recordWorkerLocation: (b: Record<string, unknown>) => req<Record<string, unknown>>("POST", "/api/record-worker-location", b),
  recordCheckpoint: (b: Record<string, unknown>) => req<Record<string, unknown>>("POST", "/api/record-handling-checkpoint", b),
  initiateHandoff: (b: Record<string, unknown>) => req<Record<string, unknown>>("POST", "/api/initiate-handoff", b),
  confirmHandoff: (b: Record<string, unknown>) => req<Record<string, unknown>>("POST", "/api/confirm-handoff", b),
  updateAssignmentProgress: (b: Record<string, unknown>) =>
    req<Record<string, unknown>>("POST", "/api/update-assignment-progress", b),
  confirmLabReceipt: (b: Record<string, unknown>) => req<Record<string, unknown>>("POST", "/api/confirm-laboratory-receipt", b),
  recordLabException: (b: Record<string, unknown>) => req<Record<string, unknown>>("POST", "/api/record-laboratory-exception", b),
  ingestPresealed: (b: Record<string, unknown>) => req<Record<string, unknown>>("POST", "/api/ingest-presealed-sample", b),
  setWorkerAvailability: (b: Record<string, unknown>) => req<Record<string, unknown>>("POST", "/api/set-worker-availability", b),
  reportDisruption: (b: Record<string, unknown>) => req<Record<string, unknown>>("POST", "/api/report-disruption", b),
  cancelJourney: (b: Record<string, unknown>) => req<Record<string, unknown>>("POST", "/api/cancel-journey", b),
  splitJourney: (b: Record<string, unknown>) => req<Record<string, unknown>>("POST", "/api/split-journey", b),
  mergeJourneys: (b: Record<string, unknown>) => req<Record<string, unknown>>("POST", "/api/merge-journeys", b),
  rerouteJourney: (b: Record<string, unknown>) => req<Record<string, unknown>>("POST", "/api/reroute-journey", b),
  editActivePlan: (b: Record<string, unknown>) => req<Record<string, unknown>>("POST", "/api/edit-active-plan", b),
  searchAudit: (b: Record<string, unknown>) => req<AuditSearchResult>("POST", "/api/search-audit-trail", b),
};

export type Api = typeof api;

