:root {
  --bg: #0f1420;
  --panel: #1a2130;
  --panel2: #232c3f;
  --border: #2e3a52;
  --text: #e6e9f0;
  --muted: #93a0b8;
  --accent: #4f9eff;
  --accent2: #2bd4a0;
  --danger: #ff5a6a;
  --warn: #ffb84d;
  --ok: #2bd4a0;
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
}

* { box-sizing: border-box; }

html, body, #root { height: 100%; margin: 0; }

body {
  background: var(--bg);
  color: var(--text);
  font-size: 14px;
}

a { color: var(--accent); }

button {
  font-family: inherit;
  font-size: 13px;
  background: var(--panel2);
  color: var(--text);
  border: 1px solid var(--border);
  border-radius: 6px;
  padding: 6px 12px;
  cursor: pointer;
}
button:hover:not(:disabled) { border-color: var(--accent); }
button:disabled { opacity: 0.5; cursor: not-allowed; }
button.primary { background: var(--accent); border-color: var(--accent); color: #fff; font-weight: 600; }
button.danger { background: var(--danger); border-color: var(--danger); color: #fff; }
button.small { padding: 3px 8px; font-size: 12px; }

input, select, textarea {
  font-family: inherit;
  font-size: 13px;
  background: var(--bg);
  color: var(--text);
  border: 1px solid var(--border);
  border-radius: 6px;
  padding: 6px 8px;
  width: 100%;
}
input:focus, select:focus, textarea:focus { outline: none; border-color: var(--accent); }

.app-shell { display: flex; flex-direction: column; height: 100%; }
.topbar {
  display: flex; align-items: center; gap: 12px;
  padding: 8px 16px; background: var(--panel); border-bottom: 1px solid var(--border);
  flex-wrap: wrap;
}
.topbar .brand { font-weight: 700; font-size: 15px; }
.topbar .spacer { flex: 1; }
.role-select { width: auto; }

.layout { display: flex; flex: 1; overflow: hidden; }
.sidebar {
  width: 220px; background: var(--panel); border-right: 1px solid var(--border);
  padding: 8px 0; overflow-y: auto; flex-shrink: 0;
}
.sidebar a {
  display: block; padding: 8px 16px; color: var(--muted); text-decoration: none;
}
.sidebar a:hover { background: var(--panel2); color: var(--text); }
.sidebar a.active { background: var(--panel2); color: var(--accent); border-left: 3px solid var(--accent); }
.main { flex: 1; overflow-y: auto; padding: 20px; }

.panel {
  background: var(--panel); border: 1px solid var(--border); border-radius: 8px;
  padding: 16px; margin-bottom: 16px;
}
.panel h2, .panel h3 { margin: 0 0 12px; }
.grid { display: grid; gap: 12px; }
.grid-2 { grid-template-columns: 1fr 1fr; }
.grid-3 { grid-template-columns: 1fr 1fr 1fr; }
@media (max-width: 900px) { .grid-2, .grid-3 { grid-template-columns: 1fr; } }

.form-row { margin-bottom: 10px; }
.form-row label { display: block; font-size: 12px; color: var(--muted); margin-bottom: 3px; }

table { width: 100%; border-collapse: collapse; font-size: 13px; }
th, td { text-align: left; padding: 6px 8px; border-bottom: 1px solid var(--border); }
th { color: var(--muted); font-weight: 600; }

.badge {
  display: inline-block; padding: 2px 8px; border-radius: 10px; font-size: 11px; font-weight: 600;
}
.badge.ok { background: rgba(43,212,160,0.15); color: var(--ok); }
.badge.warn { background: rgba(255,184,77,0.15); color: var(--warn); }
.badge.danger { background: rgba(255,90,106,0.15); color: var(--danger); }
.badge.muted { background: rgba(147,160,184,0.15); color: var(--muted); }

.stale { color: var(--warn); font-weight: 600; }
.exception-flag { color: var(--danger); font-weight: 700; }

.login-wrap {
  display: flex; align-items: center; justify-content: center; height: 100%;
}
.login-card {
  width: 340px; background: var(--panel); border: 1px solid var(--border);
  border-radius: 10px; padding: 28px;
}
.login-card h1 { margin: 0 0 6px; font-size: 18px; }
.login-card p { margin: 0 0 18px; color: var(--muted); font-size: 12px; }
.error-msg { color: var(--danger); font-size: 12px; margin-top: 8px; }
.muted { color: var(--muted); }
.small { font-size: 12px; }

.map-wrap { position: relative; height: 480px; border-radius: 8px; overflow: hidden; border: 1px solid var(--border); }
.map-wrap.tall { height: 600px; }
#map { position: absolute; inset: 0; }

.timeline-item {
  border-left: 2px solid var(--border); padding: 6px 0 6px 12px; margin-bottom: 6px;
}
.timeline-item .ti-head { display: flex; justify-content: space-between; font-size: 12px; }
.timeline-item .ti-action { font-weight: 600; }
.timeline-item .ti-time { color: var(--muted); }
.timeline-item.failed .ti-action { color: var(--danger); }

.tag { display: inline-block; background: var(--panel2); border: 1px solid var(--border); border-radius: 4px; padding: 1px 6px; font-size: 11px; margin: 1px; }

.map-popup { font-size: 12px; }
.map-popup strong { display: block; margin-bottom: 4px; }

.modal-bg { position: fixed; inset: 0; background: rgba(0,0,0,0.5); display: flex; align-items: center; justify-content: center; z-index: 100; }
.modal { background: var(--panel); border: 1px solid var(--border); border-radius: 8px; padding: 20px; max-width: 600px; width: 90%; max-height: 85vh; overflow-y: auto; }
.modal h2 { margin-top: 0; }

