export function fmtTime(s?: string): string {
  if (!s) return "â";
  const d = new Date(s);
  if (isNaN(d.getTime())) return s;
  return d.toLocaleString();
}

export function relTime(s?: string): string {
  if (!s) return "â";
  const d = new Date(s);
  if (isNaN(d.getTime())) return s;
  const diff = Date.now() - d.getTime();
  const min = Math.floor(diff / 60000);
  if (min < 1) return "just now";
  if (min < 60) return `${min}m ago`;
  const hr = Math.floor(min / 60);
  if (hr < 24) return `${hr}h ago`;
  return `${Math.floor(hr / 24)}d ago`;
}

export function uid(): string {
  return crypto.randomUUID();
}

export function nowISO(): string {
  return new Date().toISOString();
}

export function inMinutesISO(min: number): string {
  return new Date(Date.now() + min * 60000).toISOString();
}

export const ROLE_LABELS: Record<string, string> = {
  administrator: "Administrator",
  dispatcher: "Dispatcher",
  requester: "Requester",
  collection_professional: "Collection Professional",
  delivery_partner: "Delivery Partner",
  node_handler: "Node Handler",
  laboratory_team: "Laboratory Team",
};

export function kv(o: Record<string, unknown>): string {
  return Object.entries(o)
    .map(([k, v]) => `${k}: ${typeof v === "object" ? JSON.stringify(v) : v}`)
    .join(", ");
}

