import { useEffect, useState } from "react";
import { api, useApp } from "../api";
import type { RoleWork, ServiceabilityResult, ServiceabilitySnapshot } from "../types";
import { fmtTime } from "../util";

export function RequesterView({ page }: { page: string }) {
  if (page === "new-request") return <NewRequest />;
  if (page === "serviceability") return <ServiceabilityCheck />;
  return <MyRequests />;
}

function MyRequests() {
  const { navigate } = useApp();
  const [work, setWork] = useState<RoleWork | null>(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    api.listRoleWork("requester").then((w) => { setWork(w); setLoading(false); }).catch(() => setLoading(false));
  }, []);

  if (loading) return <div className="muted">LoadingÃÃÂ¢ÃÂ¦</div>;
  if (!work) return null;

  const all = [...(work.inProgress || []), ...(work.pending || []), ...(work.completed || [])];

  return (
    <div>
      <h2>My Requests</h2>
      <div className="panel">
        {all.length === 0 ? (
          <span className="muted">You have no requests yet. Use "New Request" to create one.</span>
        ) : (
          <table>
            <thead><tr><th>Sample</th><th>Origin</th><th>Status</th><th>Deadline</th><th>Exception</th></tr></thead>
            <tbody>
              {all.map((item, i) => (
                <tr key={i} style={{ cursor: "pointer" }} onClick={() => navigate("sample", String(item.sampleId || item.id))}>
                  <td>{String(item.sampleId || item.id || "").slice(0, 8)}</td>
                  <td>{String(item.originType || item.origin_type || "ÃÃÂ¢ÃÃ")}</td>
                  <td><span className="badge muted">{String(item.status || item.state || "")}</span></td>
                  <td>{fmtTime(String(item.deliveryDeadline || item.delivery_deadline || ""))}</td>
                  <td>{item.exception ? <span className="exception-flag">Yes</span> : <span className="muted">No</span>}</td>
                </tr>
              ))}
            </tbody>
          </table>
        )}
      </div>
    </div>
  );
}

function NewRequest() {
  const { navigate } = useApp();
  const [originType, setOriginType] = useState("home");
  const [lat, setLat] = useState("12.9716");
  const [lng, setLng] = useState("77.5946");
  const [sampleTypeId, setSampleTypeId] = useState("Amber");
  const [collectFrom, setCollectFrom] = useState("");
  const [collectUntil, setCollectUntil] = useState("");
  const [deadline, setDeadline] = useState("");
  const [result, setResult] = useState<string | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [busy, setBusy] = useState(false);

  const submit = async () => {
    setBusy(true);
    setError(null);
    setResult(null);
    try {
      await api.createCollectionRequest({
        originType,
        origin: { latitude: parseFloat(lat), longitude: parseFloat(lng) },
        sampleType: sampleTypeId,
        collectionWindowStart: new Date(collectFrom).toISOString(),
        collectionWindowEnd: new Date(collectUntil).toISOString(),
        deliveryDeadline: new Date(deadline).toISOString(),
      });
      setResult("Request created successfully.");
      setTimeout(() => navigate("home"), 800);
    } catch (e) {
      setError((e as Error).message);
    } finally {
      setBusy(false);
    }
  };

  return (
    <div>
      <h2>New Collection Request</h2>
      <div className="panel" style={{ maxWidth: 520 }}>
        <div className="grid grid-2">
          <div className="form-row">
            <label>Origin type</label>
            <select value={originType} onChange={(e) => setOriginType(e.target.value)}>
              <option value="home">Home</option>
              <option value="clinic">Clinic</option>
              <option value="node">Network node</option>
            </select>
          </div>
          <div className="form-row">
            <label>Sample type</label>
            <select value={sampleTypeId} onChange={(e) => setSampleTypeId(e.target.value)}>
              <option>Amber</option><option>Indigo</option><option>Frost</option><option>Pulse</option>
            </select>
          </div>
          <div className="form-row">
            <label>Origin latitude</label>
            <input value={lat} onChange={(e) => setLat(e.target.value)} />
          </div>
          <div className="form-row">
            <label>Origin longitude</label>
            <input value={lng} onChange={(e) => setLng(e.target.value)} />
          </div>
          <div className="form-row">
            <label>Collection window start</label>
            <input type="datetime-local" value={collectFrom} onChange={(e) => setCollectFrom(e.target.value)} />
          </div>
          <div className="form-row">
            <label>Collection window end</label>
            <input type="datetime-local" value={collectUntil} onChange={(e) => setCollectUntil(e.target.value)} />
          </div>
          <div className="form-row" style={{ gridColumn: "1 / span 2" }}>
            <label>Delivery deadline</label>
            <input type="datetime-local" value={deadline} onChange={(e) => setDeadline(e.target.value)} />
          </div>
        </div>
        {error && <div className="error-msg">{error}</div>}
        {result && <div className="badge ok">{result}</div>}
        <button className="primary" onClick={submit} disabled={busy} style={{ marginTop: 12 }}>
          {busy ? "CreatingÃÃÂ¢ÃÂ¦" : "Create request"}
        </button>
      </div>
    </div>
  );
}

function ServiceabilityCheck() {
  const [originType, setOriginType] = useState("home");
  const [lat, setLat] = useState("12.9716");
  const [lng, setLng] = useState("77.5946");
  const [sampleType, setSampleType] = useState("Amber");
  const [deadline, setDeadline] = useState("");
  const [result, setResult] = useState<ServiceabilityResult | null>(null);
  const [snapshot, setSnapshot] = useState<ServiceabilitySnapshot | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [busy, setBusy] = useState(false);

  const check = async () => {
    setBusy(true);
    setError(null);
    setResult(null);
    try {
      const r = await api.checkServiceability({
        originType,
        origin: { latitude: parseFloat(lat), longitude: parseFloat(lng) },
        sampleType,
        deliveryDeadline: new Date(deadline).toISOString(),
      });
      setResult(r);
    } catch (e) {
      setError((e as Error).message);
    } finally {
      setBusy(false);
    }
  };

  useEffect(() => {
    api.readServiceabilitySnapshot().then(setSnapshot).catch(() => {});
  }, []);

  return (
    <div>
      <h2>Serviceability Check</h2>
      <div className="panel" style={{ maxWidth: 520 }}>
        <p className="muted small">
          This is a dry run ÃÃÂ¢ÃÃ it checks whether a location and sample can be serviced without creating a request.
        </p>
        <div className="grid grid-2">
          <div className="form-row">
            <label>Origin type</label>
            <select value={originType} onChange={(e) => setOriginType(e.target.value)}>
              <option value="home">Home</option><option value="clinic">Clinic</option><option value="node">Node</option>
            </select>
          </div>
          <div className="form-row">
            <label>Sample type</label>
            <select value={sampleType} onChange={(e) => setSampleType(e.target.value)}>
              <option>Amber</option><option>Indigo</option><option>Frost</option><option>Pulse</option>
            </select>
          </div>
          <div className="form-row"><label>Latitude</label><input value={lat} onChange={(e) => setLat(e.target.value)} /></div>
          <div className="form-row"><label>Longitude</label><input value={lng} onChange={(e) => setLng(e.target.value)} /></div>
          <div className="form-row" style={{ gridColumn: "1 / span 2" }}>
            <label>Delivery deadline</label>
            <input type="datetime-local" value={deadline} onChange={(e) => setDeadline(e.target.value)} />
          </div>
        </div>
        <button className="primary" onClick={check} disabled={busy} style={{ marginTop: 12 }}>
          {busy ? "CheckingÃÃÂ¢ÃÂ¦" : "Check serviceability"}
        </button>
        {error && <div className="error-msg">{error}</div>}
        {result && (
          <div style={{ marginTop: 12 }}>
            <span className={`badge ${result.serviceable ? "ok" : "danger"}`}>
              {result.serviceable ? "Serviceable" : "Not serviceable"}
            </span>
            <div className="small" style={{ marginTop: 6 }}>Reason: {result.reason}</div>
            {result.targetLaboratoryId && <div className="small">Target lab: {result.targetLaboratoryId.slice(0, 8)}</div>}
            {result.estimatedArrivalAt && <div className="small">Est. arrival: {fmtTime(result.estimatedArrivalAt)}</div>}
            {result.serviceabilityVersion && <div className="small muted">Calculation v{result.serviceabilityVersion}</div>}
          </div>
        )}
      </div>

      {snapshot && (
        <div className="panel">
          <h3>Serviceability snapshot</h3>
          <div className="small muted" style={{ marginBottom: 8 }}>
            Version {snapshot.version} ÃÃÂ¢ÃÃ computed {fmtTime(snapshot.computedAt)} ÃÃÂ¢ÃÃ {snapshot.activeCollectionPointCount} active collection points
          </div>
          {snapshot.regions.length > 0 && (
            <table>
              <thead><tr><th>Collection point</th><th>Latitude</th><th>Longitude</th><th>Coverage (km)</th></tr></thead>
              <tbody>
                {snapshot.regions.map((r) => (
                  <tr key={r.locationId}>
                    <td>{r.name}</td><td>{r.latitude.toFixed(4)}</td><td>{r.longitude.toFixed(4)}</td><td>{r.coverageKm}</td>
                  </tr>
                ))}
              </tbody>
            </table>
          )}
        </div>
      )}
    </div>
  );
}

