import { useEffect, useState } from "react";
import { api, useApp } from "../api";
import type { RoleWork } from "../types";
import { fmtTime, relTime } from "../util";

export function WorkerView() {
  const { bootstrap, navigate } = useApp();
  const role = bootstrap!.user.activeRole;
  const [work, setWork] = useState<RoleWork | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [tick, setTick] = useState(0);

  const load = () => {
    api.listRoleWork(role).then((w) => { setWork(w); setLoading(false); }).catch((e) => { setError((e as Error).message); setLoading(false); });
  };

  useEffect(() => {
    load();
    const t = setInterval(() => setTick((x) => x + 1), 15000);
    return () => clearInterval(t);
  }, [role]);

  useEffect(() => { load(); }, [tick, role]);

  if (loading) return <div className="muted">Loading workÃÃÃÂ¢ÃÂ¦</div>;
  if (error) return <div className="error-msg">{error}</div>;
  if (!work) return null;

  const renderSection = (title: string, items: any[]) => (
    <div className="panel">
      <h3>{title} ({items.length})</h3>
      {items.length === 0 ? <span className="muted">Nothing here.</span> : (
        <table>
          <tbody>
            {items.map((item, i) => (
              <tr key={i} style={{ cursor: "pointer" }} onClick={() => navigate("sample", String(item.sampleId || item.assignmentId || item.id))}>
                <td>
                  <div><strong>{item.kind || item.type || "Work item"}</strong></div>
                  <div className="small muted">
                    {item.sampleId && <>Sample {String(item.sampleId).slice(0, 8)} ÃÃÂ¢ÃÃ </>}
                    {item.assignmentId && <>Assignment {String(item.assignmentId).slice(0, 8)} ÃÃÂ¢ÃÃ </>}
                    <span className={`badge ${item.status ? "muted" : ""}`}>{String(item.status || item.state || "")}</span>
                  </div>
                  {item.deliveryDeadline && <div className="small">Deadline: {fmtTime(String(item.deliveryDeadline))}</div>}
                  {item.lastUpdated && <div className="small">Updated: {relTime(String(item.lastUpdated))}</div>}
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      )}
    </div>
  );

  return (
    <div>
      <h2>My Work</h2>
      {renderSection("In progress", work.inProgress || [])}
      {renderSection("Pending / offered", work.pending || [])}
      {renderSection("Completed", work.completed || [])}
    </div>
  );
}

