import { useEffect, useState } from "react";
import { api, useApp } from "../api";
import type { OperationsState } from "../types";
import { fmtTime, relTime } from "../util";

export function MonitorView() {
  const { navigate } = useApp();
  const [state, setState] = useState<OperationsState | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  const load = () => {
    api.readOperationsState().then((s) => { setState(s); setLoading(false); }).catch((e) => { setError((e as Error).message); setLoading(false); });
  };

  useEffect(() => {
    load();
    const t = setInterval(load, 10000);
    return () => clearInterval(t);
  }, []);

  if (loading) return <div className="muted">Loading dashboardÃÃÃÂ¢ÃÂ¦</div>;
  if (error) return <div className="error-msg">{error}</div>;
  if (!state) return null;

  const samples = (state.samples || []) as any[];
  const workers = (state.workers || []) as any[];
  const exceptions = (state.exceptions || []) as any[];
  const nodes = (state.locations || []) as any[];
  const active = (state.activeSamples ?? samples.filter((s) => !String(s.status || "").includes("complet") && !String(s.status || "").includes("received"))).length;

  return (
    <div>
      <h2>Monitor Dashboard</h2>
      <div className="grid grid-3">
        <StatCard label="Samples" value={samples.length} sub={`${active} active`} />
        <StatCard label="Exceptions" value={exceptions.length} danger={exceptions.length > 0} />
        <StatCard label="Workers" value={workers.length} />
        <StatCard label="Nodes" value={(state.nodes ?? nodes.length) || nodes.length} />
        <StatCard label="Laboratories" value={(state.laboratories ?? 0) || nodes.filter((n) => n.functions?.includes?.("laboratory")).length} />
        <StatCard label="Connections" value={(state.connections || []).length} />
      </div>

      <div className="panel">
        <h3>Exceptions ({exceptions.length})</h3>
        {exceptions.length === 0 ? <span className="muted">No exceptions.</span> : (
          <table>
            <thead><tr><th>Sample</th><th>Reason</th><th>Time</th></tr></thead>
            <tbody>
              {exceptions.map((e, i) => (
                <tr key={i}>
                  <td>{String(e.sampleId || "").slice(0, 8)}</td>
                  <td className="exception-flag">{String(e.reason || e.type || "")}</td>
                  <td>{relTime(String(e.at || e.occurredAt || e.created_at))}</td>
                </tr>
              ))}
            </tbody>
          </table>
        )}
      </div>

      <div className="panel">
        <h3>Samples ({samples.length})</h3>
        {samples.length === 0 ? <span className="muted">No samples.</span> : (
          <table>
            <thead><tr><th>Sample</th><th>Type</th><th>Status</th><th>Holder</th><th>Location</th><th>Stale</th></tr></thead>
            <tbody>
              {samples.map((s, i) => {
                const loc = s.location || s.latestLocation;
                const stale = loc?.stale ?? s.locationStale;
                return (
                  <tr key={i} style={{ cursor: "pointer" }} onClick={() => navigate("sample", String(s.sampleId || s.id))}>
