import { useState } from "react";
import { api } from "../api";
import { ROLE_LABELS } from "../util";

export function AdminView() {
  const [tab, setTab] = useState("users");
  return (
    <div>
      <h2>Administration</h2>
      <div style={{ display: "flex", gap: 8, marginBottom: 16 }}>
        {["users", "locations", "connections", "sample-types", "capacity"].map((t) => (
          <button key={t} className={tab === t ? "primary" : ""} onClick={() => setTab(t)}>
            {t.replace("-", " ").replace(/\b\w/g, (c) => c.toUpperCase())}
          </button>
        ))}
      </div>
      {tab === "users" && <UsersTab />}
      {tab === "locations" && <LocationsTab />}
      {tab === "connections" && <ConnectionsTab />}
      {tab === "sample-types" && <SampleTypesTab />}
      {tab === "capacity" && <CapacityTab />}
    </div>
  );
}

function UsersTab() {
  const [username, setUsername] = useState("");
  const [password, setPassword] = useState("");
  const [fullName, setFullName] = useState("");
  const [email, setEmail] = useState("");
  const [roles, setRoles] = useState<string[]>(["requester"]);
  const [result, setResult] = useState<string | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [userId, setUserId] = useState("");
