import { useState } from "react";
import { api } from "../api";
import type { AuditSearchResult } from "../types";
import { fmtTime } from "../util";

export function AuditView() {
  const [query, setQuery] = useState("");
  const [entityType, setEntityType] = useState("");
  const [entityId, setEntityId] = useState("");
  const [action, setAction] = useState("");
  const [actor, setActor] = useState("");
  const [from, setFrom] = useState("");
  const [until, setUntil] = useState("");
  const [result, setResult] = useState<AuditSearchResult | null>(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const search = async () => {
    setLoading(true); setError(null);
    try {
      const body: Record<string, unknown> = { limit: 100, order: "desc" };
      if (query) body.query = query;
      if (entityType) body.entityType = entityType;
      if (entityId) body.entityId = entityId;
      if (action) body.action = action;
      if (actor) body.actorId = actor;
      if (from) body.from = new Date(from).toISOString();
      if (until) body.until = new Date(until).toISOString();
      const r = await api.searchAudit(body);
      setResult(r);
    } catch (e) { setError((e as Error).message); }
    finally { setLoading(false); }
  };

  return (
    <div>
      <h2>Audit Trail</h2>
      <div className="panel">
        <div className="grid grid-3">
          <div className="form-row"><label>Query</label><input value={query} onChange={(e) => setQuery(e.target.value)} placeholder="free text" /></div>
          <div className="form-row"><label>Entity type</label>
            <select value={entityType} onChange={(e) => setEntityType(e.target.value)}>
              <option value="">any</option>
              <option>sample</option><option>request</option><option>journey</option>
              <option>assignment</option><option>handoff</option><option>location</option>
              <option>connection</option><option>capacity</option><option>user</option>
            </select>
          </div>
          <div className="form-row"><label>Entity ID</label><input value={entityId} onChange={(e) => setEntityId(e.target.value)} /></div>
          <div className="form-row"><label>Action</label><input value={action} onChange={(e) => setAction(e.target.value)} placeholder="e.g. collect_and_seal" /></div>
          <div className="form-row"><label>Actor ID</label><input value={actor} onChange={(e) => setActor(e.target.value)} /></div>
