import { useEffect, useRef, useState } from "react";
import maplibregl from "maplibre-gl";
import { Protocol } from "pmtiles";
import "maplibre-gl/dist/maplibre-gl.css";
import { api } from "../api";
import type { OperationsState } from "../types";

const CENTER: [number, number] = [77.5946, 12.9716];

export function MapView() {
  const containerRef = useRef<HTMLDivElement>(null);
  const mapRef = useRef<maplibregl.Map | null>(null);
  const [state, setState] = useState<OperationsState | null>(null);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    api.readOperationsState().then(setState).catch((e) => setError((e as Error).message));
  }, []);

  useEffect(() => {
    if (!containerRef.current || mapRef.current) return;

    const protocol = new Protocol();
    maplibregl.addProtocol("pmtiles", protocol.tile);

    const map = new maplibregl.Map({
      container: containerRef.current,
      style: "/map-assets/style.json",
      center: CENTER,
      zoom: 10,
    });
    mapRef.current = map;

    map.addControl(new maplibregl.NavigationControl(), "top-right");

    map.on("load", () => {
      addOverlays(map);
    });

    return () => {
      map.remove();
      mapRef.current = null;
    };
  }, []);

  useEffect(() => {
    const map = mapRef.current;
    if (!map || !state || !map.loaded()) return;
    updateOverlays(map, state);
  }, [state]);

  const addOverlays = (map: maplibregl.Map) => {
    map.addSource("samples", { type: "geojson", data: { type: "FeatureCollection", features: [] } });
    map.addSource("workers", { type: "geojson", data: { type: "FeatureCollection", features: [] } });
    map.addSource("nodes", { type: "geojson", data: { type: "FeatureCollection", features: [] } });

    map.addLayer({
      id: "nodes",
      type: "circle",
      source: "nodes",
      paint: { "circle-radius": 7, "circle-color": "#4f9eff", "circle-stroke-color": "#fff", "circle-stroke-width": 1.5 },
    });

    map.addLayer({
      id: "samples",
      type: "circle",
      source: "samples",
      paint: {
        "circle-radius": 6,
        "circle-color": ["case", ["get", "exception"], "#ff5a6a", "#2bd4a0"],
        "circle-stroke-color": "#fff", "circle-stroke-width": 1.5,
      },
    });

    map.addLayer({
      id: "workers",
      type: "circle",
      source: "workers",
      paint: { "circle-radius": 5, "circle-color": "#ffb84d", "circle-stroke-color": "#fff", "circle-stroke-width": 1 },
    });

    const popup = new maplibregl.Popup({ offset: 15 });
    for (const layerId of ["nodes", "samples", "workers"]) {
      map.on("click", layerId, (e) => {
        const f = e.features?.[0];
        if (!f) return;
        const html = (f.properties?.html as string) || f.properties?.title || "";
        popup.setLngLat(e.lngLat).setHTML(html).addTo(map);
      });
      map.on("mouseenter", layerId, () => (map.getCanvas().style.cursor = "pointer"));
      map.on("mouseleave", layerId, () => (map.getCanvas().style.cursor = ""));
    }
  };

  const updateOverlays = (map: maplibregl.Map, st: OperationsState) => {
    const sampleFeats = ((st.samples || []) as any[])
      .filter((s) => s.location || s.latestLocation)
      .map((s) => {
        const loc = s.location || s.latestLocation;
        return {
          type: "Feature" as const,
          geometry: { type: "Point" as const, coordinates: [Number(loc.longitude), Number(loc.latitude)] },
          properties: {
            exception: !!s.exception,
            html: `<div class="map-popup"><strong>Sample ${String(s.sampleId || "").slice(0, 8)}</strong>Status: ${s.status}<br/>${loc.stale ? '<span style="color:#ffb84d">stale location</span>' : ""}</div>`,
          },
        };
      });

    const workerFeats = ((st.workers || []) as any[])
      .filter((w) => w.location || w.latestLocation)
      .map((w) => {
        const loc = w.location || w.latestLocation;
        return {
          type: "Feature" as const,
          geometry: { type: "Point" as const, coordinates: [Number(loc.longitude), Number(loc.latitude)] },
          properties: {
            html: `<div class="map-popup"><strong>Worker ${String(w.workerId || w.userId || "").slice(0, 8)}</strong>${w.role || ""}<br/>${w.available ? "available" : "unavailable"}${loc.stale ? "<br/><span style='color:#ffb84d'>stale</span>" : ""}</div>`,
          },
        };
      });

    const nodeFeats = ((st.locations || []) as any[])
      .filter((n) => n.latitude != null || n.coordinate)
      .map((n) => {
        const lat = n.latitude ?? n.coordinate?.latitude;
        const lng = n.longitude ?? n.coordinate?.longitude;
        return {
          type: "Feature" as const,
          geometry: { type: "Point" as const, coordinates: [Number(lng), Number(lat)] },
          properties: {
            html: `<div class="map-popup"><strong>${n.name || n.locationId}</strong>Functions: ${(n.functions || []).join(", ")}<br/>${n.active ? "active" : "inactive"}</div>`,
          },
        };
      });

    const src1 = map.getSource("samples") as maplibregl.GeoJSONSource;
    const src2 = map.getSource("workers") as maplibregl.GeoJSONSource;
    const src3 = map.getSource("nodes") as maplibregl.GeoJSONSource;
    src1?.setData({ type: "FeatureCollection", features: sampleFeats });
    src2?.setData({ type: "FeatureCollection", features: workerFeats });
    src3?.setData({ type: "FeatureCollection", features: nodeFeats });
  };

  return (
    <div>
      <h2>Live Map</h2>
      {error && <div className="error-msg">{error}</div>}
      <div className="map-wrap tall">
        <div ref={containerRef} id="map" />
      </div>
      <div className="small muted" style={{ marginTop: 8 }}>
        <span style={{ color: "#4f9eff" }}>Ã¢Ã¢ÃÂ¢</span> Nodes &amp; labs ÃÃÂ¢ÃÃ
        <span style={{ color: "#2bd4a0" }}>Ã¢Ã¢ÃÂ¢</span> Samples ÃÃÂ¢ÃÃ
        <span style={{ color: "#ff5a6a" }}>Ã¢Ã¢ÃÂ¢</span> Exceptions ÃÃÂ¢ÃÃ
        <span style={{ color: "#ffb84d" }}>Ã¢Ã¢ÃÂ¢</span> Workers
      </div>
    </div>
  );
}

