  const active = state.activeSamples ?? samples.filter((s) => !String(s.status || "").includes("complet") && !String(s.status || "").includes("received")).length;

  return (
    <div>
      <h2>Monitor Dashboard</h2>
      <div className="grid grid-3">
        <StatCard label="Samples" value={samples.length} sub={`${active} active`} />
        <StatCard label="Exceptions" value={exceptions.length} danger={exceptions.length > 0} />
        <StatCard label="Workers" value={workers.length} />
        <StatCard label="Nodes" value={(state.nodes ?? nodes.length) || nodes.length} />
        <StatCard label="Laboratories" value={(state.laboratories ?? 0) || nodes.filter((n) => n.functions?.includes?.("laboratory")).length} />
        <StatCard label="Connections" value={(state.connections || []).length} />
      </div>

      <div className="panel">
        <h3>Exceptions ({exceptions.length})</h3>
        {exceptions.length === 0 ? <span className="muted">No exceptions.</span> : (
          <table>
            <thead><tr><th>Sample</th><th>Reason</th><th>Time</th></tr></thead>
            <tbody>
              {exceptions.map((e, i) => (
                <tr key={i}>
                  <td>{String(e.sampleId || "").slice(0, 8)}</td>
                  <td className="exception-flag">{String(e.reason || e.type || "")}</td>
                  <td>{relTime(String(e.at || e.occurredAt || e.created_at))}</td>
                </tr>
              ))}
            </tbody>
          </table>
        )}
      </div>

      <div className="panel">
        <h3>Samples ({samples.length})</h3>
        {samples.length === 0 ? <span className="muted">No samples.</span> : (
          <table>
            <thead><tr><th>Sample</th><th>Type</th><th>Status</th><th>Holder</th><th>Location</th><th>Stale</th></tr></thead>
            <tbody>
              {samples.map((s, i) => {
                const loc = s.location || s.latestLocation;
                const stale = loc?.stale ?? s.locationStale;
                return (
                  <tr key={i} style={{ cursor: "pointer" }} onClick={() => navigate("sample", String(s.sampleId || s.id))}>
                    <td>{String(s.sampleId || s.id || "").slice(0, 8)}</td>
                    <td>{s.sampleType || s.sample_type || ""}</td>
                    <td><span className="badge muted">{String(s.status || "")}</span></td>
                    <td>{s.currentHolderId ? String(s.currentHolderId).slice(0, 8) : ""}</td>
                    <td>{loc ? `${Number(loc.latitude).toFixed(3)},${Number(loc.longitude).toFixed(3)}` : ""}</td>
                    <td>{stale ? <span className="stale">stale</span> : <span className="muted">-</span>}</td>
                  </tr>
                );
              })}
            </tbody>
          </table>
        )}
      </div>

      <div className="panel">
        <h3>Workers ({workers.length})</h3>
        {workers.length === 0 ? <span className="muted">No workers.</span> : (
          <table>
            <thead><tr><th>Worker</th><th>Role</th><th>Available</th><th>Location</th><th>Last update</th></tr></thead>
            <tbody>
              {workers.map((w, i) => {
                const loc = w.location || w.latestLocation;
                return (
                  <tr key={i}>
                    <td>{String(w.workerId || w.userId || "").slice(0, 8)}</td>
                    <td>{w.role || ""}</td>
                    <td>{w.available ? <span className="badge ok">yes</span> : <span className="badge muted">no</span>}</td>
                    <td>{loc ? `${Number(loc.latitude).toFixed(3)},${Number(loc.longitude).toFixed(3)}` : ""}</td>
                    <td className={loc?.stale ? "stale" : "muted"}>{relTime(String(loc?.recordedAt || w.lastUpdated || ""))}</td>
                  </tr>
                );
              })}
            </tbody>
          </table>
        )}
      </div>

      <div className="panel">
        <h3>Network locations ({nodes.length})</h3>
        {nodes.length === 0 ? <span className="muted">No locations.</span> : (
          <table>
            <thead><tr><th>Name</th><th>Functions</th><th>Active</th><th>Location</th></tr></thead>
            <tbody>
              {nodes.map((n, i) => (
                <tr key={i}>
                  <td>{n.name || n.locationId}</td>
                  <td>{Array.isArray(n.functions) ? n.functions.join(", ") : ""}</td>
                  <td>{n.active ? <span className="badge ok">active</span> : <span className="badge muted">inactive</span>}</td>
                  <td>{n.latitude != null ? `${Number(n.latitude).toFixed(3)},${Number(n.longitude).toFixed(3)}` : ""}</td>
                </tr>
              ))}
            </tbody>
          </table>
        )}
      </div>
    </div>
  );
}

function StatCard({ label, value, sub, danger }: { label: string; value: number; sub?: string; danger?: boolean }) {
  return (
    <div className="panel" style={{ marginBottom: 0 }}>
      <div className="muted small">{label}</div>
      <div style={{ fontSize: 28, fontWeight: 700, color: danger ? "var(--danger)" : "var(--text)" }}>{value}</div>
      {sub && <div className="small muted">{sub}</div>}
    </div>
  );
}

