			return err
		}
		in := serviceabilityInput{
			OriginType:      req.OriginType,
			OriginLat:       req.Origin.Latitude,
			OriginLng:       req.Origin.Longitude,
			OriginNodeID:    req.OriginNodeId,
			SampleTypeID:    req.SampleTypeId,
			RequiresCooled:  st.RequiresCooled,
			RequestedAt:     requestedAt,
			Deadline:        deadline,
			EarliestCollect: earliest,
			LatestCollect:   latest,
			SampleID:        sid,
		}
		entry, route, labID, estArrival, ae := a.resolveEntryAndRoute(r.Context(), in)
		if ae != nil {
			return ae
		}
		// build journey using tx
		p, be := a.buildJourneyTx(r.Context(), t, in, st, entry, route, labID, estArrival, false, sid)
		if be != nil {
			return be
		}
		_, err = t.Exec(r.Context(), `INSERT INTO journey_samples (journey_id, sample_id) VALUES ($1,$2)`, p.JourneyID, sid)
		if err != nil {
			return err
		}
		_, err = t.Exec(r.Context(), `UPDATE samples SET active_journey_id=$1, target_laboratory_id=$2 WHERE sample_id::text=$3`, p.JourneyID, labID, sid)
		if err != nil {
			return err
		}
		requestID = rid
		sampleID = sid
		journeyID = p.JourneyID
		targetLabID = labID
		activeAssigns = p.AssignmentIDs
		if len(activeAssigns) == 0 {
			activeAssigns = []string{}
		}
		_ = estArrival
		return nil
	})
	if err != nil {
		serviceable = false
	}
	a.audit(r.Context(), u, "create_collection_request", "request", requestID, true, map[string]any{"sampleId": sampleID, "serviceable": serviceable})
	if journeyID != "" {
		a.audit(r.Context(), u, "create_journey", "journey", journeyID, true, map[string]any{"sampleId": sampleID})
	}
	a.emitRealtime(r.Context(), "sample.created", "sample", sampleID, map[string]any{"requestId": requestID})
	servStr := "serviceable"
	if !serviceable {
		servStr = "unserviceable"
	}
	out := map[string]any{
		"requestId":            requestID,
		"sampleId":             sampleID,
		"serviceability":       servStr,
		"serviceabilityReason": "",
		"activeAssignmentIds":  activeAssigns,
		"earliestCollectionAt": rfcOrEmpty(earliest),
		"latestCollectionAt":   rfcOrEmpty(latest),
		"alreadySealed":        false,
		"originType":            req.OriginType,
	}
	if journeyID != "" {
		out["journeyId"] = journeyID
	}
	if targetLabID != "" {
		out["targetLaboratoryId"] = targetLabID
	}
	if activeAssigns == nil {
		out["activeAssignmentIds"] = []string{}
	}
	writeData(w, 201, out)
}

