[?2004l// handleReadServiceabilitySnapshot implements POST /api/read-serviceability-snapshot.
func (a *App) handleReadServiceabilitySnapshot(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		writeError(w, errCode(405, "method_not_allowed", "POST required"))
		return
	}
	u := currentUser(r)
	if e := requireRole(u, "administrator", "dispatcher", "requester"); e != nil {
		writeError(w, e)
		return
	}
	// Body is an empty object per contract; tolerate empty/absent body.
	_ = decodeJSON(r, &struct{}{})
	ver := a.currentServiceabilityVersion(r.Context())
	var computedAt string
	var regions []map[string]any
	var cpCount, netRev int
	_ = a.pg.QueryRow(r.Context(), `SELECT computed_at::text, regions, active_cp_count, network_revision FROM serviceability_versions WHERE version=$1 AND status='complete'`, ver).Scan(&computedAt, &regions, &cpCount, &netRev)
	if regions == nil {
		regions = []map[string]any{}
	}
	writeData(w, 200, map[string]any{
		"version":                 ver,
		"status":                  "complete",
		"computedAt":              computedAt,
		"networkRevision":         netRev,
		"regions":                 regions,
		"activeCollectionPointCount": cpCount,
	})
}

func nilIfEmpty(s string) any {
	if s == "" {
		return nil
	}
	return s
}

func nilIfZero(t time.Time) any {
	if t.IsZero() {
		return nil
	}
	return t
}

// rfcOrEmpty returns an RFC3339 string for a non-zero time, or "" otherwise.
func rfcOrEmpty(t time.Time) string {
	if t.IsZero() {
		return ""
	}
	return rfc(t)
}[?2004h

