func (a *App) handleAcceptAssignment(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		writeError(w, errCode(405, "method_not_allowed", "POST required"))
		return
	}
	u := currentUser(r)
	if e := requireRole(u, workerRoles()...); e != nil {
		writeError(w, e)
		return
	}
	var req struct {
		AssignmentID string `json:"assignmentId"`
	}
