	if !compliant {
		_, _ = a.pg.Exec(r.Context(), `UPDATE samples SET exception=$1 WHERE sample_id::text=$2`, toJSONB(map[string]any{"reason": "temperature_out_of_range", "category": "handling", "observedTemperatureC": req.ObservedTemperatureC}), req.SampleID)
		_, _ = a.pg.Exec(r.Context(), `INSERT INTO exceptions (exception_id, sample_id, reason, category, observed_at) VALUES ($1,$2,'temperature_out_of_range','handling',now())`, uuidStr(), req.SampleID)
