package main

import (
	"context"
	"net/http"
	"time"
)

func workerRoles() []string {
	return []string{"collection_professional", "delivery_partner", "node_handler", "laboratory_team"}
}

func isWorker(u *AuthUser) bool {
	for _, r := range workerRoles() {
		if u.ActiveRole == r {
			return true
		}
	}
	return false
}

// assignmentRow loads an assignment with related sample/journey info.
type assignmentRow struct {
	AssignmentID string
	JourneyID    string
	Kind         string
	Sequence     int
	Status       string
	FromLoc      *string
	ToLoc        *string
	WorkerID     *string
	SampleID     *string
	NodeID       *string
	LabID        *string
}

func loadAssignment(ctx context.Context, q pgxQuerier, id string) (*assignmentRow, *apiError) {
	var a assignmentRow
	err := q.QueryRow(ctx, `SELECT assignment_id::text, journey_id::text, kind, sequence, status, from_location_id::text, to_location_id::text, worker_id::text, sample_id::text, node_id::text, laboratory_id::text FROM assignments WHERE assignment_id::text=$1`, id).
		Scan(&a.AssignmentID, &a.JourneyID, &a.Kind, &a.Sequence, &a.Status, &a.FromLoc, &a.ToLoc, &a.WorkerID, &a.SampleID, &a.NodeID, &a.LabID)
	if err != nil {
		return nil, errNotFound
	}
	return &a, nil
}

// handleListRoleWork implements POST /api/list-role-work.
func (a *App) handleListRoleWork(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		writeError(w, errCode(405, "method_not_allowed", "POST required"))
		return
	}
	u := currentUser(r)
	var req struct {
		Role string `json:"role"`
	}
	if err := decodeJSON(r, &req); err != nil {
		writeError(w, errInvalidJSON)
		return
	}
	if req.Role == "" {
		req.Role = u.ActiveRole
	}
	if !u.hasRole(req.Role) {
		writeError(w, errForbidden)
		return
	}
	out := a.roleWork(r.Context(), u.UserID, req.Role)
	writeData(w, 200, out)
}

// roleWork builds the RoleWork view for a user under a given role.
func (a *App) roleWork(ctx context.Context, userID, role string) map[string]any {
	current := []map[string]any{}
	past := []map[string]any{}
	switch role {
	case "requester":
		rows, _ := a.pg.Query(ctx, `SELECT s.sample_id::text, s.status, s.origin_type, st.name, j.journey_id::text, s.exception
			FROM samples s JOIN sample_types st ON st.sample_type_id=s.sample_type_id
			LEFT JOIN journeys j ON j.journey_id=s.active_journey_id
			WHERE s.requester_id::text=$1 ORDER BY s.created_at DESC`, userID)
		current, past = scanRoleWorkRequester(rows)
	case "collection_professional", "delivery_partner", "node_handler", "laboratory_team":
		rows, _ := a.pg.Query(ctx, `SELECT a.assignment_id::text, a.kind, a.status, a.sample_id::text, a.from_location_id::text, a.to_location_id::text, a.node_id::text, a.laboratory_id::text, j.status, s.status
			FROM assignments a JOIN journeys j ON j.journey_id=a.journey_id
			LEFT JOIN samples s ON s.sample_id=a.sample_id
			WHERE a.worker_id::text=$1 ORDER BY a.created_at DESC`, userID)
		current, past = scanRoleWorkWorker(rows)
	default:
		// dispatcher/admin see all open/past assignments
		rows, _ := a.pg.Query(ctx, `SELECT a.assignment_id::text, a.kind, a.status, a.sample_id::text, a.from_location_id::text, a.to_location_id::text, a.node_id::text, a.laboratory_id::text, j.status, s.status
			FROM assignments a JOIN journeys j ON j.journey_id=a.journey_id
			LEFT JOIN samples s ON s.sample_id=a.sample_id
			ORDER BY a.created_at DESC LIMIT 200`)
		current, past = scanRoleWorkWorker(rows)
	}
	return map[string]any{
		"role":    role,
		"current": current,
		"past":    past,
	}
}

func scanRoleWorkWorker(rows pgxRows) ([]map[string]any, []map[string]any) {
	if rows == nil {
		return []map[string]any{}, []map[string]any{}
	}
	defer rows.Close()
	current := []map[string]any{}
	past := []map[string]any{}
	for rows.Next() {
		var aid, kind, status, jStatus, sStatus string
		var sampleID, from, to, node, lab *string
		_ = rows.Scan(&aid, &kind, &status, &sampleID, &from, &to, &node, &lab, &jStatus, &sStatus)
		item := map[string]any{
			"assignmentId": aid,
			"kind":         kind,
			"status":       status,
			"sampleId":     strPtr(sampleID),
			"journeyStatus": jStatus,
			"sampleStatus":  sStatus,
		}
		if from != nil {
			item["fromLocationId"] = *from
		}
		if to != nil {
			item["toLocationId"] = *to
		}
		if node != nil {
			item["nodeId"] = *node
		}
		if lab != nil {
			item["laboratoryId"] = *lab
		}
		if isTerminalStatus(status) {
			past = append(past, item)
		} else {
			current = append(current, item)
		}
	}
	return current, past
}

func scanRoleWorkRequester(rows pgxRows) ([]map[string]any, []map[string]any) {
	if rows == nil {
		return []map[string]any{}, []map[string]any{}
	}
	defer rows.Close()
	current := []map[string]any{}
	past := []map[string]any{}
	for rows.Next() {
		var sid, status, origin, stName string
		var jID *string
		var exc []byte
		_ = rows.Scan(&sid, &status, &origin, &stName, &jID, &exc)
		item := map[string]any{
			"sampleId":   sid,
			"status":     status,
			"originType": origin,
			"sampleType": stName,
		}
		if jID != nil {
			item["journeyId"] = *jID
		}
		if len(exc) > 0 && string(exc) != "null" {
			item["exception"] = jsonRaw(exc)
		}
		if status == "received" || status == "cancelled" || status == "expired" {
			past = append(past, item)
		} else {
			current = append(current, item)
		}
	}
	return current, past
}

func isTerminalStatus(s string) bool {
	switch s {
	case "completed", "declined", "cancelled", "expired":
		return true
	}
	return false
}

func strPtr(s *string) string {
	if s == nil {
		return ""
	}
	return *s
}

// handleAcceptAssignment implements POST /api/accept-assignment.
func (a *App) handleAcceptAssignment(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		writeError(w, errCode(405, "method_not_allowed", "POST required"))
		return
	}
	u := currentUser(r)
	if e := requireRole(u, workerRoles()...); e != nil {
		writeError(w, e)
		return
	}
	var req struct {
		AssignmentID  string `json:"assignmentId"`
		IdempotencyKey string `json:"idempotencyKey"`
	}
	if err := decodeJSON(r, &req); err != nil {
		writeError(w, errInvalidJSON)
		return
	}
	ar, e := loadAssignment(r.Context(), a.pg, req.AssignmentID)
	if e != nil {
		writeError(w, e)
		return
	}
	if ar.WorkerID == nil || *ar.WorkerID != u.UserID {
		writeError(w, errCode(403, "not_assigned", "assignment not offered to you"))
		return
	}
	if ar.Status != "offered" {
		writeError(w, errCode(409, "invalid_state", "assignment not offered"))
		return
	}
	_, err := a.pg.Exec(r.Context(), `UPDATE assignments SET status='accepted' WHERE assignment_id::text=$1 AND status='offered'`, req.AssignmentID)
	if err != nil {
		writeError(w, errConflict)
		return
	}
	if ar.SampleID != nil {
		_, _ = a.pg.Exec(r.Context(), `UPDATE samples SET current_holder_id=$1 WHERE sample_id::text=$2`, u.UserID, *ar.SampleID)
	}
	a.audit(r.Context(), u, "accept_assignment", "assignment", req.AssignmentID, true, nil)
	a.emitRealtime(r.Context(), "assignment.accepted", "assignment", req.AssignmentID, map[string]any{"workerId": u.UserID})
	writeData(w, 201, map[string]any{
		"assignmentId": req.AssignmentID,
		"workerId":     u.UserID,
		"status":       "accepted",
	})
}

