// handleConfirmLaboratoryReceipt implements POST /api/confirm-laboratory-receipt (laboratory_team).
func (a *App) handleConfirmLaboratoryReceipt(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		writeError(w, errCode(405, "method_not_allowed", "POST required"))
		return
	}
	u := currentUser(r)
	if e := requireRole(u, "laboratory_team"); e != nil {
		writeError(w, e)
		return
	}
	var req struct {
		AssignmentID string `json:"assignmentId"`
		SampleID     string `json:"sampleId"`
		ReceivedAt   string `json:"receivedAt"`
	}
	if err := decodeJSON(r, &req); err != nil {
		writeError(w, errInvalidJSON)
		return
	}
	var labID *string
	if req.AssignmentID != "" {
		ar, e := loadAssignment(r.Context(), a.pg, req.AssignmentID)
		if e != nil {
			writeError(w, e)
			return
		}
		if ar.WorkerID == nil || *ar.WorkerID != u.UserID {
			writeError(w, errForbidden)
			return
		}
		labID = ar.LabID
		_, _ = a.pg.Exec(r.Context(), `UPDATE assignments SET status='completed' WHERE assignment_id::text=$1`, req.AssignmentID)
	} else {
		var aLoc *string
		_ = a.pg.QueryRow(r.Context(), `SELECT assigned_location_id::text FROM users WHERE user_id::text=$1`, u.UserID).Scan(&aLoc)
		labID = aLoc
	}
	_, err := a.pg.Exec(r.Context(), `UPDATE samples SET status='received', received_laboratory_id=$1, current_holder_id=NULL WHERE sample_id::text=$2`, labID, req.SampleID)
	if err != nil {
		writeError(w, errConflict)
		return
	}
	// Complete the journey.
	_, _ = a.pg.Exec(r.Context(), `UPDATE journeys SET status='completed' WHERE journey_id=(SELECT active_journey_id FROM samples WHERE sample_id::text=$1)`, req.SampleID)
	a.audit(r.Context(), u, "confirm_laboratory_receipt", "sample", req.SampleID, true, map[string]any{"laboratoryId": strPtr(labID)})
	a.emitRealtime(r.Context(), "sample.received", "sample", req.SampleID, map[string]any{"laboratoryId": strPtr(labID)})
	writeData(w, 201, map[string]any{
		"sampleId":      req.SampleID,
		"status":        "received",
		"laboratoryId":  strPtr(labID),
		"receivedAt":    nowRFC(),
	})
}

