		_ = a.pg.QueryRow(r.Context(), `SELECT COALESCE(worker_id::text,'') FROM assignments WHERE assignment_id::text=$1`, toAssignID).Scan(&newHolder)
		if newHolder == "" {
			newHolder = u.UserID
		}
		_, _ = a.pg.Exec(r.Context(), `UPDATE samples SET current_holder_id=$1 WHERE sample_id::text=$2`, newHolder, sampleID)
		// Mark previous assignment completed; mark next assignment in_progress.
		_, _ = a.pg.Exec(r.Context(), `UPDATE assignments SET status='completed' WHERE (SELECT from_assignment_id FROM handoffs WHERE handoff_id::text=$1)::text=assignment_id::text`, req.HandoffID)
		if toAssignID != "" {
			_, _ = a.pg.Exec(r.Context(), `UPDATE assignments SET status='in_progress' WHERE assignment_id::text=$1`, toAssignID)
		}
		// If next assignment is laboratory kind, sample becomes received.
		var kind string
		_ = a.pg.QueryRow(r.Context(), `SELECT kind FROM assignments WHERE assignment_id::text=$1`, toAssignID).Scan(&kind)
		if kind == "laboratory" {
			_, _ = a.pg.Exec(r.Context(), `UPDATE samples SET status='at_lab' WHERE sample_id::text=$1`, sampleID)
		} else {
			_, _ = a.pg.Exec(r.Context(), `UPDATE samples SET status='in_transit' WHERE sample_id::text=$1`, sampleID)
		}
		a.emitRealtime(r.Context(), "handoff.completed", "sample", sampleID, map[string]any{"holder": newHolder})
	}
	a.audit(r.Context(), u, "confirm_handoff", "handoff", req.HandoffID, true, nil)
	writeData(w, 201, map[string]any{
		"handoffId":       req.HandoffID,
		"status":          handoffStatus(s, rc),
		"senderConfirmed": s,
		"receiverConfirmed": rc,
	})
