	_, _ = a.pg.Exec(r.Context(), `INSERT INTO worker_locations (assignment_id, sequence, latitude, longitude, recorded_at)
		SELECT a.assignment_id, COALESCE((SELECT MAX(sequence) FROM worker_locations WHERE assignment_id=a.assignment_id),0)+1, $1, $2, now()
