// reofferAssignment clears the current worker and offers to the next eligible worker.
// Returns the next worker's id, or "" if none available.
func (a *App) reofferAssignment(ctx context.Context, ar *assignmentRow, declinedWorker string) string {
	role := roleForKind(ar.Kind)
	qual := ""
	if ar.Kind == "collection" {
		var stName string
		_ = a.pg.QueryRow(ctx, `SELECT st.name FROM samples s JOIN sample_types st ON st.sample_type_id=s.sample_type_id WHERE s.sample_id::text=$1`, strPtr(ar.SampleID)).Scan(&stName)
		qual = stName
	}
	workers, _ := eligibleWorkers(ctx, a.pg, role, qual)
	var next *workerSummary
	for i := range workers {
		if workers[i].UserID == declinedWorker {
			continue
		}
		if ar.Kind == "node" || ar.Kind == "laboratory" {
			locID := strPtr(ar.NodeID)
			if ar.Kind == "laboratory" {
				locID = strPtr(ar.LabID)
			}
			if workers[i].AssignedLocationID != nil && *workers[i].AssignedLocationID == locID {
				next = &workers[i]
				break
			}
			continue
		}
		next = &workers[i]
		break
	}
	var workerID *string
	var exp *time.Time
	if next != nil {
		workerID = &next.UserID
		e := time.Now().UTC().Add(30 * time.Minute)
		exp = &e
	}
	_, _ = a.pg.Exec(ctx, `UPDATE assignments SET worker_id=$1, offer_expires_at=$2, offer_rank=offer_rank+1 WHERE assignment_id::text=$3`, workerID, exp, ar.AssignmentID)
	if next != nil {
		return next.UserID
	}
	return ""
}

func roleForKind(kind string) string {
	switch kind {
	case "collection":
		return "collection_professional"
	case "transport":
		return "delivery_partner"
	case "node":
		return "node_handler"
	case "laboratory":
		return "laboratory_team"
	}
	return ""
}

// handleCollectAndSeal implements POST /api/collect-and-seal-sample (collection_professional).
func (a *App) handleCollectAndSeal(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		writeError(w, errCode(405, "method_not_allowed", "POST required"))
		return
	}
	u := currentUser(r)
	if e := requireRole(u, "collection_professional"); e != nil {
		writeError(w, e)
		return
	}
	var req struct {
		SampleID              string  `json:"sampleId"`
		AssignmentID          string  `json:"assignmentId"`
		CollectedAt           string  `json:"collectedAt"`
		ContainerType         string  `json:"containerType"`
		ObservedTemperatureC   float64 `json:"observedTemperatureC"`
		IdempotencyKey        string  `json:"idempotencyKey"`
	}
	if err := decodeJSON(r, &req); err != nil {
		writeError(w, errInvalidJSON)
		return
	}
	ar, e := loadAssignment(r.Context(), a.pg, req.AssignmentID)
	if e != nil {
		writeError(w, e)
		return
	}
	if ar.WorkerID == nil || *ar.WorkerID != u.UserID || ar.Kind != "collection" {
		writeError(w, errForbidden)
		return
	}
	if ar.Status != "accepted" && ar.Status != "in_progress" {
		writeError(w, errCode(409, "invalid_state", "assignment not accepted"))
		return
	}
	if ar.SampleID == nil {
		writeError(w, errNotFound)
		return
	}
	sampleID := *ar.SampleID
	var lat, lng float64
	var tmin, tmax float64
	var container string
	_ = a.pg.QueryRow(r.Context(), `SELECT latest_latitude, latest_longitude, temperature_min_c, temperature_max_c, container_type FROM samples WHERE sample_id::text=$1`, sampleID).Scan(&lat, &lng, &tmin, &tmax, &container)
	compliant := req.ObservedTemperatureC >= tmin && req.ObservedTemperatureC <= tmax
	ct := req.ContainerType
	if ct == "" {
		ct = container
	}
	_, err := a.pg.Exec(r.Context(), `UPDATE samples SET sealed=true, sealed_at=now(), status='collected', current_holder_id=$1, container_type=$2 WHERE sample_id::text=$3`,
		u.UserID, ct, sampleID)
	if err != nil {
		writeError(w, errConflict)
		return
	}
	if !compliant {
		_, _ = a.pg.Exec(r.Context(), `UPDATE samples SET exception=$1 WHERE sample_id::text=$2`, toJSONB(map[string]any{"reason": "temperature_out_of_range", "category": "handling", "observedTemperatureC": req.ObservedTemperatureC}), sampleID)
		_, _ = a.pg.Exec(r.Context(), `INSERT INTO exceptions (exception_id, sample_id, reason, category, observed_at) VALUES ($1,$2,'temperature_out_of_range','handling',now())`, uuidStr(), sampleID)
	}
	_, _ = a.pg.Exec(r.Context(), `UPDATE assignments SET status='completed' WHERE assignment_id::text=$1`, req.AssignmentID)
	// Record a checkpoint for the collection.
	_, _ = a.pg.Exec(r.Context(), `INSERT INTO checkpoints (checkpoint_id, sample_id, assignment_id, container_type, observed_temperature_c, compliant, recorded_at) VALUES ($1,$2,$3,$4,$5,$6,now())`,
		uuidStr(), sampleID, req.AssignmentID, ct, req.ObservedTemperatureC, compliant)
	a.audit(r.Context(), u, "collect_and_seal_sample", "sample", sampleID, true, map[string]any{"containerType": ct, "compliant": compliant})
	a.emitRealtime(r.Context(), "sample.sealed", "sample", sampleID, map[string]any{"workerId": u.UserID})
	var sealedAt string
	_ = a.pg.QueryRow(r.Context(), `SELECT sealed_at::text FROM samples WHERE sample_id::text=$1`, sampleID).Scan(&sealedAt)
	writeData(w, 201, map[string]any{
		"sampleId":            sampleID,
		"status":              "collected",
		"currentHolderId":     u.UserID,
		"sealedAt":            sealedAt,
		"handlingCompliant":   compliant,
	})
}

// handleInitiateHandoff implements POST /api/initiate-handoff.
func (a *App) handleInitiateHandoff(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		writeError(w, errCode(405, "method_not_allowed", "POST required"))
		return
	}
	u := currentUser(r)
	if e := requireRole(u, workerRoles()...); e != nil {
		writeError(w, e)
		return
	}
	var req struct {
		SampleID       string `json:"sampleId"`
		FromAssignmentID string `json:"fromAssignmentId"`
		ToAssignmentID string `json:"toAssignmentId"`
		ReceiverID     string `json:"receiverId"`
		InitiatedAt    string `json:"initiatedAt"`
		IdempotencyKey string `json:"idempotencyKey"`
	}
	if err := decodeJSON(r, &req); err != nil {
		writeError(w, errInvalidJSON)
		return
	}
	ar, e := loadAssignment(r.Context(), a.pg, req.FromAssignmentID)
	if e != nil {
		writeError(w, e)
		return
	}
	if ar.WorkerID == nil || *ar.WorkerID != u.UserID {
		writeError(w, errForbidden)
		return
	}
	// Determine the next assignment if not provided.
	toAssignID := req.ToAssignmentID
	if toAssignID == "" {
		_ = a.pg.QueryRow(r.Context(), `SELECT assignment_id::text FROM assignments WHERE journey_id::text=$1 AND sequence > $2 AND status NOT IN ('completed','cancelled','expired') ORDER BY sequence LIMIT 1`, ar.JourneyID, ar.Sequence).Scan(&toAssignID)
	}
	receiver := req.ReceiverID
	if receiver == "" && toAssignID != "" {
		_ = a.pg.QueryRow(r.Context(), `SELECT COALESCE(worker_id::text,'') FROM assignments WHERE assignment_id::text=$1`, toAssignID).Scan(&receiver)
	}
	hid := uuidStr()
	_, err := a.pg.Exec(r.Context(), `INSERT INTO handoffs (handoff_id, sample_id, from_assignment_id, to_assignment_id, sender_id, receiver_id, sender_confirmed, status, initiated_at)
		VALUES ($1,$2,$3,$4,$5,$6,true,'pending',now())`,
		hid, req.SampleID, req.FromAssignmentID, nilIfEmpty(toAssignID), u.UserID, nilIfEmpty(receiver))
	if err != nil {
		writeError(w, errConflict)
		return
	}
	a.audit(r.Context(), u, "initiate_handoff", "handoff", hid, true, map[string]any{"sampleId": req.SampleID})
	// currentHolder remains the sender until receiver confirms.
	writeData(w, 201, map[string]any{
		"handoffId":       hid,
		"senderId":        u.UserID,
		"receiverId":      receiver,
		"currentHolderId": u.UserID,
		"status":          "pending",
	})
}

// handleConfirmHandoff implements POST /api/confirm-handoff.
func (a *App) handleConfirmHandoff(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		writeError(w, errCode(405, "method_not_allowed", "POST required"))
		return
	}
	u := currentUser(r)
	if e := requireRole(u, workerRoles()...); e != nil {
		writeError(w, e)
		return
	}
	var req struct {
		HandoffID       string `json:"handoffId"`
		ConfirmationSide string `json:"confirmationSide"`
		ConfirmedAt     string `json:"confirmedAt"`
		IdempotencyKey  string `json:"idempotencyKey"`
	}
	if err := decodeJSON(r, &req); err != nil {
		writeError(w, errInvalidJSON)
		return
	}
	var sampleID, toAssignID, senderID, receiverID string
	var senderConf bool
	err := a.pg.QueryRow(r.Context(), `SELECT sample_id::text, to_assignment_id::text, sender_id::text, COALESCE(receiver_id::text,''), sender_confirmed FROM handoffs WHERE handoff_id::text=$1`, req.HandoffID).
		Scan(&sampleID, &toAssignID, &senderID, &receiverID, &senderConf)
	if err != nil {
		writeError(w, errNotFound)
		return
	}
	side := req.ConfirmationSide
	if side == "" {
		if u.UserID == senderID {
			side = "sender"
		} else {
			side = "receiver"
		}
	}
	if side == "sender" {
		if u.UserID != senderID {
			writeError(w, errCode(403, "not_sender", "only the sender can confirm as sender"))
			return
		}
		_, _ = a.pg.Exec(r.Context(), `UPDATE handoffs SET sender_confirmed=true WHERE handoff_id::text=$1`, req.HandoffID)
	} else {
		_, _ = a.pg.Exec(r.Context(), `UPDATE handoffs SET receiver_confirmed=true, receiver_id=$1 WHERE handoff_id::text=$2`, u.UserID, req.HandoffID)
	}
	var s, rc bool
	_ = a.pg.QueryRow(r.Context(), `SELECT sender_confirmed, receiver_confirmed FROM handoffs WHERE handoff_id::text=$1`, req.HandoffID).Scan(&s, &rc)
	newHolder := senderID
	if s && rc {
		_, _ = a.pg.Exec(r.Context(), `UPDATE handoffs SET status='completed', completed_at=now() WHERE handoff_id::text=$1`, req.HandoffID)
		var holder string
		_ = a.pg.QueryRow(r.Context(), `SELECT COALESCE(worker_id::text,'') FROM assignments WHERE assignment_id::text=$1`, toAssignID).Scan(&holder)
		if holder == "" {
			holder = u.UserID
		}
		_, _ = a.pg.Exec(r.Context(), `UPDATE samples SET current_holder_id=$1 WHERE sample_id::text=$2`, holder, sampleID)
		_, _ = a.pg.Exec(r.Context(), `UPDATE assignments SET status='completed' WHERE (SELECT from_assignment_id FROM handoffs WHERE handoff_id::text=$1)::text=assignment_id::text`, req.HandoffID)
		if toAssignID != "" {
			_, _ = a.pg.Exec(r.Context(), `UPDATE assignments SET status='in_progress' WHERE assignment_id::text=$1`, toAssignID)
		}
		var kind string
		_ = a.pg.QueryRow(r.Context(), `SELECT kind FROM assignments WHERE assignment_id::text=$1`, toAssignID).Scan(&kind)
		if kind == "laboratory" {
			_, _ = a.pg.Exec(r.Context(), `UPDATE samples SET status='at_lab' WHERE sample_id::text=$1`, sampleID)
		} else {
			_, _ = a.pg.Exec(r.Context(), `UPDATE samples SET status='in_transit' WHERE sample_id::text=$1`, sampleID)
		}
		newHolder = holder
		a.emitRealtime(r.Context(), "handoff.completed", "sample", sampleID, map[string]any{"holder": holder})
	}
	a.audit(r.Context(), u, "confirm_handoff", "handoff", req.HandoffID, true, map[string]any{"side": side})
	writeData(w, 201, map[string]any{
		"handoffId":         req.HandoffID,
		"status":            handoffStatus(s, rc),
		"senderConfirmed":   s,
		"receiverConfirmed": rc,
		"currentHolderId":   newHolder,
	})
}

func handoffStatus(s, rc bool) string {
	if s && rc {
		return "completed"
	}
	return "pending"
}

