		if t, perr := parseTime(req.DeclinedAt, "invalid_time"); perr == nil {
			declinedAt = rfc(t)
		}
	}
	a.audit(r.Context(), u, "decline_assignment", "assignment", req.AssignmentID, true, map[string]any{"reason": req.Reason})
	out := map[string]any{
		"assignmentId": req.AssignmentID,
		"status":       "offered",
		"declinedBy":   u.UserID,
		"declinedAt":   declinedAt,
	}
	if nextWorker != "" {
		out["reofferedTo"] = nextWorker
	}
	writeData(w, 201, out)
