		_ = a.pg.QueryRow(r.Context(), `SELECT COALESCE(MAX(sequence),0)+1 FROM worker_locations WHERE assignment_id::text=$1`, req.AssignmentID).Scan(&seq)
	}
	recordedAt := nowRFC()
	if req.RecordedAt != "" {
		if t, perr := parseTime(req.RecordedAt, "invalid_time"); perr == nil {
			recordedAt = rfc(t)
		}
	}
	_, _ = a.pg.Exec(r.Context(), `INSERT INTO worker_locations (assignment_id, sequence, latitude, longitude, recorded_at) VALUES ($1,$2,$3,$4,now())`,
		req.AssignmentID, seq, req.Coordinate.Latitude, req.Coordinate.Longitude)
	_, _ = a.pg.Exec(r.Context(), `UPDATE samples SET latest_latitude=$1, latest_longitude=$2, location_recorded_at=now() WHERE current_holder_id::text=$3`, req.Coordinate.Latitude, req.Coordinate.Longitude, u.UserID)
