	_, _ = a.pg.Exec(r.Context(), `INSERT INTO exceptions (exception_id, sample_id, reason, category, observed_at) VALUES ($1,$2,$3,'laboratory',now())`, uuidStr(), req.SampleID, req.Reason)
	a.audit(r.Context(), u, "record_laboratory_exception", "sample", req.SampleID, true, map[string]any{"reason": req.Reason})
