// handleSetWorkerAvailability implements POST /api/set-worker-availability.
func (a *App) handleSetWorkerAvailability(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		writeError(w, errCode(405, "method_not_allowed", "POST required"))
		return
	}
	u := currentUser(r)
	var req struct {
		WorkerID string `json:"workerId"`
		Available bool  `json:"available"`
		CapacityUnits int `json:"capacityUnits"`
	}
	if err := decodeJSON(r, &req); err != nil {
		writeError(w, errInvalidJSON)
		return
	}
	target := req.WorkerID
	if target == "" {
		target = u.UserID
	}
	if u.ActiveRole != "administrator" && u.ActiveRole != "dispatcher" && target != u.UserID {
		writeError(w, errForbidden)
		return
	}
	_, _ = a.pg.Exec(r.Context(), `INSERT INTO worker_profiles (worker_id, available, capacity_units, updated_at) VALUES ($1,$2,$3,now())
		ON CONFLICT (worker_id) DO UPDATE SET available=EXCLUDED.available, capacity_units=COALESCE(NULLIF(EXCLUDED.capacity_units,0), worker_profiles.capacity_units), updated_at=now()`,
		target, req.Available, req.CapacityUnits)
	a.audit(r.Context(), u, "set_worker_availability", "user", target, true, map[string]any{"available": req.Available})
	writeData(w, 201, map[string]any{
		"workerId":      target,
		"available":     req.Available,
		"capacityUnits": req.CapacityUnits,
	})
}

