[?2004lfunc auditSearch(ctx context.Context, a *App, q auditQuery) (auditSearchResult, error) {
	filter := bson.M{}
	if q.ActorID != "" {
		filter["actorId"] = q.ActorID
	}
	if q.EntityType != "" {
		filter["entityType"] = q.EntityType
	}
	if q.EntityID != "" {
		filter["entityId"] = q.EntityID
	}
	if q.Action != "" {
		filter["action"] = q.Action
	}
	if q.Role != "" {
		filter["role"] = q.Role
	}
	if q.Success != nil {
		filter["success"] = *q.Success
	}
	if !q.FromTime.IsZero() || !q.ToTime.IsZero() {
		tf := bson.M{}
		if !q.FromTime.IsZero() {
			tf["$gte"] = q.FromTime
		}
		if !q.ToTime.IsZero() {
			tf["$lte"] = q.ToTime
		}
		filter["occurredAt"] = tf
	}
	if q.Query != "" {
		filter["$or"] = bson.A{
			bson.M{"action": bson.M{"$regex": q.Query, "$options": "i"}},
			bson.M{"entityType": bson.M{"$regex": q.Query, "$options": "i"}},
			bson.M{"entityId": bson.M{"$regex": q.Query, "$options": "i"}},
		}
	}
	total, err := a.mdb.Collection("audit_events").CountDocuments(ctx, filter)
	if err != nil {
		return auditSearchResult{}, err
	}
	order := 1
	if q.Order == "newest_first" {
		order = -1
	}
	opts := options.Find().SetSort(bson.D{{Key: "occurredAt", Value: order}, {Key: "_id", Value: order}}).
		SetSkip(int64(q.Offset)).SetLimit(int64(q.Limit))
	cur, err := a.mdb.Collection("audit_events").Find(ctx, filter, opts)
	if err != nil {
		return auditSearchResult{}, err
	}
	defer cur.Close(ctx)
	var out []bson.M
	if err := cur.All(ctx, &out); err != nil {
		return auditSearchResult{}, err
	}
	entries := make([]map[string]any, 0, len(out))
	for _, d := range out {
		entries = append(entries, normalizeAudit(d))
	}
	hasMore := q.Offset+len(entries) < int(total)
	res := auditSearchResult{
		Entries: entries,
		Total:   int(total),
		Returned: len(entries),
		Offset:  q.Offset,
		Limit:   q.Limit,
		Order:   q.Order,
		HasMore: hasMore,
	}
	if q.Offset+len(entries) < int(total) {
		no := q.Offset + len(entries)
		res.NextOffset = &no
	}
	return res, nil
}

func normalizeAudit(d bson.M) map[string]any {
	oid := getStr(d, "_id")
	aid := getStr(d, "auditId")
	if aid == "" {
		aid = oid
	}
	ev := getInt(d, "eventId")
	return map[string]any{
		"eventId":    ev,
		"auditId":    aid,
		"audit_id":   aid,
		"actorId":    getStr(d, "actorId"),
		"actor_id":   getStr(d, "actorId"),
		"role":        getStr(d, "role"),
		"actorRole":   getStr(d, "role"),
		"action":      getStr(d, "action"),
		"entityType": getStr(d, "entityType"),
		"entity_type": getStr(d, "entityType"),
		"entityId":   getStr(d, "entityId"),
		"entity_id":  getStr(d, "entityId"),
		"success":    getBool(d, "success"),
		"occurredAt": getTime(d, "occurredAt"),
		"occurred_at": getTime(d, "occurredAt"),
		"details":    d["details"],
	}
}

func getStr(d bson.M, k string) string {
	if v, ok := d[k]; ok {
		switch t := v.(type) {
		case string:
			return t
		}
	}
	return ""
}

func getBool(d bson.M, k string) bool {
	if v, ok := d[k]; ok {
		if b, ok := v.(bool); ok {
			return b
		}
	}
	return false
}

func getInt(d bson.M, k string) int64 {
	if v, ok := d[k]; ok {
		switch t := v.(type) {
		case int:
			return int64(t)
		case int32:
			return int64(t)
		case int64:
			return t
		case float64:
			return int64(t)
		}
	}
	return 0
}

func getTime(d bson.M, k string) string {
	if v, ok := d[k]; ok {
		switch t := v.(type) {
		case time.Time:
			return t.UTC().Format(time.RFC3339Nano)
		case string:
			return t
		}
	}
	return ""
}

type auditQuery struct {
	Query     string
	ActorID   string
	EntityType string
	EntityID  string
	Action    string
	Role      string
	Success   *bool
	FromTime  time.Time
	ToTime    time.Time
	Limit     int
	Offset    int
	Order     string
}

type auditSearchResult struct {
	Entries    []map[string]any `json:"entries"`
	Total      int              `json:"total"`
	Returned   int              `json:"returned"`
	Offset     int              `json:"offset"`
	Limit      int              `json:"limit"`
	Order      string           `json:"order"`
	HasMore    bool             `json:"hasMore"`
	NextOffset *int             `json:"nextOffset,omitempty"`
}[?2004h

