// sampleLifecycle builds the ordered status timeline for a sample.
func (a *App) sampleLifecycle(ctx context.Context, sampleID string) map[string]any {
	// Current sample state.
	var status, sealed string
	var holder *string
	var lat, lng *float64
	var locAt *string
	var exc []byte
	var stName, origin string
	_ = a.pg.QueryRow(ctx, `SELECT s.status, CASE WHEN s.sealed THEN 'sealed' ELSE 'not_sealed' END, s.current_holder_id::text, s.latest_latitude, s.latest_longitude, s.location_recorded_at::text, s.exception, st.name, s.origin_type
		FROM samples s JOIN sample_types st ON st.sample_type_id=s.sample_type_id WHERE s.sample_id::text=$1`, sampleID).
		Scan(&status, &sealed, &holder, &lat, &lng, &locAt, &exc, &stName, &origin)

	timeline := []map[string]any{}
	// Audit records (MongoDB) describe the chronological history.
	res, _ := auditSearch(ctx, a, auditQuery{EntityType: "sample", EntityID: sampleID, Order: "oldest_first", Limit: 500})
	for _, e := range res.Entries {
		timeline = append(timeline, map[string]any{
			"at":      e["occurredAt"],
			"action":  e["action"],
			"outcome": e["success"],
			"actorId": e["actorId"],
		})
	}

	loc := map[string]any{}
	if lat != nil && lng != nil {
		loc["latitude"] = *lat
		loc["longitude"] = *lng
		loc["recordedAt"] = strPtr(locAt)
		stale := false
		if locAt != nil && *locAt != "" {
			if t, err := time.Parse(time.RFC3339Nano, *locAt); err == nil {
				stale = time.Since(t).Minutes() > 30
			}
		}
		loc["stale"] = stale
	}

	out := map[string]any{
		"sampleId":         sampleID,
		"sampleType":       stName,
		"status":           status,
		"sealed":           sealed == "sealed",
		"originType":       origin,
		"currentHolderId":  strPtr(holder),
		"location":         loc,
		"timeline":         timeline,
	}
	if len(exc) > 0 && string(exc) != "null" {
		out["exception"] = jsonRaw(exc)
	}
	return out
}

