package main

import (
	"context"
	"encoding/json"
	"time"

	"github.com/jackc/pgx/v5"
)

// pgxRows aliases pgx.Rows for handler scan helpers.
type pgxRows = pgx.Rows

// jsonRaw returns a json.RawMessage for embedding a raw JSON column value.
func jsonRaw(b []byte) json.RawMessage {
	if len(b) == 0 {
		return nil
	}
	return json.RawMessage(b)
}

// canViewSample authorizes a user to view a sample's lifecycle/details.
func (a *App) canViewSample(ctx context.Context, u *AuthUser, sampleID string) *apiError {
	if u == nil {
		return errUnauthorized
	}
	if u.ActiveRole == "administrator" || u.ActiveRole == "dispatcher" {
		return nil
	}
	if u.ActiveRole == "requester" {
		var owner string
		_ = a.pg.QueryRow(ctx, `SELECT requester_id::text FROM samples WHERE sample_id::text=$1`, sampleID).Scan(&owner)
		if owner != u.UserID {
			return errForbidden
		}
		return nil
	}
	// Workers may view samples they are responsible for (current holder or assigned).
	var holder, assignWorker string
	_ = a.pg.QueryRow(ctx, `SELECT COALESCE(current_holder_id::text,''), COALESCE((SELECT a.worker_id::text FROM assignments a WHERE a.sample_id::text=s.sample_id::text AND a.worker_id::text=$2 ORDER BY a.created_at DESC LIMIT 1),'') FROM samples s WHERE s.sample_id::text=$1`, sampleID, u.UserID).
		Scan(&holder, &assignWorker)
	if holder != u.UserID && assignWorker != u.UserID {
		return errForbidden
	}
	return nil
}

// sampleLifecycle builds the ordered status timeline for a sample.
func (a *App) sampleLifecycle(ctx context.Context, sampleID string) map[string]any {
	var status string
	var sealed bool
	var holder *string
	var lat, lng *float64
	var locAt *string
	var exc []byte
	var activeJourneyID *string
	var recvLabID *string
	_ = a.pg.QueryRow(ctx, `SELECT s.status, s.sealed, s.current_holder_id::text, s.latest_latitude, s.latest_longitude, s.location_recorded_at::text, s.exception, s.active_journey_id::text, s.received_laboratory_id::text
		FROM samples s WHERE s.sample_id::text=$1`, sampleID).
		Scan(&status, &sealed, &holder, &lat, &lng, &locAt, &exc, &activeJourneyID, &recvLabID)

	timeline := []map[string]any{}
	res, _ := auditSearch(ctx, a, auditQuery{EntityType: "sample", EntityID: sampleID, Order: "oldest_first", Limit: 500})
	for _, e := range res.Entries {
		timeline = append(timeline, map[string]any{
			"eventId":    e["eventId"],
			"action":     e["action"],
			"actorId":    e["actorId"],
			"role":       e["role"],
			"entityType": e["entityType"],
			"entityId":   e["entityId"],
			"success":    e["success"],
			"occurredAt": e["occurredAt"],
			"details":    e["details"],
		})
	}

	locStale := true
	var latestLocation map[string]any
	if lat != nil && lng != nil {
		latestLocation = map[string]any{"latitude": *lat, "longitude": *lng}
		locStale = false
		if locAt != nil && *locAt != "" {
			if t, err := time.Parse(time.RFC3339Nano, *locAt); err == nil {
				locStale = time.Since(t).Minutes() > 30
			}
		}
	}

	completedLegs := []string{}
	activePlans := []string{}
	if activeJourneyID != nil {
		rows, _ := a.pg.Query(ctx, `SELECT assignment_id::text FROM assignments WHERE journey_id::text=$1 AND status='completed' ORDER BY sequence`, *activeJourneyID)
		for rows.Next() {
			var id string
			_ = rows.Scan(&id)
			completedLegs = append(completedLegs, id)
		}
		rows.Close()
		rp, _ := a.pg.Query(ctx, `SELECT replacement_plan_id::text FROM replacement_plans WHERE journey_id::text=$1 AND status='active'`, *activeJourneyID)
		for rp.Next() {
			var id string
			_ = rp.Scan(&id)
			activePlans = append(activePlans, id)
		}
		rp.Close()
	}

	var pendingHandoffID *string
	_ = a.pg.QueryRow(ctx, `SELECT handoff_id::text FROM handoffs WHERE sample_id::text=$1 AND status='pending' ORDER BY initiated_at DESC LIMIT 1`, sampleID).Scan(&pendingHandoffID)
	pendingHandoff := map[string]any{}
	if pendingHandoffID != nil {
		_ = a.pg.QueryRow(ctx, `SELECT sender_id::text, receiver_id::text, status FROM handoffs WHERE handoff_id::text=$1`, *pendingHandoffID).Scan(&pendingHandoff["senderId"], &pendingHandoff["receiverId"], &pendingHandoff["status"])
	}

	out := map[string]any{
		"sampleId":                 sampleID,
		"status":                   status,
		"sealed":                   sealed,
		"completedLegIds":           completedLegs,
		"activeReplacementPlanIds":  activePlans,
		"timeline":                 timeline,
		"locationStale":            locStale,
	}
	if activeJourneyID != nil {
		out["activeJourneyId"] = *activeJourneyID
	}
	if holder != nil {
		out["currentHolderId"] = *holder
	}
	if recvLabID != nil {
		out["receivedLaboratoryId"] = *recvLabID
	}
	if latestLocation != nil {
		out["latestLocation"] = latestLocation
	}
	if locAt != nil {
		out["locationRecordedAt"] = *locAt
	}
	if pendingHandoffID != nil {
		out["pendingHandoffId"] = *pendingHandoffID
		out["pendingHandoff"] = pendingHandoff
	}
	if len(exc) > 0 && string(exc) != "null" {
		out["exception"] = jsonRaw(exc)
	}
	return out
}

