// handleRecordWorkerLocation implements POST /api/record-worker-location.
func (a *App) handleRecordWorkerLocation(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		writeError(w, errCode(405, "method_not_allowed", "POST required"))
		return
	}
	u := currentUser(r)
	if e := requireRole(u, workerRoles()...); e != nil {
		writeError(w, e)
		return
	}
	var req struct {
		AssignmentID string  `json:"assignmentId"`
		Coordinate   coordIn `json:"coordinate"`
		Sequence     int     `json:"sequence"`
		RecordedAt   string  `json:"recordedAt"`
	}
	if err := decodeJSON(r, &req); err != nil {
		writeError(w, errInvalidJSON)
		return
	}
	// Verify the assignment belongs to the worker (if provided).
	if req.AssignmentID != "" {
		ar, e := loadAssignment(r.Context(), a.pg, req.AssignmentID)
		if e != nil {
			writeError(w, e)
			return
		}
		if ar.WorkerID == nil || *ar.WorkerID != u.UserID {
			writeError(w, errForbidden)
			return
		}
	}
	seq := req.Sequence
	if seq == 0 {
		_ = a.pg.QueryRow(r.Context(), `SELECT COALESCE(MAX(sequence),0)+1 FROM worker_locations WHERE assignment_id::text=$1`, req.AssignmentID).Scan(&seq)
	}
	recordedAt := nowRFC()
	if req.RecordedAt != "" {
		if t, perr := parseTime(req.RecordedAt, "invalid_time"); perr == nil {
			recordedAt = rfc(t)
		}
	}
	_, _ = a.pg.Exec(r.Context(), `INSERT INTO worker_locations (assignment_id, sequence, latitude, longitude, recorded_at) VALUES ($1,$2,$3,$4,now())`,
		req.AssignmentID, seq, req.Coordinate.Latitude, req.Coordinate.Longitude)
	_, _ = a.pg.Exec(r.Context(), `UPDATE samples SET latest_latitude=$1, latest_longitude=$2, location_recorded_at=now() WHERE current_holder_id::text=$3`, req.Coordinate.Latitude, req.Coordinate.Longitude, u.UserID)
	a.emitRealtime(r.Context(), "worker.location", "user", u.UserID, map[string]any{"latitude": req.Coordinate.Latitude, "longitude": req.Coordinate.Longitude})
	writeData(w, 201, map[string]any{
		"assignmentId": req.AssignmentID,
		"coordinate": map[string]any{
			"latitude":  req.Coordinate.Latitude,
			"longitude": req.Coordinate.Longitude,
		},
		"sequence":   seq,
		"recordedAt": recordedAt,
	})
}

// handleRecordHandlingCheckpoint implements POST /api/record-handling-checkpoint.
func (a *App) handleRecordHandlingCheckpoint(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		writeError(w, errCode(405, "method_not_allowed", "POST required"))
		return
	}
	u := currentUser(r)
	if e := requireRole(u, workerRoles()...); e != nil {
		writeError(w, e)
		return
	}
	var req struct {
		SampleID              string  `json:"sampleId"`
		AssignmentID          string  `json:"assignmentId"`
		LocationID            string  `json:"locationId"`
		ContainerType         string  `json:"containerType"`
		ObservedTemperatureC  float64 `json:"observedTemperatureC"`
		RecordedAt            string  `json:"recordedAt"`
		IdempotencyKey        string  `json:"idempotencyKey"`
	}
	if err := decodeJSON(r, &req); err != nil {
		writeError(w, errInvalidJSON)
		return
	}
	var tmin, tmax float64
	var container string
	var status string
	err := a.pg.QueryRow(r.Context(), `SELECT temperature_min_c, temperature_max_c, container_type, status FROM samples WHERE sample_id::text=$1`, req.SampleID).Scan(&tmin, &tmax, &container, &status)
	if err != nil {
		writeError(w, errNotFound)
		return
	}
	tempCompliant := req.ObservedTemperatureC >= tmin && req.ObservedTemperatureC <= tmax
	containerCompliant := req.ContainerType == "" || req.ContainerType == container
	compliant := tempCompliant && containerCompliant
	cid := uuidStr()
	_, _ = a.pg.Exec(r.Context(), `INSERT INTO checkpoints (checkpoint_id, sample_id, assignment_id, location_id, container_type, observed_temperature_c, compliant, recorded_at) VALUES ($1,$2,$3,$4,$5,$6,$7,now())`,
		cid, req.SampleID, nilIfEmpty(req.AssignmentID), nilIfEmpty(req.LocationID), req.ContainerType, req.ObservedTemperatureC, compliant)
	if !compliant {
		reason := "temperature_out_of_range"
		if !tempCompliant && !containerCompliant {
			reason = "handling_non_compliant"
		} else if !containerCompliant {
			reason = "container_mismatch"
		}
		_, _ = a.pg.Exec(r.Context(), `UPDATE samples SET exception=$1 WHERE sample_id::text=$2`, toJSONB(map[string]any{"reason": reason, "category": "handling", "observedTemperatureC": req.ObservedTemperatureC}), req.SampleID)
		_, _ = a.pg.Exec(r.Context(), `INSERT INTO exceptions (exception_id, sample_id, reason, category, observed_at) VALUES ($1,$2,$3,'handling',now())`, uuidStr(), req.SampleID, reason)
		status = "exception"
		_, _ = a.pg.Exec(r.Context(), `UPDATE samples SET status='exception' WHERE sample_id::text=$1`, req.SampleID)
		a.emitRealtime(r.Context(), "sample.exception", "sample", req.SampleID, map[string]any{"reason": reason})
	}
	a.audit(r.Context(), u, "record_handling_checkpoint", "sample", req.SampleID, true, map[string]any{"compliant": compliant})
	writeData(w, 201, map[string]any{
		"checkpointId":  cid,
		"sampleId":      req.SampleID,
		"compliant":     compliant,
		"sampleStatus":  status,
	})
}

// handleConfirmLaboratoryReceipt implements POST /api/confirm-laboratory-receipt (laboratory_team).
func (a *App) handleConfirmLaboratoryReceipt(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		writeError(w, errCode(405, "method_not_allowed", "POST required"))
		return
	}
	u := currentUser(r)
	if e := requireRole(u, "laboratory_team"); e != nil {
		writeError(w, e)
		return
	}
	var req struct {
		SampleID      string `json:"sampleId"`
		LaboratoryID  string `json:"laboratoryId"`
		ReceivedAt    string `json:"receivedAt"`
		IdempotencyKey string `json:"idempotencyKey"`
	}
	if err := decodeJSON(r, &req); err != nil {
		writeError(w, errInvalidJSON)
		return
	}
	labID := req.LaboratoryID
	if labID == "" {
		var aLoc *string
		_ = a.pg.QueryRow(r.Context(), `SELECT assigned_location_id::text FROM users WHERE user_id::text=$1`, u.UserID).Scan(&aLoc)
		labID = strPtr(aLoc)
	}
	_, err := a.pg.Exec(r.Context(), `UPDATE samples SET status='received', received_laboratory_id=$1, current_holder_id=NULL WHERE sample_id::text=$2`, labID, req.SampleID)
	if err != nil {
		writeError(w, errConflict)
		return
	}
	_, _ = a.pg.Exec(r.Context(), `UPDATE journeys SET status='completed' WHERE journey_id=(SELECT active_journey_id FROM samples WHERE sample_id::text=$1)`, req.SampleID)
	_, _ = a.pg.Exec(r.Context(), `UPDATE assignments SET status='completed' WHERE journey_id=(SELECT active_journey_id FROM samples WHERE sample_id::text=$1) AND status NOT IN ('completed','cancelled','expired')`, req.SampleID)
	receivedAt := nowRFC()
	if req.ReceivedAt != "" {
		if t, perr := parseTime(req.ReceivedAt, "invalid_time"); perr == nil {
			receivedAt = rfc(t)
		}
	}
	a.audit(r.Context(), u, "confirm_laboratory_receipt", "sample", req.SampleID, true, map[string]any{"laboratoryId": labID})
	a.emitRealtime(r.Context(), "sample.received", "sample", req.SampleID, map[string]any{"laboratoryId": labID})
	writeData(w, 201, map[string]any{
		"sampleId":     req.SampleID,
		"laboratoryId": labID,
		"status":       "received",
		"receivedAt":   receivedAt,
	})
}

