		OriginNodeID         string  `json:"originNodeId"`
		SampleTypeID         string  `json:"sampleTypeId"`
		RequestedAt          string  `json:"requestedAt"`
		DeliveryDeadline     string  `json:"deliveryDeadline"`
		EarliestCollectionAt string  `json:"earliestCollectionAt"`
		LatestCollectionAt   string  `json:"latestCollectionAt"`
	}
	if err := decodeJSON(r, &req); err != nil {
		writeError(w, errInvalidJSON)
		return
	}
	if req.SampleTypeID == "" {
		writeError(w, errCode(400, "invalid_sample_type", "sampleTypeId is required"))
		return
	}
	deadline, e := parseTime(req.DeliveryDeadline, "invalid_deadline")
	if e != nil {
		writeError(w, e)
		return
	}
	var earliest, latest time.Time
	if req.EarliestCollectionAt != "" {
		earliest, e = parseTime(req.EarliestCollectionAt, "invalid_collection_window")
		if e != nil {
			writeError(w, e)
			return
		}
	}
	if req.LatestCollectionAt != "" {
		latest, e = parseTime(req.LatestCollectionAt, "invalid_collection_window")
		if e != nil {
			writeError(w, e)
			return
		}
	}
	if !earliest.IsZero() && !latest.IsZero() && latest.Before(earliest) {
		writeError(w, errCode(400, "invalid_collection_window", "latest collection before earliest"))
		return
	}
	if !deadline.IsZero() && !latest.IsZero() && deadline.Before(latest) {
		writeError(w, errCode(400, "invalid_deadline", "deadline before latest collection"))
		return
	}
	st, err := loadSampleType(r.Context(), a.pg, req.SampleTypeID)
	if err != nil {
		writeError(w, errCode(400, "invalid_sample_type", "unknown sample type"))
		return
	}
	requestedAt := time.Now().UTC()
	if req.RequestedAt != "" {
		if t, perr := parseTime(req.RequestedAt, "invalid_time"); perr == nil {
			requestedAt = t
		}
	}
	in := serviceabilityInput{
		OriginType:      req.OriginType,
		OriginLat:       req.Origin.Latitude,
		OriginLng:       req.Origin.Longitude,
		OriginNodeID:    req.OriginNodeID,
		SampleTypeID:    req.SampleTypeID,
		RequiresCooled:  st.RequiresCooled,
		RequestedAt:     requestedAt,
		Deadline:        deadline,
		EarliestCollect: earliest,
		LatestCollect:   latest,
	}
	res := a.checkServiceability(r.Context(), in)
	// Dry run: write nothing but an audit trail marker.
	a.audit(r.Context(), u, "check_serviceability", "serviceability", req.SampleTypeID, res.Serviceable, map[string]any{"reason": res.Reason})
	out := map[string]any{
		"serviceable":          res.Serviceable,
		"reason":               res.Reason,
		"serviceabilityVersion": res.Version,
