func (a *App) readSampleState(ctx context.Context, sampleID string) map[string]any {
	var status string
	var sealed bool
	var holder *string
	var lat, lng *float64
	var locAt *string
	var exc []byte
	var stName, origin, jID string
	var jStatus string
	var targetLab *string
	_ = a.pg.QueryRow(ctx, `SELECT s.status, s.sealed, s.current_holder_id::text, s.latest_latitude, s.latest_longitude, s.location_recorded_at::text, s.exception, st.name, s.origin_type, COALESCE(s.active_journey_id::text,''), COALESCE((SELECT j.status FROM journeys j WHERE j.journey_id=s.active_journey_id),''), s.target_laboratory_id::text
		FROM samples s JOIN sample_types st ON st.sample_type_id=s.sample_type_id WHERE s.sample_id::text=$1`, sampleID).
		Scan(&status, &sealed, &holder, &lat, &lng, &locAt, &exc, &stName, &origin, &jID, &jStatus, &targetLab)

	loc := map[string]any{}
	stale := false
	if lat != nil && lng != nil {
		loc["latitude"] = *lat
		loc["longitude"] = *lng
		if locAt != nil && *locAt != "" {
			loc["recordedAt"] = *locAt
			if t, err := time.Parse(time.RFC3339Nano, *locAt); err == nil {
				stale = time.Since(t).Minutes() > 30
			}
		}
	}
	loc["stale"] = stale

	out := map[string]any{
		"sampleId":        sampleID,
		"sampleType":      stName,
		"status":          status,
		"sealed":          sealed,
		"originType":      origin,
		"currentHolderId": strPtr(holder),
		"location":        loc,
		"journeyId":       jID,
		"journeyStatus":   jStatus,
		"targetLaboratoryId": strPtr(targetLab),
	}
	if len(exc) > 0 && string(exc) != "null" {
		out["exception"] = jsonRaw(exc)
	}
	return out
}

