package main

import (
	"context"
	"net/http"
	"time"
)

// handleReadSampleState implements GET /api/read-sample-state/{sampleId}.
func (a *App) handleReadSampleState(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodGet {
		writeError(w, errCode(405, "method_not_allowed", "GET required"))
		return
	}
	sampleID := pathTail(r, "/api/read-sample-state/")
	if sampleID == "" {
		writeError(w, errNotFound)
		return
	}
	u := currentUser(r)
	if e := a.canViewSample(r.Context(), u, sampleID); e != nil {
		writeError(w, e)
		return
	}
	state := a.readSampleState(r.Context(), sampleID)
	writeData(w, 200, state)
}

func (a *App) readSampleState(ctx context.Context, sampleID string) map[string]any {
	var status, origin, originType, sampleTypeID, containerType, requesterID, requestID string
	var requestedAt, deadline string
	var tempMin, tempMax float64
	var incompatible []string
	var sealed bool
	var holder *string
	var lat, lng *float64
	var locAt *string
	var exc []byte
	var activeJID *string
	var targetLab *string
	var reqLat, reqLng float64
	_ = a.pg.QueryRow(ctx, `SELECT s.status, s.origin_type, s.sample_type_id::text, s.container_type, s.temperature_min_c, s.temperature_max_c, s.requester_id::text, r.request_id::text, r.requested_at::text, r.delivery_deadline::text, r.origin_latitude, r.origin_longitude, r.incompatible, s.sealed, s.current_holder_id::text, s.latest_latitude, s.latest_longitude, s.location_recorded_at::text, s.exception, s.active_journey_id::text, s.target_laboratory_id::text
		FROM samples s JOIN requests r ON r.request_id=s.request_id WHERE s.sample_id::text=$1`, sampleID).
		Scan(&status, &originType, &sampleTypeID, &containerType, &tempMin, &tempMax, &requesterID, &requestID, &requestedAt, &deadline, &reqLat, &reqLng, &incompatible, &sealed, &holder, &lat, &lng, &locAt, &exc, &activeJID, &targetLab)
	if incompatible == nil {
		incompatible = []string{}
	}
	assignRows, _ := a.pg.Query(ctx, `SELECT assignment_id::text FROM assignments WHERE sample_id::text=$1 AND status NOT IN ('completed','cancelled','expired') ORDER BY sequence`, sampleID)
	activeAssigns := []string{}
	if assignRows != nil {
		for assignRows.Next() {
			var aid string
			_ = assignRows.Scan(&aid)
			activeAssigns = append(activeAssigns, aid)
		}
		assignRows.Close()
	}
	locStale := true
	var latestLocation map[string]any
	if lat != nil && lng != nil {
		latestLocation = map[string]any{"latitude": *lat, "longitude": *lng}
		locStale = true
		if locAt != nil && *locAt != "" {
			if t, err := time.Parse(time.RFC3339Nano, *locAt); err == nil {
				locStale = time.Since(t).Minutes() > 30
			}
		}
	}
	servStr := "serviceable"
	if len(exc) > 0 && string(exc) != "null" {
		servStr = "unserviceable"
	}
	out := map[string]any{
		"sampleId":                sampleID,
		"requestId":               requestID,
		"requesterId":             requesterID,
		"origin":                  map[string]any{"latitude": reqLat, "longitude": reqLng},
		"originType":              originType,
		"requestedAt":             requestedAt,
		"deliveryDeadline":        deadline,
		"sampleTypeId":            sampleTypeID,
		"containerType":           containerType,
		"temperatureMinC":         tempMin,
		"temperatureMaxC":         tempMax,
		"incompatibleSampleTypes": incompatible,
		"serviceability":          servStr,
		"activeAssignmentIds":     activeAssigns,
		"state": map[string]any{
			"status":           status,
			"sealed":           sealed,
			"currentHolderId":  strPtr(holder),
		},
		"timeline":         timelineFor(ctx, a, "sample", sampleID),
		"locationStale":    locStale,
	}
	if latestLocation != nil {
		out["latestLocation"] = latestLocation
	}
	if locAt != nil && *locAt != "" {
		out["locationRecordedAt"] = *locAt
	}
	if activeJID != nil {
		out["activeJourneyId"] = *activeJID
	}
	if targetLab != nil {
		out["targetLaboratoryId"] = *targetLab
	}
	if len(exc) > 0 && string(exc) != "null" {
		out["exception"] = jsonRaw(exc)
	}
	return out
}

// handleReadOperationsState implements POST /api/read-operations-state.
func (a *App) handleReadOperationsState(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		writeError(w, errCode(405, "method_not_allowed", "POST required"))
		return
	}
	u := currentUser(r)
	if e := requireRole(u, "administrator", "dispatcher"); e != nil {
		writeError(w, e)
		return
	}
	out := a.operationsState(r.Context())
	// Append samples with current holder + staleness.
	rows, _ := a.pg.Query(r.Context(), `SELECT s.sample_id::text, s.status, COALESCE(s.current_holder_id::text,''), s.location_recorded_at::text, COALESCE(s.latest_latitude,0), COALESCE(s.latest_longitude,0), st.name
		FROM samples s JOIN sample_types st ON st.sample_type_id=s.sample_type_id ORDER BY s.created_at DESC LIMIT 200`)
	samples := []map[string]any{}
	if rows != nil {
		for rows.Next() {
			var sid, status, holder, locAt, name string
			var la, lo float64
			_ = rows.Scan(&sid, &status, &holder, &locAt, &la, &lo, &name)
			stale := false
			if locAt != "" {
				if t, err := time.Parse(time.RFC3339Nano, locAt); err == nil {
					stale = time.Since(t).Minutes() > 30
				}
			}
			samples = append(samples, map[string]any{
				"sampleId":        sid,
				"status":         status,
				"currentHolderId": holder,
				"sampleType":     name,
				"location":       map[string]any{"latitude": la, "longitude": lo, "stale": stale, "recordedAt": locAt},
			})
		}
		rows.Close()
	}
	out["samples"] = samples
	writeData(w, 200, out)
}

// handleReadJourneyPlan implements POST /api/read-journey-plan.
func (a *App) handleReadJourneyPlan(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		writeError(w, errCode(405, "method_not_allowed", "POST required"))
		return
	}
	u := currentUser(r)
	if e := requireRole(u, "administrator", "dispatcher"); e != nil {
		writeError(w, e)
		return
	}
	var req struct {
		JourneyID string `json:"journeyId"`
		SampleID  string `json:"sampleId"`
	}
	if err := decodeJSON(r, &req); err != nil {
		writeError(w, errInvalidJSON)
		return
	}
	jid := req.JourneyID
	if jid == "" && req.SampleID != "" {
		_ = a.pg.QueryRow(r.Context(), `SELECT active_journey_id::text FROM samples WHERE sample_id::text=$1`, req.SampleID).Scan(&jid)
	}
	if jid == "" {
		writeError(w, errNotFound)
		return
	}
	plan := a.readJourneyPlan(r.Context(), jid)
	writeData(w, 200, plan)
}

func (a *App) readJourneyPlan(ctx context.Context, jid string) map[string]any {
	var routeMode, status, jStatus, targetLab string
	var planVersion int
	var valid bool
	var estArrival *string
	_ = a.pg.QueryRow(ctx, `SELECT route_mode, status, COALESCE(status,'planned'), COALESCE(target_laboratory_id::text,''), plan_version, valid, estimated_delivery_at::text FROM journeys WHERE journey_id::text=$1`, jid).
		Scan(&routeMode, &status, &jStatus, &targetLab, &planVersion, &valid, &estArrival)

	stops := []map[string]any{}
	rows, _ := a.pg.Query(ctx, `SELECT stop_id::text, location_id::text, stop_type, sequence, estimated_at::text, completed_at::text FROM journey_stops WHERE journey_id::text=$1 ORDER BY sequence`, jid)
	if rows != nil {
		for rows.Next() {
			var sid, locID, stType string
			var seq int
			var est, done *string
			_ = rows.Scan(&sid, &locID, &stType, &seq, &est, &done)
			stops = append(stops, map[string]any{
				"stopId":     sid,
				"locationId": locID,
				"stopType":   stType,
				"sequence":   seq,
				"estimatedAt": strPtr(est),
				"completedAt": strPtr(done),
			})
		}
		rows.Close()
	}

	assigns := []map[string]any{}
	rows, _ = a.pg.Query(ctx, `SELECT assignment_id::text, kind, sequence, status, from_location_id::text, to_location_id::text, worker_id::text, sample_id::text, node_id::text, laboratory_id::text FROM assignments WHERE journey_id::text=$1 ORDER BY sequence`, jid)
	if rows != nil {
		for rows.Next() {
			var aid, kind, status string
			var seq int
			var from, to, worker, sample, node, lab *string
			_ = rows.Scan(&aid, &kind, &seq, &status, &from, &to, &worker, &sample, &node, &lab)
			assigns = append(assigns, map[string]any{
				"assignmentId": aid,
				"kind":         kind,
				"sequence":     seq,
				"status":       status,
				"fromLocationId": strPtr(from),
				"toLocationId":   strPtr(to),
				"workerId":       strPtr(worker),
				"sampleId":       strPtr(sample),
				"nodeId":         strPtr(node),
				"laboratoryId":   strPtr(lab),
			})
		}
		rows.Close()
	}

	return map[string]any{
		"journeyId":          jid,
		"planVersion":        planVersion,
		"routeMode":          routeMode,
		"status":             jStatus,
		"valid":              valid,
		"targetLaboratoryId": targetLab,
		"estimatedArrival":   strPtr(estArrival),
		"stops":              stops,
		"assignments":        assigns,
	}
}

// handleEditActivePlan implements POST /api/edit-active-plan.
func (a *App) handleEditActivePlan(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		writeError(w, errCode(405, "method_not_allowed", "POST required"))
