	var parentJID *string
	var routeMode, status string
	var planVersion int
	var valid bool
	var estDelivery *string
	var totalCost float64
	var targetLab *string
	_ = a.pg.QueryRow(ctx, `SELECT parent_journey_id::text, route_mode, COALESCE(status,'planned'), plan_version, valid, estimated_delivery_at::text, total_cost_units, target_laboratory_id::text FROM journeys WHERE journey_id::text=$1`, jid).
		Scan(&parentJID, &routeMode, &status, &planVersion, &valid, &estDelivery, &totalCost, &targetLab)

	sampleIDs := []string{}
	rows, _ := a.pg.Query(ctx, `SELECT sample_id::text FROM journey_samples WHERE journey_id::text=$1`, jid)
	if rows != nil {
		for rows.Next() {
			var sid string
			_ = rows.Scan(&sid)
			sampleIDs = append(sampleIDs, sid)
		}
		rows.Close()
	}

	orderedStops := []map[string]any{}
	rows, _ = a.pg.Query(ctx, `SELECT stop_id::text, location_id::text, stop_type, sequence, estimated_at::text, dwell_minutes, completed_at::text, l.latitude, l.longitude FROM journey_stops s JOIN locations l ON l.location_id=s.location_id WHERE s.journey_id::text=$1 ORDER BY sequence`, jid)
	if rows != nil {
		for rows.Next() {
			var sid, locID, stType string
			var seq, dwell int
			var est, done *string
			var lat, lng float64
			_ = rows.Scan(&sid, &locID, &stType, &seq, &est, &dwell, &done, &lat, &lng)
			stop := map[string]any{
				"stopId":        sid,
				"locationId":    locID,
				"stopType":      stType,
				"sequence":      seq,
				"dwellMinutes":  dwell,
				"coordinate":    map[string]any{"latitude": lat, "longitude": lng},
			}
			if est != nil {
				stop["estimatedAt"] = *est
			}
			if done != nil {
				stop["completedAt"] = *done
			}
			orderedStops = append(orderedStops, stop)
		}
		rows.Close()
	}

	legs := []map[string]any{}
	assignedWorkerIDs := []string{}
	var collectionAssignIDs, nodeAssignIDs, labAssignIDs []string
	var firstTransport, middleTransport, finalTransport string
	rows, _ = a.pg.Query(ctx, `SELECT assignment_id::text, kind, sequence, status, from_location_id::text, to_location_id::text, worker_id::text, sample_id::text, node_id::text, laboratory_id::text FROM assignments WHERE journey_id::text=$1 ORDER BY sequence`, jid)
	if rows != nil {
		idx := 0
		for rows.Next() {
			var aid, kind, asgStatus string
			var seq int
			var from, to, worker, sample, node, lab *string
			_ = rows.Scan(&aid, &kind, &seq, &asgStatus, &from, &to, &worker, &sample, &node, &lab)
			leg := map[string]any{
				"assignmentId":  aid,
				"kind":          kind,
				"sequence":      seq,
				"status":        asgStatus,
				"fromLocationId": strPtr(from),
				"toLocationId":   strPtr(to),
				"workerId":       strPtr(worker),
				"sampleId":       strPtr(sample),
				"nodeId":         strPtr(node),
				"laboratoryId":   strPtr(lab),
			}
			legs = append(legs, leg)
			if worker != nil && *worker != "" {
				assignedWorkerIDs = append(assignedWorkerIDs, *worker)
			}
			switch kind {
			case "collection":
				collectionAssignIDs = append(collectionAssignIDs, aid)
			case "node":
				nodeAssignIDs = append(nodeAssignIDs, aid)
			case "laboratory":
				labAssignIDs = append(labAssignIDs, aid)
			case "transport":
				switch idx {
				case 0:
					firstTransport = aid
