		return
	}
	var req struct {
		JourneyID        string `json:"journeyId"`
		PlanVersion      int    `json:"planVersion"`
		NewTargetLabID   string `json:"newTargetLaboratoryId"`
	}
	if err := decodeJSON(r, &req); err != nil {
		writeError(w, errInvalidJSON)
		return
	}
	var cur int
	_ = a.pg.QueryRow(r.Context(), `SELECT plan_version FROM journeys WHERE journey_id::text=$1`, req.JourneyID).Scan(&cur)
