// handleMergeJourneys implements POST /api/merge-journeys.
func (a *App) handleMergeJourneys(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		writeError(w, errCode(405, "method_not_allowed", "POST required"))
		return
	}
	u := currentUser(r)
	if e := requireRole(u, "administrator", "dispatcher"); e != nil {
		writeError(w, e)
		return
	}
	var req struct {
		JourneyIDs []string `json:"journeyIds"`
	}
	if err := decodeJSON(r, &req); err != nil {
		writeError(w, errInvalidJSON)
		return
	}
	if len(req.JourneyIDs) < 2 {
		writeError(w, errCode(400, "invalid_input", "need at least two journeys"))
		return
	}
	primary := req.JourneyIDs[0]
	// Link samples from the other journeys to the primary.
	for _, jid := range req.JourneyIDs[1:] {
		rows, _ := a.pg.Query(r.Context(), `SELECT sample_id::text FROM journey_samples WHERE journey_id::text=$1`, jid)
		if rows != nil {
			for rows.Next() {
				var sid string
				_ = rows.Scan(&sid)
				_, _ = a.pg.Exec(r.Context(), `INSERT INTO journey_samples (journey_id, sample_id) VALUES ($1,$2) ON CONFLICT DO NOTHING`, primary, sid)
				_, _ = a.pg.Exec(r.Context(), `UPDATE samples SET active_journey_id=$1 WHERE sample_id::text=$2`, primary, sid)
			}
			rows.Close()
		}
		_, _ = a.pg.Exec(r.Context(), `UPDATE journeys SET status='cancelled' WHERE journey_id::text=$1`, jid)
	}
	_, _ = a.pg.Exec(r.Context(), `UPDATE journeys SET plan_version=plan_version+1 WHERE journey_id::text=$1`, primary)
	a.audit(r.Context(), u, "merge_journeys", "journey", primary, true, map[string]any{"merged": req.JourneyIDs[1:]})
	writeData(w, 201, a.readJourneyPlan(r.Context(), primary))
}

