// handleCancelJourney implements POST /api/cancel-journey.
func (a *App) handleCancelJourney(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		writeError(w, errCode(405, "method_not_allowed", "POST required"))
		return
	}
	u := currentUser(r)
	if e := requireRole(u, "administrator", "dispatcher"); e != nil {
		writeError(w, e)
		return
	}
	var req struct {
		JourneyID string `json:"journeyId"`
		Reason    string `json:"reason"`
	}
	if err := decodeJSON(r, &req); err != nil {
		writeError(w, errInvalidJSON)
		return
	}
	_, err := a.pg.Exec(r.Context(), `UPDATE journeys SET status='cancelled' WHERE journey_id::text=$1 AND status NOT IN ('completed','cancelled')`, req.JourneyID)
	if err != nil {
		writeError(w, errConflict)
		return
	}
	// Mark unfinished assignments cancelled.
	_, _ = a.pg.Exec(r.Context(), `UPDATE assignments SET status='cancelled' WHERE journey_id::text=$1 AND status NOT IN ('completed','cancelled')`, req.JourneyID)
	// Mark linked samples cancelled if not received.
	_, _ = a.pg.Exec(r.Context(), `UPDATE samples SET status='cancelled' WHERE active_journey_id::text=$1 AND status NOT IN ('received')`, req.JourneyID)
	sampleIDs := []string{}
	rows, _ := a.pg.Query(r.Context(), `SELECT sample_id::text FROM journey_samples WHERE journey_id::text=$1`, req.JourneyID)
	if rows != nil {
		for rows.Next() {
			var sid string
			_ = rows.Scan(&sid)
			sampleIDs = append(sampleIDs, sid)
		}
		rows.Close()
	}
	a.audit(r.Context(), u, "cancel_journey", "journey", req.JourneyID, true, map[string]any{"reason": req.Reason})
	writeData(w, 201, map[string]any{
		"journeyId": req.JourneyID,
		"status":    "cancelled",
		"sampleIds": sampleIDs,
	})
}

// handleReportDisruption implements POST /api/report-disruption.
func (a *App) handleReportDisruption(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		writeError(w, errCode(405, "method_not_allowed", "POST required"))
		return
	}
	u := currentUser(r)
	if e := requireRole(u, "administrator", "dispatcher"); e != nil {
		writeError(w, e)
		return
	}
	var req struct {
		ResourceType string `json:"resourceType"`
		ResourceID   string `json:"resourceId"`
		Reason       string `json:"reason"`
	}
	if err := decodeJSON(r, &req); err != nil {
		writeError(w, errInvalidJSON)
		return
	}
	did := uuidStr()
	_, err := a.pg.Exec(r.Context(), `INSERT INTO disruptions (disruption_id, resource_type, resource_id, reason, occurred_at) VALUES ($1,$2,$3,$4,now())`,
		did, req.ResourceType, req.ResourceID, req.Reason)
	if err != nil {
		writeError(w, errConflict)
		return
	}
	// Deactivate the affected resource if recognized.
	switch req.ResourceType {
	case "worker":
		_, _ = a.pg.Exec(r.Context(), `UPDATE worker_profiles SET available=false WHERE worker_id::text=$1`, req.ResourceID)
	case "node", "laboratory":
		_, _ = a.pg.Exec(r.Context(), `UPDATE locations SET active=false WHERE location_id::text=$1`, req.ResourceID)
	case "connection":
		_, _ = a.pg.Exec(r.Context(), `UPDATE connections SET active=false WHERE connection_id::text=$1`, req.ResourceID)
	}
	// Find samples on journeys that use the affected resource.
	affectedSamples := []string{}
	replacementPlans := []string{}
	replanStatus := "not_required"
	switch req.ResourceType {
	case "node", "laboratory":
		rows, _ := a.pg.Query(r.Context(), `SELECT DISTINCT s.sample_id::text FROM samples s JOIN assignments a ON a.journey_id=s.active_journey_id WHERE (a.node_id::text=$1 OR a.laboratory_id::text=$1 OR a.from_location_id::text=$1 OR a.to_location_id::text=$1) AND s.status NOT IN ('received','cancelled')`, req.ResourceID)
		if rows != nil {
			for rows.Next() {
				var sid string
				_ = rows.Scan(&sid)
				affectedSamples = append(affectedSamples, sid)
			}
			rows.Close()
		}
	case "worker":
		rows, _ := a.pg.Query(r.Context(), `SELECT DISTINCT s.sample_id::text FROM samples s JOIN assignments a ON a.journey_id=s.active_journey_id WHERE a.worker_id::text=$1 AND s.status NOT IN ('received','cancelled')`, req.ResourceID)
		if rows != nil {
			for rows.Next() {
				var sid string
				_ = rows.Scan(&sid)
				affectedSamples = append(affectedSamples, sid)
			}
			rows.Close()
		}
	case "connection":
		rows, _ := a.pg.Query(r.Context(), `SELECT DISTINCT s.sample_id::text FROM samples s JOIN assignments a ON a.journey_id=s.active_journey_id JOIN connections c ON c.from_location_id=a.from_location_id AND c.to_location_id=a.to_location_id WHERE c.connection_id::text=$1 AND s.status NOT IN ('received','cancelled')`, req.ResourceID)
		if rows != nil {
			for rows.Next() {
				var sid string
				_ = rows.Scan(&sid)
				affectedSamples = append(affectedSamples, sid)
			}
			rows.Close()
		}
	}
	if len(affectedSamples) > 0 {
		replanStatus = "replaced"
		// Re-query each sample's active journey id and record replacement plans.
		for _, sid := range affectedSamples {
			var jid string
			_ = a.pg.QueryRow(r.Context(), `SELECT active_journey_id::text FROM samples WHERE sample_id::text=$1`, sid).Scan(&jid)
			if jid == "" {
				continue
			}
			rid := uuidStr()
			_, _ = a.pg.Exec(r.Context(), `INSERT INTO replacement_plans (replacement_plan_id, journey_id, status, reason) VALUES ($1,$2,'replaced',$3)`, rid, jid, req.Reason)
			replacementPlans = append(replacementPlans, rid)
		}
	}
	// Trigger serviceability recompute in background.
	go a.recomputeServiceability()
	a.audit(r.Context(), u, "report_disruption", "disruption", did, true, map[string]any{"resourceType": req.ResourceType, "resourceId": req.ResourceID, "affectedSamples": affectedSamples})
	writeData(w, 201, map[string]any{
		"disruptionId":        did,
		"affectedSampleIds":  affectedSamples,
		"replacementPlanIds": replacementPlans,
		"replanStatus":       replanStatus,
	})
}

// handleSearchAuditTrail implements POST /api/search-audit-trail.
func (a *App) handleSearchAuditTrail(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		writeError(w, errCode(405, "method_not_allowed", "POST required"))
		return
	}
	u := currentUser(r)
	if e := requireRole(u, "administrator", "dispatcher"); e != nil {
		writeError(w, e)
		return
	}
	var req struct {
		Query      string `json:"query"`
		EntityType string `json:"entityType"`
		EntityID   string `json:"entityId"`
		ActorID    string `json:"actorId"`
		Action     string `json:"action"`
		Role       string `json:"role"`
		FromTime   string `json:"fromTime"`
		ToTime     string `json:"toTime"`
		Limit      int    `json:"limit"`
		Offset     int    `json:"offset"`
		Order      string `json:"order"`
	}
	if err := decodeJSON(r, &req); err != nil {
		writeError(w, errInvalidJSON)
		return
	}
	if req.Limit <= 0 {
		req.Limit = 50
	}
	if req.Order == "" {
		req.Order = "newest_first"
	}
	q := auditQuery{
		Query:      req.Query,
		EntityType: req.EntityType,
		EntityID:   req.EntityID,
		ActorID:    req.ActorID,
		Action:     req.Action,
		Role:       req.Role,
		Limit:      req.Limit,
		Offset:     req.Offset,
		Order:      req.Order,
	}
	if req.FromTime != "" {
		if t, e := parseTime(req.FromTime, "invalid_time"); e == nil {
			q.FromTime = t
		} else {
			writeError(w, e)
			return
		}
	}
	if req.ToTime != "" {
		if t, e := parseTime(req.ToTime, "invalid_time"); e == nil {
			q.ToTime = t
		} else {
			writeError(w, e)
			return
		}
	}
	res, err := auditSearch(r.Context(), a, q)
	if err != nil {
		writeError(w, errInternal)
		return
	}
	writeData(w, 200, res)
}

