type auditRecord struct {
	ActorID    string
	Role       string
	Action     string
	EntityType string
	EntityID   string
	Success    bool
	OccurredAt time.Time
	Details    map[string]any
}

func (a *App) audit(ctx context.Context, u *AuthUser, action, entityType, entityID string, success bool, details map[string]any) {
	if u == nil {
		u = &AuthUser{}
	}
	aid := uuidStr()
	seq := a.nextAuditSeq(ctx)
	rec := bson.M{
		"auditId":    aid,
		"eventId":    seq,
		"actorId":    u.UserID,
		"role":       u.ActiveRole,
		"actorRole":  u.ActiveRole,
		"action":     action,
		"entityType": entityType,
		"entityId":   entityID,
		"success":    success,
		"occurredAt": time.Now().UTC(),
		"timestamp":  time.Now().UTC(),
		"details":    details,
	}
	_, _ = a.mdb.Collection("audit_events").InsertOne(ctx, rec)
}

// realtime event seq counter
func (a *App) emitRealtime(ctx context.Context, etype, entityType, entityID string, payload map[string]any) {
	seq := a.nextSeq(ctx)
	_, _ = a.mdb.Collection("realtime_events").InsertOne(ctx, bson.M{
		"id":          seq,
		"seq":         seq,
		"type":        etype,
		"entityType":  entityType,
		"entityId":    entityID,
		"payload":     payload,
		"createdAt":   time.Now().UTC(),
		"timestamp":   time.Now().UTC(),
	})
}

func (a *App) nextSeq(ctx context.Context) int64 {
	for {
		var seq int64
		err := a.pg.QueryRow(ctx, `SELECT seq FROM network_revision WHERE id=1 FOR UPDATE`).Scan(&seq)
		if err != nil {
			return time.Now().UnixNano()
		}
		seq++
		_, err = a.pg.Exec(ctx, `UPDATE network_revision SET seq=$1 WHERE id=1`, seq)
		if err == nil {
			return seq
		}
	}
}

func init() {
	// network_revision table is created in migrate; add seq column if missing at runtime via migration
}

func (a *App) ensureSeqCol(ctx context.Context) {
	_, _ = a.pg.Exec(ctx, `ALTER TABLE network_revision ADD COLUMN IF NOT EXISTS seq bigint NOT NULL DEFAULT 0`)
	_, _ = a.pg.Exec(ctx, `ALTER TABLE network_revision ADD COLUMN IF NOT EXISTS audit_seq bigint NOT NULL DEFAULT 0`)
	_, _ = a.pg.Exec(ctx, `UPDATE network_revision SET seq=0 WHERE id=1 AND seq IS NULL`)
}

// nextAuditSeq returns a monotonically increasing event id for audit records.
func (a *App) nextAuditSeq(ctx context.Context) int64 {
	for {
		var seq int64
		err := a.pg.QueryRow(ctx, `SELECT audit_seq FROM network_revision WHERE id=1 FOR UPDATE`).Scan(&seq)
		if err != nil {
			return time.Now().UnixNano()
		}
		seq++
		_, err = a.pg.Exec(ctx, `UPDATE network_revision SET audit_seq=$1 WHERE id=1`, seq)
		if err == nil {
			return seq
		}
	}
}

func realtimeQuery(ctx context.Context, a *App, since int64, limit int) ([]bson.M, int64, error) {
	if limit <= 0 {
		limit = 500
	}
	opts := options.Find().SetSort(bson.D{{Key: "seq", Value: 1}}).SetLimit(int64(limit))
	filter := bson.M{}
	if since > 0 {
		filter["seq"] = bson.M{"$gt": since}
	}
	cur, err := a.mdb.Collection("realtime_events").Find(ctx, filter, opts)
	if err != nil {
		return nil, 0, err
	}
	defer cur.Close(ctx)
	var out []bson.M
	if err := cur.All(ctx, &out); err != nil {
		return nil, 0, err
	}
	var last int64 = since
	for _, d := range out {
		if s, ok := d["seq"].(int64); ok && s > last {
			last = s
		}
	}
	return out, last, nil
}

