[?2004lpackage main

import (
	"context"
	"crypto/sha256"
	"encoding/hex"
	"fmt"
)

func hashPassword(password, salt string) string {
	h := sha256.New()
	h.Write([]byte(salt))
	h.Write([]byte(password))
	h.Write([]byte("labpd-v1"))
	return hex.EncodeToString(h.Sum(nil))
}

func newSalt() string {
	return newToken()[:16]
}

// SeedDefaults seeds the four default sample types if missing.
func (a *App) SeedDefaults(ctx context.Context) error {
	defaults := []struct {
		name         string
		container    string
		tmin, tmax   float64
		qual         string
		cooled       bool
		batching     bool
		incompatible []string
	}{
		{"Amber", "standard", 15, 25, "", false, true, nil},
		{"Indigo", "standard", 15, 25, "", false, true, []string{"Amber"}},
		{"Frost", "cooled", 2, 8, "", true, true, nil},
		{"Pulse", "standard", 15, 25, "", false, false, nil},
	}
	for _, d := range defaults {
		var exists bool
		err := a.pg.QueryRow(ctx, `SELECT EXISTS(SELECT 1 FROM sample_types WHERE name=$1)`, d.name).Scan(&exists)
		if err != nil {
			return err
		}
		if exists {
			continue
		}
		incompat := d.incompatible
		if incompat == nil {
			incompat = []string{}
		}
		_, err = a.pg.Exec(ctx, `INSERT INTO sample_types
			(sample_type_id, name, qualified_collector_required, required_qualification, container_type, temperature_min_c, temperature_max_c, requires_cooled_route, batching_allowed, incompatible, is_default)
			VALUES ($1,$2,true,$3,$4,$5,$6,$7,$8,$9,true)`,
			uuidStr(), d.name, d.name, d.container, d.tmin, d.tmax, d.cooled, d.batching, incompat)
		if err != nil {
			return err
		}
	}
	// Resolve Indigo's incompatibility to Amber's UUID.
	var amberID string
	_ = a.pg.QueryRow(ctx, `SELECT sample_type_id::text FROM sample_types WHERE name='Amber'`).Scan(&amberID)
	if amberID != "" {
		_, _ = a.pg.Exec(ctx, `UPDATE sample_types SET incompatible=$1 WHERE name='Indigo'`, []string{amberID})
	}
	return nil
}

// EnsureInitialAdmin creates the first administrator account when no users exist.
func (a *App) EnsureInitialAdmin(ctx context.Context) error {
	var count int
	if err := a.pg.QueryRow(ctx, `SELECT COUNT(*) FROM users`).Scan(&count); err != nil {
		return err
	}
	if count > 0 {
		return nil
	}
	if a.cfg.AdminUser == "" || a.cfg.AdminPass == "" {
		return fmt.Errorf("ADMIN_USERNAME/ADMIN_PASSWORD not set and no users exist")
	}
	salt := newSalt()
	_, err := a.pg.Exec(ctx, `INSERT INTO users
		(user_id, username, password_hash, password_salt, roles, qualifications, active, full_name)
		VALUES ($1,$2,$3,$4,$5,$6,true,'System Administrator')`,
		uuidStr(), a.cfg.AdminUser, hashPassword(a.cfg.AdminPass, salt), salt,
		[]string{"administrator"}, []string{})
	return err
}[?2004h

