	if req.EarliestCollectionAt != "" {
		earliest, e = parseTime(req.EarliestCollectionAt, "invalid_collection_window")
		if e != nil {
			writeError(w, e)
			return
		}
	}
	if req.LatestCollectionAt != "" {
		latest, e = parseTime(req.LatestCollectionAt, "invalid_collection_window")
		if e != nil {
			writeError(w, e)
			return
		}
	}
	if !earliest.IsZero() && !latest.IsZero() && latest.Before(earliest) {
		writeError(w, errCode(400, "invalid_collection_window", "latest collection before earliest"))
		return
	}
	if !deadline.IsZero() && !latest.IsZero() && deadline.Before(latest) {
		writeError(w, errCode(400, "invalid_deadline", "deadline before latest collection"))
		return
	}
	st, err := loadSampleType(r.Context(), a.pg, req.SampleTypeID)
	if err != nil {
		writeError(w, errCode(400, "invalid_sample_type", "unknown sample type"))
		return
	}
