func normalizeAudit(d bson.M) map[string]any {
	oid := getStr(d, "_id")
	aid := getStr(d, "auditId")
	if aid == "" {
		aid = oid
	}
	return map[string]any{
		"auditId":    aid,
		"audit_id":   aid,
		"actorId":    getStr(d, "actorId"),
		"actor_id":   getStr(d, "actorId"),
		"role":        getStr(d, "role"),
