		"occurred_at": getTime(d, "occurredAt"),
		"details":    normalizeDetails(d["details"]),
	}
}

func normalizeDetails(v any) map[string]any {
	if v == nil {
		return map[string]any{}
	}
	if m, ok := v.(map[string]any); ok {
		return m
	}
	return map[string]any{}
}

func getStr(d bson.M, k string) string {
	if v, ok := d[k]; ok {
		switch t := v.(type) {
		case string:
			return t
		}
	}
	return ""
}

func getBool(d bson.M, k string) bool {
	if v, ok := d[k]; ok {
