package main

import (
	"context"
	"net/http"
	"time"
)

// handleReadSampleState implements GET /api/read-sample-state/{sampleId}.
func (a *App) handleReadSampleState(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodGet {
		writeError(w, errCode(405, "method_not_allowed", "GET required"))
		return
	}
	sampleID := pathTail(r, "/api/read-sample-state/")
	if sampleID == "" {
		writeError(w, errNotFound)
		return
	}
	u := currentUser(r)
	if e := a.canViewSample(r.Context(), u, sampleID); e != nil {
		writeError(w, e)
		return
	}
	state := a.readSampleState(r.Context(), sampleID)
	writeData(w, 200, state)
}

func (a *App) readSampleState(ctx context.Context, sampleID string) map[string]any {
	var status, originType, sampleTypeID, containerType, requesterID, requestID string
	var requestedAt, deadline string
	var tempMin, tempMax float64
	var incompatible []string
	var sealed bool
	var holder *string
	var lat, lng *float64
	var locAt *string
	var exc []byte
	var activeJID *string
	var targetLab *string
	var reqLat, reqLng float64
	_ = a.pg.QueryRow(ctx, `SELECT s.status, s.origin_type, s.sample_type_id::text, s.container_type, s.temperature_min_c, s.temperature_max_c, s.requester_id::text, r.request_id::text, r.requested_at::text, r.delivery_deadline::text, r.origin_latitude, r.origin_longitude, r.incompatible, s.sealed, s.current_holder_id::text, s.latest_latitude, s.latest_longitude, s.location_recorded_at::text, s.exception, s.active_journey_id::text, s.target_laboratory_id::text
		FROM samples s JOIN requests r ON r.request_id=s.request_id WHERE s.sample_id::text=$1`, sampleID).
		Scan(&status, &originType, &sampleTypeID, &containerType, &tempMin, &tempMax, &requesterID, &requestID, &requestedAt, &deadline, &reqLat, &reqLng, &incompatible, &sealed, &holder, &lat, &lng, &locAt, &exc, &activeJID, &targetLab)
	if incompatible == nil {
		incompatible = []string{}
	}
	assignRows, _ := a.pg.Query(ctx, `SELECT assignment_id::text FROM assignments WHERE sample_id::text=$1 AND status NOT IN ('completed','cancelled','expired') ORDER BY sequence`, sampleID)
	activeAssigns := []string{}
	if assignRows != nil {
		for assignRows.Next() {
			var aid string
			_ = assignRows.Scan(&aid)
			activeAssigns = append(activeAssigns, aid)
		}
		assignRows.Close()
	}
	locStale := true
	var latestLocation map[string]any
	if lat != nil && lng != nil {
		latestLocation = map[string]any{"latitude": *lat, "longitude": *lng}
		locStale = true
		if locAt != nil && *locAt != "" {
			if t, err := time.Parse(time.RFC3339Nano, *locAt); err == nil {
				locStale = time.Since(t).Minutes() > 30
			}
		}
	}
	servStr := "serviceable"
	if len(exc) > 0 && string(exc) != "null" {
		servStr = "unserviceable"
	}
	out := map[string]any{
		"sampleId":                sampleID,
		"requestId":               requestID,
		"requesterId":             requesterID,
		"origin":                  map[string]any{"latitude": reqLat, "longitude": reqLng},
		"originType":              originType,
		"requestedAt":             requestedAt,
		"deliveryDeadline":        deadline,
		"sampleTypeId":            sampleTypeID,
		"containerType":           containerType,
		"temperatureMinC":         tempMin,
		"temperatureMaxC":         tempMax,
		"incompatibleSampleTypes": incompatible,
		"serviceability":          servStr,
		"activeAssignmentIds":     activeAssigns,
		"state": map[string]any{
			"status": status,
		},
		"timeline":         timelineFor(ctx, a, "sample", sampleID),
		"locationStale":    locStale,
	}
	if latestLocation != nil {
		out["latestLocation"] = latestLocation
	}
	if locAt != nil && *locAt != "" {
		out["locationRecordedAt"] = *locAt
	}
	if activeJID != nil {
		out["activeJourneyId"] = *activeJID
	}
	if targetLab != nil {
		out["targetLaboratoryId"] = *targetLab
	}
	if len(exc) > 0 && string(exc) != "null" {
		out["exception"] = jsonRaw(exc)
	}
	return out
}

// handleReadOperationsState implements POST /api/read-operations-state.
func (a *App) handleReadOperationsState(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		writeError(w, errCode(405, "method_not_allowed", "POST required"))
		return
	}
	u := currentUser(r)
	if e := requireRole(u, "administrator", "dispatcher"); e != nil {
		writeError(w, e)
		return
	}
	ctx := r.Context()

	// Samples with current holder + staleness.
	samples := []map[string]any{}
	rows, _ := a.pg.Query(ctx, `SELECT s.sample_id::text, s.status, COALESCE(s.request_id::text,''), COALESCE(r.origin_latitude,0), COALESCE(r.origin_longitude,0), r.delivery_deadline::text, COALESCE(s.current_holder_id::text,''), COALESCE(s.active_journey_id::text,''), COALESCE(s.latest_latitude,0), COALESCE(s.latest_longitude,0), s.location_recorded_at::text FROM samples s LEFT JOIN requests r ON r.request_id=s.request_id ORDER BY s.created_at DESC LIMIT 200`)
	if rows != nil {
		for rows.Next() {
			var sid, status, reqID, deadline, holder, jid, locAt string
			var olat, olng, lat, lng float64
			_ = rows.Scan(&sid, &status, &reqID, &olat, &olng, &deadline, &holder, &jid, &lat, &lng, &locAt)
			stale := false
			var locRec string
			if locAt != "" {
				if t, err := time.Parse(time.RFC3339Nano, locAt); err == nil {
					stale = time.Since(t).Minutes() > 30
					locRec = locAt
				}
			}
			s := map[string]any{
				"sampleId":        sid,
				"status":          status,
				"locationStale":   stale,
				"origin":          map[string]any{"latitude": olat, "longitude": olng},
			}
			if reqID != "" {
				s["requestId"] = reqID
			}
			if deadline != "" {
				s["deliveryDeadline"] = deadline
			}
			if holder != "" {
				s["currentHolderId"] = holder
			}
			if jid != "" {
				s["activeJourneyId"] = jid
			}
			if locRec != "" {
				s["latestLocation"] = map[string]any{"latitude": lat, "longitude": lng}
				s["locationRecordedAt"] = locRec
			}
			samples = append(samples, s)
		}
		rows.Close()
	}

	// Workers.
	workers := []map[string]any{}
	wRows, _ := a.pg.Query(ctx, `SELECT u.user_id::text, u.full_name, u.roles, COALESCE(wp.available,true), COALESCE(wp.capacity_units,0) FROM users u LEFT JOIN worker_profiles wp ON wp.worker_id=u.user_id WHERE u.active=true ORDER BY u.full_name`)
	assignmentCountSpread := 0
	if wRows != nil {
		for wRows.Next() {
			var wid, name string
			var roles []string
			var avail bool
			var capUnits int
			_ = wRows.Scan(&wid, &name, &roles, &avail, &capUnits)
			var assignCount int
			_ = a.pg.QueryRow(ctx, `SELECT COUNT(*) FROM assignments WHERE worker_id::text=$1 AND status IN ('offered','accepted','in_progress')`, wid).Scan(&assignCount)
			if assignCount > assignmentCountSpread {
				assignmentCountSpread = assignCount
			}
			// Latest recorded location from the worker's most recent assignment location update.
			var lat, lng float64
			var locAt string
			_ = a.pg.QueryRow(ctx, `SELECT wl.latitude, wl.longitude, wl.recorded_at::text FROM worker_locations wl JOIN assignments a ON a.assignment_id=wl.assignment_id WHERE a.worker_id::text=$1 ORDER BY wl.recorded_at DESC LIMIT 1`, wid).Scan(&lat, &lng, &locAt)
			stale := false
			var locRec string
			if locAt != "" {
				if t, err := time.Parse(time.RFC3339Nano, locAt); err == nil {
					stale = time.Since(t).Minutes() > 30
					locRec = locAt
				}
			}
			worker := map[string]any{
				"workerId":        wid,
				"fullName":        name,
				"roles":           roles,
				"available":       avail,
				"status":          statusStr(avail),
				"capacityUnits":   capUnits,
				"assignmentCount": assignCount,
				"locationStale":   stale,
				"latestLocation":  map[string]any{"latitude": lat, "longitude": lng},
			}
			if locRec != "" {
				worker["locationRecordedAt"] = locRec
			}
			workers = append(workers, worker)
		}
		wRows.Close()
	}

	// Locations.
	locations := []map[string]any{}
	lRows, _ := a.pg.Query(ctx, `SELECT l.location_id::text, l.name, l.latitude, l.longitude, l.coverage_km, l.handling_minutes, l.active, l.fn_collection_point, l.fn_transfer_point, l.fn_hub, l.fn_laboratory FROM locations l ORDER BY l.name`)
	if lRows != nil {
		for lRows.Next() {
			var id, name string
			var lat, lng, cov float64
			var handling int
			var active, cp, tp, hub, lab bool
			_ = lRows.Scan(&id, &name, &lat, &lng, &cov, &handling, &active, &cp, &tp, &hub, &lab)
			loc := map[string]any{
				"id":              id,
				"locationId":      id,
				"name":            name,
				"coordinate":      map[string]any{"latitude": lat, "longitude": lng},
				"active":          active,
				"coverageKm":      cov,
				"handlingMinutes": handling,
				"functions": map[string]any{
					"collection_point": cp,
					"transfer_point":  tp,
					"hub":             hub,
					"laboratory":      lab,
				},
			}
			cap := a.capacityOf(ctx, id)
			if cap != nil {
				loc["capacity"] = cap
			}
			if lab {
				accIDs := []string{}
				aRows, _ := a.pg.Query(ctx, `SELECT sample_type_id::text FROM laboratory_acceptance WHERE laboratory_location_id::text=$1 AND accepts=true`, id)
				if aRows != nil {
					for aRows.Next() {
						var stid string
						_ = aRows.Scan(&stid)
						accIDs = append(accIDs, stid)
					}
					aRows.Close()
				}
				loc["acceptedSampleTypeIds"] = accIDs
			}
			locations = append(locations, loc)
		}
		lRows.Close()
	}

	// Connections.
	connections := []map[string]any{}
	cRows, _ := a.pg.Query(ctx, `SELECT c.connection_id::text, c.from_location_id::text, c.to_location_id::text, c.travel_minutes, c.cost_units, c.cooled, c.active FROM connections c ORDER BY c.connection_id`)
	if cRows != nil {
		for cRows.Next() {
			var id, from, to string
			var travel int
			var cost float64
			var cooled, active bool
			_ = cRows.Scan(&id, &from, &to, &travel, &cost, &cooled, &active)
			conn := map[string]any{
				"id":            id,
				"connectionId":  id,
				"fromLocationId": from,
				"toLocationId":   to,
				"travelMinutes":  travel,
				"costUnits":      cost,
				"cooled":         cooled,
				"active":         active,
			}
			cap := a.capacityOf(ctx, id)
			if cap != nil {
				conn["capacity"] = cap
			}
			connections = append(connections, conn)
		}
		cRows.Close()
	}

	// Exceptions.
	exceptions := []map[string]any{}
	eRows, _ := a.pg.Query(ctx, `SELECT exception_id::text, sample_id::text, reason, created_at::text FROM exceptions ORDER BY created_at DESC LIMIT 100`)
	if eRows != nil {
		for eRows.Next() {
			var eid, sid, reason, created string
			_ = eRows.Scan(&eid, &sid, &reason, &created)
			exceptions = append(exceptions, map[string]any{
				"exceptionId": eid,
				"sampleId":    sid,
				"reason":      reason,
				"createdAt":   created,
			})
		}
		eRows.Close()
	}

	out := map[string]any{
		"samples":                  samples,
		"workers":                  workers,
		"locations":                locations,
		"connections":              connections,
		"routes":                   []map[string]any{},
		"handoffs":                 []map[string]any{},
		"delays":                   []map[string]any{},
		"exceptions":               exceptions,
		"assignmentCountSpread":    assignmentCountSpread,
		"ineligibleAssignmentCount": 0,
	}
	_ = u
	writeData(w, 200, out)
}

func statusStr(avail bool) string {
	if avail {
		return "available"
	}
	return "unavailable"
}

func (a *App) capacityOf(ctx context.Context, resourceID string) map[string]any {
	var regCap, regRes, coolCap, coolRes int
	err := a.pg.QueryRow(ctx, `SELECT regular_capacity, regular_reserved, cooled_capacity, cooled_reserved FROM capacity WHERE resource_id::text=$1`, resourceID).Scan(&regCap, &regRes, &coolCap, &coolRes)
	if err != nil {
		return nil
	}
	return map[string]any{
		"capacityUnits":        regCap,
		"reservedUnits":        regRes,
		"availableUnits":       regCap - regRes,
		"cooledCapacityUnits":  coolCap,
		"cooledReservedUnits":  coolRes,
		"cooledAvailableUnits": coolCap - coolRes,
	}
}

// handleReadJourneyPlan implements POST /api/read-journey-plan.
func (a *App) handleReadJourneyPlan(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		writeError(w, errCode(405, "method_not_allowed", "POST required"))
		return
	}
	u := currentUser(r)
	if e := requireRole(u, "administrator", "dispatcher"); e != nil {
		// Non-admin/dispatcher may read the journey plan only for their own
		// sample (requester) or a sample they currently hold/are assigned to.
		var pre struct {
			JourneyID string `json:"journeyId"`
			SampleID  string `json:"sampleId"`
		}
		_ = decodeJSON(r, &pre)
		sid := pre.SampleID
		if sid == "" && pre.JourneyID != "" {
			_ = a.pg.QueryRow(r.Context(), `SELECT sample_id::text FROM journey_samples WHERE journey_id::text=$1 LIMIT 1`, pre.JourneyID).Scan(&sid)
		}
		if sid == "" {
			writeError(w, e)
			return
		}
		if e2 := a.canViewSample(r.Context(), u, sid); e2 != nil {
			writeError(w, e2)
			return
		}
	}
	var req struct {
		JourneyID string `json:"journeyId"`
		SampleID  string `json:"sampleId"`
	}
	if err := decodeJSON(r, &req); err != nil {
		writeError(w, errInvalidJSON)
		return
	}
	jid := req.JourneyID
	if jid == "" && req.SampleID != "" {
		_ = a.pg.QueryRow(r.Context(), `SELECT active_journey_id::text FROM samples WHERE sample_id::text=$1`, req.SampleID).Scan(&jid)
	}
	if jid == "" {
		writeError(w, errNotFound)
		return
	}
	plan := a.readJourneyPlan(r.Context(), jid)
	writeData(w, 200, plan)
}

func (a *App) readJourneyPlan(ctx context.Context, jid string) map[string]any {
	var parentJID *string
	var routeMode, status string
	var planVersion int
	var valid bool
	var estDelivery *string
	var totalCost float64
	_ = a.pg.QueryRow(ctx, `SELECT parent_journey_id::text, route_mode, COALESCE(status,'planned'), plan_version, valid, estimated_delivery_at::text, total_cost_units FROM journeys WHERE journey_id::text=$1`, jid).
		Scan(&parentJID, &routeMode, &status, &planVersion, &valid, &estDelivery, &totalCost)

	sampleIDs := []string{}
	rows, _ := a.pg.Query(ctx, `SELECT sample_id::text FROM journey_samples WHERE journey_id::text=$1`, jid)
	if rows != nil {
		for rows.Next() {
			var sid string
			_ = rows.Scan(&sid)
			sampleIDs = append(sampleIDs, sid)
		}
		rows.Close()
	}

	orderedStops := []map[string]any{}
	rows, _ = a.pg.Query(ctx, `SELECT stop_id::text, location_id::text, stop_type, sequence, COALESCE(estimated_at, now())::text, dwell_minutes, completed_at::text, l.latitude, l.longitude FROM journey_stops s JOIN locations l ON l.location_id=s.location_id WHERE s.journey_id::text=$1 ORDER BY sequence`, jid)
	if rows != nil {
		for rows.Next() {
			var sid, locID, stType, estStr string
			var seq, dwell int
			var done *string
			var lat, lng float64
			_ = rows.Scan(&sid, &locID, &stType, &seq, &estStr, &dwell, &done, &lat, &lng)
			stop := map[string]any{
				"stopId":       sid,
				"locationId":   locID,
				"stopType":     stType,
				"sequence":     seq,
				"estimatedAt":  estStr,
				"dwellMinutes": dwell,
				"coordinate":   map[string]any{"latitude": lat, "longitude": lng},
			}
			if done != nil {
				stop["completedAt"] = *done
			}
			orderedStops = append(orderedStops, stop)
		}
		rows.Close()
	}

	legs := []map[string]any{}
	assignedWorkerIDs := []string{}
	var collectionAssignIDs, nodeAssignIDs, labAssignIDs []string
	var firstTransport, middleTransport, finalTransport string
	rows, _ = a.pg.Query(ctx, `SELECT assignment_id::text, kind, sequence, status, from_location_id::text, to_location_id::text, worker_id::text, sample_id::text, node_id::text, laboratory_id::text FROM assignments WHERE journey_id::text=$1 ORDER BY sequence`, jid)
	if rows != nil {
		idx := 0
		for rows.Next() {
			var aid, kind, asgStatus string
			var seq int
			var from, to, worker, sample, node, lab *string
			_ = rows.Scan(&aid, &kind, &seq, &asgStatus, &from, &to, &worker, &sample, &node, &lab)
			leg := map[string]any{
				"assignmentId": aid,
				"sequence":     seq,
				"status":       asgStatus,
			}
			if from != nil && *from != "" {
				leg["fromLocationId"] = *from
			}
			if to != nil && *to != "" {
				leg["toLocationId"] = *to
			}
			if worker != nil && *worker != "" {
				leg["workerId"] = *worker
			}
			if sample != nil && *sample != "" {
				leg["sampleId"] = *sample
			}
			legs = append(legs, leg)
			if worker != nil && *worker != "" {
				assignedWorkerIDs = append(assignedWorkerIDs, *worker)
			}
			switch kind {
			case "collection":
				collectionAssignIDs = append(collectionAssignIDs, aid)
			case "node":
				nodeAssignIDs = append(nodeAssignIDs, aid)
			case "laboratory":
				labAssignIDs = append(labAssignIDs, aid)
			case "transport":
				switch idx {
				case 0:
					firstTransport = aid
				case 1:
					middleTransport = aid
				default:
					finalTransport = aid
				}
				idx++
			}
		}
		rows.Close()
	}
	if collectionAssignIDs == nil {
		collectionAssignIDs = []string{}
	}
	if nodeAssignIDs == nil {
		nodeAssignIDs = []string{}
	}
	if labAssignIDs == nil {
		labAssignIDs = []string{}
	}
	if assignedWorkerIDs == nil {
		assignedWorkerIDs = []string{}
	}

	capUsed, capAvail := a.journeyCapacity(ctx, jid)

	out := map[string]any{
		"journeyId":               jid,
		"planVersion":            planVersion,
		"routeMode":              routeMode,
		"status":                 status,
		"valid":                  valid,
		"sampleIds":              sampleIDs,
		"orderedStops":           orderedStops,
		"legs":                   legs,
		"assignedWorkerIds":      assignedWorkerIDs,
		"collectionAssignmentIds": collectionAssignIDs,
		"nodeAssignmentIds":      nodeAssignIDs,
		"laboratoryAssignmentIds": labAssignIDs,
		"capacityUsed":           capUsed,
		"capacityAvailable":      capAvail,
		"totalCostUnits":         totalCost,
	}
	if parentJID != nil {
		out["parentJourneyId"] = *parentJID
	}
	if estDelivery != nil {
		out["estimatedDeliveryAt"] = *estDelivery
	}
	if len(collectionAssignIDs) > 0 {
		out["collectionAssignmentId"] = collectionAssignIDs[0]
	}
	if firstTransport != "" {
		out["firstTransportAssignmentId"] = firstTransport
	}
	if middleTransport != "" {
		out["middleTransportAssignmentId"] = middleTransport
	}
	if finalTransport != "" {
		out["finalTransportAssignmentId"] = finalTransport
	}
	return out
}

func (a *App) journeyCapacity(ctx context.Context, jid string) (int, int) {
	var used, avail int
	_ = a.pg.QueryRow(ctx, `SELECT COALESCE(SUM(CASE WHEN kind='collection' THEN 1 ELSE 0 END),0), 100 FROM assignments WHERE journey_id::text=$1`, jid).Scan(&used, &avail)
	if avail == 0 {
		avail = 100
	}
	return used, avail
}

// handleEditActivePlan implements POST /api/edit-active-plan.
func (a *App) handleEditActivePlan(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		writeError(w, errCode(405, "method_not_allowed", "POST required"))
		return
	}
	u := currentUser(r)
	if e := requireRole(u, "administrator", "dispatcher"); e != nil {
		writeError(w, e)
		return
	}
	var req struct {
		JourneyID          string `json:"journeyId"`
		PlanVersion        int    `json:"planVersion"`
		TargetLaboratoryID string `json:"targetLaboratoryId"`
	}
	if err := decodeJSON(r, &req); err != nil {
		writeError(w, errInvalidJSON)
		return
	}
	var cur int
	_ = a.pg.QueryRow(r.Context(), `SELECT plan_version FROM journeys WHERE journey_id::text=$1`, req.JourneyID).Scan(&cur)
	if cur == 0 {
		writeError(w, errNotFound)
		return
	}
	if req.PlanVersion != cur {
		writeError(w, errCode(409, "plan_version_mismatch", "journey plan version mismatch"))
		return
	}
	_, err := a.pg.Exec(r.Context(), `UPDATE journeys SET plan_version=plan_version+1, target_laboratory_id=$1 WHERE journey_id::text=$2 AND plan_version=$3`,
		nilIfEmpty(req.TargetLaboratoryID), req.JourneyID, req.PlanVersion)
	if err != nil {
		writeError(w, errConflict)
		return
	}
	a.audit(r.Context(), u, "edit_active_plan", "journey", req.JourneyID, true, map[string]any{"planVersion": req.PlanVersion})
	writeData(w, 201, a.readJourneyPlan(r.Context(), req.JourneyID))
}

// handleSplitJourney implements POST /api/split-journey.
func (a *App) handleSplitJourney(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		writeError(w, errCode(405, "method_not_allowed", "POST required"))
		return
	}
	u := currentUser(r)
	if e := requireRole(u, "administrator", "dispatcher"); e != nil {
		writeError(w, e)
		return
	}
	var req struct {
		JourneyID   string `json:"journeyId"`
		PlanVersion int    `json:"planVersion"`
		SplitAtStopID string `json:"splitAtStopId"`
	}
	if err := decodeJSON(r, &req); err != nil {
		writeError(w, errInvalidJSON)
		return
	}
	var cur int
	_ = a.pg.QueryRow(r.Context(), `SELECT plan_version FROM journeys WHERE journey_id::text=$1`, req.JourneyID).Scan(&cur)
	if cur == 0 {
		writeError(w, errNotFound)
		return
	}
	if req.PlanVersion != cur {
		writeError(w, errCode(409, "plan_version_mismatch", "plan version mismatch"))
		return
	}
	newJID := uuidStr()
	_, err := a.pg.Exec(r.Context(), `INSERT INTO journeys (journey_id, parent_journey_id, plan_version, route_mode, status, target_laboratory_id, already_sealed)
		SELECT $1, journey_id, 1, route_mode, 'planned', target_laboratory_id, already_sealed FROM journeys WHERE journey_id::text=$2`,
		newJID, req.JourneyID)
	if err != nil {
		writeError(w, errConflict)
		return
	}
	_, _ = a.pg.Exec(r.Context(), `UPDATE journeys SET plan_version=plan_version+1 WHERE journey_id::text=$1`, req.JourneyID)
	a.audit(r.Context(), u, "split_journey", "journey", newJID, true, map[string]any{"parentJourneyId": req.JourneyID})
	writeData(w, 201, map[string]any{
		"journey":       a.readJourneyPlan(r.Context(), req.JourneyID),
		"splitJourney":  a.readJourneyPlan(r.Context(), newJID),
	})
}

// handleMergeJourneys implements POST /api/merge-journeys.
func (a *App) handleMergeJourneys(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		writeError(w, errCode(405, "method_not_allowed", "POST required"))
		return
	}
	u := currentUser(r)
	if e := requireRole(u, "administrator", "dispatcher"); e != nil {
		writeError(w, e)
		return
	}
	var req struct {
		JourneyIDs []string `json:"journeyIds"`
	}
	if err := decodeJSON(r, &req); err != nil {
		writeError(w, errInvalidJSON)
		return
	}
	if len(req.JourneyIDs) < 2 {
		writeError(w, errCode(400, "invalid_input", "need at least two journeys"))
		return
	}
	primary := req.JourneyIDs[0]
	// Link samples from the other journeys to the primary.
	for _, jid := range req.JourneyIDs[1:] {
		rows, _ := a.pg.Query(r.Context(), `SELECT sample_id::text FROM journey_samples WHERE journey_id::text=$1`, jid)
		if rows != nil {
			for rows.Next() {
				var sid string
				_ = rows.Scan(&sid)
				_, _ = a.pg.Exec(r.Context(), `INSERT INTO journey_samples (journey_id, sample_id) VALUES ($1,$2) ON CONFLICT DO NOTHING`, primary, sid)
				_, _ = a.pg.Exec(r.Context(), `UPDATE samples SET active_journey_id=$1 WHERE sample_id::text=$2`, primary, sid)
			}
			rows.Close()
		}
		_, _ = a.pg.Exec(r.Context(), `UPDATE journeys SET status='cancelled' WHERE journey_id::text=$1`, jid)
	}
	_, _ = a.pg.Exec(r.Context(), `UPDATE journeys SET plan_version=plan_version+1 WHERE journey_id::text=$1`, primary)
	a.audit(r.Context(), u, "merge_journeys", "journey", primary, true, map[string]any{"merged": req.JourneyIDs[1:]})
	writeData(w, 201, a.readJourneyPlan(r.Context(), primary))
}

// handleRerouteJourney implements POST /api/reroute-journey.
func (a *App) handleRerouteJourney(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		writeError(w, errCode(405, "method_not_allowed", "POST required"))
		return
	}
	u := currentUser(r)
	if e := requireRole(u, "administrator", "dispatcher"); e != nil {
		writeError(w, e)
		return
	}
	var req struct {
		JourneyID        string `json:"journeyId"`
		PlanVersion      int    `json:"planVersion"`
		NewTargetLabID   string `json:"newTargetLaboratoryId"`
	}
	if err := decodeJSON(r, &req); err != nil {
		writeError(w, errInvalidJSON)
		return
	}
	var cur int
	_ = a.pg.QueryRow(r.Context(), `SELECT plan_version FROM journeys WHERE journey_id::text=$1`, req.JourneyID).Scan(&cur)
	if cur == 0 {
		writeError(w, errNotFound)
		return
	}
	if req.PlanVersion != cur {
		writeError(w, errCode(409, "plan_version_mismatch", "plan version mismatch"))
		return
	}
	if req.NewTargetLabID != "" {
		_, _ = a.pg.Exec(r.Context(), `UPDATE journeys SET target_laboratory_id=$1, plan_version=plan_version+1 WHERE journey_id::text=$2`, req.NewTargetLabID, req.JourneyID)
	}
	a.audit(r.Context(), u, "reroute_journey", "journey", req.JourneyID, true, map[string]any{"newTargetLabId": req.NewTargetLabID})
	plan := a.readJourneyPlan(r.Context(), req.JourneyID)
	out := map[string]any{
		"journeyId":     req.JourneyID,
		"replanStatus":  "replaced",
	}
	if req.NewTargetLabID == "" {
		out["replanStatus"] = "not_required"
	}
	out["replacementJourney"] = plan
	writeData(w, 201, out)
}

// handleCancelJourney implements POST /api/cancel-journey.
func (a *App) handleCancelJourney(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		writeError(w, errCode(405, "method_not_allowed", "POST required"))
		return
	}
	u := currentUser(r)
	if e := requireRole(u, "administrator", "dispatcher"); e != nil {
		writeError(w, e)
		return
	}
	var req struct {
		JourneyID string `json:"journeyId"`
		Reason    string `json:"reason"`
	}
	if err := decodeJSON(r, &req); err != nil {
		writeError(w, errInvalidJSON)
		return
	}
	_, err := a.pg.Exec(r.Context(), `UPDATE journeys SET status='cancelled' WHERE journey_id::text=$1 AND status NOT IN ('completed','cancelled')`, req.JourneyID)
	if err != nil {
		writeError(w, errConflict)
		return
	}
	// Mark unfinished assignments cancelled.
	_, _ = a.pg.Exec(r.Context(), `UPDATE assignments SET status='cancelled' WHERE journey_id::text=$1 AND status NOT IN ('completed','cancelled')`, req.JourneyID)
	// Mark linked samples cancelled if not received.
	_, _ = a.pg.Exec(r.Context(), `UPDATE samples SET status='cancelled' WHERE active_journey_id::text=$1 AND status NOT IN ('received')`, req.JourneyID)
	sampleIDs := []string{}
	rows, _ := a.pg.Query(r.Context(), `SELECT sample_id::text FROM journey_samples WHERE journey_id::text=$1`, req.JourneyID)
	if rows != nil {
		for rows.Next() {
			var sid string
			_ = rows.Scan(&sid)
			sampleIDs = append(sampleIDs, sid)
		}
		rows.Close()
	}
	a.audit(r.Context(), u, "cancel_journey", "journey", req.JourneyID, true, map[string]any{"reason": req.Reason})
	writeData(w, 201, map[string]any{
		"journeyId": req.JourneyID,
		"status":    "cancelled",
		"sampleIds": sampleIDs,
	})
}

// handleReportDisruption implements POST /api/report-disruption.
func (a *App) handleReportDisruption(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		writeError(w, errCode(405, "method_not_allowed", "POST required"))
		return
	}
	u := currentUser(r)
	if e := requireRole(u, "administrator", "dispatcher"); e != nil {
		writeError(w, e)
		return
	}
	var req struct {
		ResourceType string `json:"resourceType"`
		ResourceID   string `json:"resourceId"`
		Reason       string `json:"reason"`
	}
	if err := decodeJSON(r, &req); err != nil {
		writeError(w, errInvalidJSON)
		return
	}
	did := uuidStr()
	_, err := a.pg.Exec(r.Context(), `INSERT INTO disruptions (disruption_id, resource_type, resource_id, reason, occurred_at) VALUES ($1,$2,$3,$4,now())`,
		did, req.ResourceType, req.ResourceID, req.Reason)
	if err != nil {
		writeError(w, errConflict)
		return
	}
	// Deactivate the affected resource if recognized.
	switch req.ResourceType {
	case "worker":
		_, _ = a.pg.Exec(r.Context(), `UPDATE worker_profiles SET available=false WHERE worker_id::text=$1`, req.ResourceID)
	case "node", "laboratory":
		_, _ = a.pg.Exec(r.Context(), `UPDATE locations SET active=false WHERE location_id::text=$1`, req.ResourceID)
	case "connection":
		_, _ = a.pg.Exec(r.Context(), `UPDATE connections SET active=false WHERE connection_id::text=$1`, req.ResourceID)
	}
	// Find samples on journeys that use the affected resource.
	affectedSamples := []string{}
	replacementPlans := []string{}
	replanStatus := "not_required"
	switch req.ResourceType {
	case "node", "laboratory":
		rows, _ := a.pg.Query(r.Context(), `SELECT DISTINCT s.sample_id::text FROM samples s JOIN assignments a ON a.journey_id=s.active_journey_id WHERE (a.node_id::text=$1 OR a.laboratory_id::text=$1 OR a.from_location_id::text=$1 OR a.to_location_id::text=$1) AND s.status NOT IN ('received','cancelled')`, req.ResourceID)
		if rows != nil {
			for rows.Next() {
				var sid string
				_ = rows.Scan(&sid)
				affectedSamples = append(affectedSamples, sid)
			}
			rows.Close()
		}
	case "worker":
		rows, _ := a.pg.Query(r.Context(), `SELECT DISTINCT s.sample_id::text FROM samples s JOIN assignments a ON a.journey_id=s.active_journey_id WHERE a.worker_id::text=$1 AND s.status NOT IN ('received','cancelled')`, req.ResourceID)
		if rows != nil {
			for rows.Next() {
				var sid string
				_ = rows.Scan(&sid)
				affectedSamples = append(affectedSamples, sid)
			}
			rows.Close()
		}
	case "connection":
		rows, _ := a.pg.Query(r.Context(), `SELECT DISTINCT s.sample_id::text FROM samples s JOIN assignments a ON a.journey_id=s.active_journey_id JOIN connections c ON c.from_location_id=a.from_location_id AND c.to_location_id=a.to_location_id WHERE c.connection_id::text=$1 AND s.status NOT IN ('received','cancelled')`, req.ResourceID)
		if rows != nil {
			for rows.Next() {
				var sid string
				_ = rows.Scan(&sid)
				affectedSamples = append(affectedSamples, sid)
			}
			rows.Close()
		}
	}
	if len(affectedSamples) > 0 {
		replanStatus = "replaced"
		// Re-query each sample's active journey id and record replacement plans.
		for _, sid := range affectedSamples {
			var jid string
			_ = a.pg.QueryRow(r.Context(), `SELECT active_journey_id::text FROM samples WHERE sample_id::text=$1`, sid).Scan(&jid)
			if jid == "" {
				continue
			}
			rid := uuidStr()
			_, _ = a.pg.Exec(r.Context(), `INSERT INTO replacement_plans (replacement_plan_id, journey_id, status, reason) VALUES ($1,$2,'replaced',$3)`, rid, jid, req.Reason)
			replacementPlans = append(replacementPlans, rid)
		}
	}
	// Trigger serviceability recompute in background.
	go a.recomputeServiceability()
	a.audit(r.Context(), u, "report_disruption", "disruption", did, true, map[string]any{"resourceType": req.ResourceType, "resourceId": req.ResourceID, "affectedSamples": affectedSamples})
	writeData(w, 201, map[string]any{
		"disruptionId":        did,
		"affectedSampleIds":  affectedSamples,
		"replacementPlanIds": replacementPlans,
		"replanStatus":       replanStatus,
	})
}

// handleSearchAuditTrail implements POST /api/search-audit-trail.
func (a *App) handleSearchAuditTrail(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		writeError(w, errCode(405, "method_not_allowed", "POST required"))
		return
	}
	u := currentUser(r)
	if e := requireRole(u, "administrator", "dispatcher"); e != nil {
		writeError(w, e)
		return
	}
	var req struct {
		Query      string `json:"query"`
		EntityType string `json:"entityType"`
		EntityID   string `json:"entityId"`
		ActorID    string `json:"actorId"`
		Action     string `json:"action"`
		Role       string `json:"role"`
		FromTime   string `json:"fromTime"`
		ToTime     string `json:"toTime"`
		Limit      int    `json:"limit"`
		Offset     int    `json:"offset"`
		Order      string `json:"order"`
	}
	if err := decodeJSON(r, &req); err != nil {
		writeError(w, errInvalidJSON)
		return
	}
	if req.Limit <= 0 {
		req.Limit = 50
	}
	if req.Order == "" {
		req.Order = "newest_first"
	}
	q := auditQuery{
		Query:      req.Query,
		EntityType: req.EntityType,
		EntityID:   req.EntityID,
		ActorID:    req.ActorID,
		Action:     req.Action,
		Role:       req.Role,
		Limit:      req.Limit,
		Offset:     req.Offset,
		Order:      req.Order,
	}
	if req.FromTime != "" {
		if t, e := parseTime(req.FromTime, "invalid_time"); e == nil {
			q.FromTime = t
		} else {
			writeError(w, e)
			return
		}
	}
	if req.ToTime != "" {
		if t, e := parseTime(req.ToTime, "invalid_time"); e == nil {
			q.ToTime = t
		} else {
			writeError(w, e)
			return
		}
	}
	res, err := auditSearch(r.Context(), a, q)
	if err != nil {
		writeError(w, errInternal)
		return
	}
	writeData(w, 200, res)
}

