	compliant := req.ObservedTemperatureC >= tmin && req.ObservedTemperatureC <= tmax
	ct := req.ContainerType
	if ct == "" {
		ct = container
	}
	_, err := a.pg.Exec(r.Context(), `UPDATE samples SET sealed=true, sealed_at=now(), status='collected', current_holder_id=$1, container_type=$2 WHERE sample_id::text=$3`,
		u.UserID, ct, sampleID)
	if err != nil {
		writeError(w, errConflict)
		return
	}
	if !compliant {
		_, _ = a.pg.Exec(r.Context(), `UPDATE samples SET exception=$1 WHERE sample_id::text=$2`, toJSONB(map[string]any{"reason": "temperature_out_of_range", "category": "handling", "observedTemperatureC": req.ObservedTemperatureC}), sampleID)
		_, _ = a.pg.Exec(r.Context(), `INSERT INTO exceptions (exception_id, sample_id, reason, category, observed_at) VALUES ($1,$2,'temperature_out_of_range','handling',now())`, uuidStr(), sampleID)
	}
	_, _ = a.pg.Exec(r.Context(), `UPDATE assignments SET status='completed' WHERE assignment_id::text=$1`, req.AssignmentID)
