	labID := req.LaboratoryID
	if labID == "" {
		var aLoc *string
		_ = a.pg.QueryRow(r.Context(), `SELECT assigned_location_id::text FROM users WHERE user_id::text=$1`, u.UserID).Scan(&aLoc)
		labID = strPtr(aLoc)
	}
	_, err := a.pg.Exec(r.Context(), `UPDATE samples SET status='received', received_laboratory_id=$1, current_holder_id=NULL WHERE sample_id::text=$2`, labID, req.SampleID)
	if err != nil {
		writeError(w, errConflict)
		return
	}
	_, _ = a.pg.Exec(r.Context(), `UPDATE journeys SET status='completed' WHERE journey_id=(SELECT active_journey_id FROM samples WHERE sample_id::text=$1)`, req.SampleID)
	_, _ = a.pg.Exec(r.Context(), `UPDATE assignments SET status='completed' WHERE journey_id=(SELECT active_journey_id FROM samples WHERE sample_id::text=$1) AND status NOT IN ('completed','cancelled','expired')`, req.SampleID)
	receivedAt := nowRFC()
	if req.ReceivedAt != "" {
		if t, perr := parseTime(req.ReceivedAt, "invalid_time"); perr == nil {
			receivedAt = rfc(t)
		}
	}
	a.audit(r.Context(), u, "confirm_laboratory_receipt", "sample", req.SampleID, true, map[string]any{"laboratoryId": labID})
	a.emitRealtime(r.Context(), "sample.received", "sample", req.SampleID, map[string]any{"laboratoryId": labID})
	writeData(w, 201, map[string]any{
		"sampleId":     req.SampleID,
		"laboratoryId": labID,
		"status":       "received",
		"receivedAt":   receivedAt,
	})
}

// handleRecordLaboratoryException implements POST /api/record-laboratory-exception.
func (a *App) handleRecordLaboratoryException(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		writeError(w, errCode(405, "method_not_allowed", "POST required"))
		return
	}
	u := currentUser(r)
	if e := requireRole(u, "laboratory_team"); e != nil {
		writeError(w, e)
		return
	}
	var req struct {
		SampleID       string `json:"sampleId"`
		LaboratoryID   string `json:"laboratoryId"`
		Reason         string `json:"reason"`
		ObservedAt     string `json:"observedAt"`
		IdempotencyKey string `json:"idempotencyKey"`
	}
	if err := decodeJSON(r, &req); err != nil {
		writeError(w, errInvalidJSON)
		return
	}
	eid := uuidStr()
	_, _ = a.pg.Exec(r.Context(), `UPDATE samples SET exception=$1, status='exception' WHERE sample_id::text=$2`, toJSONB(map[string]any{"reason": req.Reason, "category": "laboratory", "exceptionId": eid, "laboratoryId": req.LaboratoryID}), req.SampleID)
	_, _ = a.pg.Exec(r.Context(), `INSERT INTO exceptions (exception_id, sample_id, laboratory_id, reason, category, observed_at) VALUES ($1,$2,$3,$4,'laboratory',now())`, eid, req.SampleID, nilIfEmpty(req.LaboratoryID), req.Reason)
	a.audit(r.Context(), u, "record_laboratory_exception", "sample", req.SampleID, true, map[string]any{"reason": req.Reason})
	writeData(w, 201, map[string]any{
		"exceptionId": eid,
		"sampleId":    req.SampleID,
		"status":      "exception",
		"reason":      req.Reason,
	})
}

// handleSetWorkerAvailability implements POST /api/set-worker-availability.
func (a *App) handleSetWorkerAvailability(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		writeError(w, errCode(405, "method_not_allowed", "POST required"))
		return
	}
	u := currentUser(r)
	var req struct {
		WorkerID string `json:"workerId"`
		Available bool  `json:"available"`
		CapacityUnits int `json:"capacityUnits"`
	}
	if err := decodeJSON(r, &req); err != nil {
		writeError(w, errInvalidJSON)
		return
	}
	target := req.WorkerID
	if target == "" {
		target = u.UserID
	}
	if u.ActiveRole != "administrator" && u.ActiveRole != "dispatcher" && target != u.UserID {
		writeError(w, errForbidden)
		return
	}
	_, _ = a.pg.Exec(r.Context(), `INSERT INTO worker_profiles (worker_id, available, capacity_units, updated_at) VALUES ($1,$2,$3,now())
		ON CONFLICT (worker_id) DO UPDATE SET available=EXCLUDED.available, capacity_units=COALESCE(NULLIF(EXCLUDED.capacity_units,0), worker_profiles.capacity_units), updated_at=now()`,
		target, req.Available, req.CapacityUnits)
	a.audit(r.Context(), u, "set_worker_availability", "user", target, true, map[string]any{"available": req.Available})
	writeData(w, 200, map[string]any{
		"workerId":      target,
		"available":     req.Available,
		"capacityUnits": req.CapacityUnits,
	})
}

// handleReadSampleLifecycle implements POST /api/read-sample-lifecycle.
func (a *App) handleReadSampleLifecycle(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		writeError(w, errCode(405, "method_not_allowed", "POST required"))
		return
	}
	var req struct {
		SampleID string `json:"sampleId"`
	}
	if err := decodeJSON(r, &req); err != nil {
		writeError(w, errInvalidJSON)
		return
	}
	u := currentUser(r)
	if e := a.canViewSample(r.Context(), u, req.SampleID); e != nil {
		writeError(w, e)
		return
	}
	lifecycle := a.sampleLifecycle(r.Context(), req.SampleID)
	writeData(w, 200, lifecycle)
}

